SELECT 'moj-all-verified-judgments-review-002-chunk-032' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7bb4becc-65e3-5269-baf4-5d9a70f1209a","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري طلب تسليم دية قتل اخلطأ تعارض التقريرين املرورين مين املدعى عليه على نفي دعوى املدعي إذا اجتمع املباشر واملتسبب أضيف احلكم إلى املباشر إال إذا تعدى املتسبب القول يف التعدي قول منكره احلكم برد دعوى املدعي.","document_number":"34201873","case_number":"23077","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة اجلزائية الرابعة رقم 34258025وتاريخ 1434/07/03ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/30","year":"1434","subject":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري طلب تسليم دية قتل اخلطأ تعارض التقريرين املرورين مين املدعى عليه على نفي دعوى املدعي إذا اجتمع املباشر واملتسبب أضيف احلكم إلى املباشر إال إذا تعدى املتسبب القول يف التعدي قول منكره احلكم برد دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/30 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34201873 :‬‬\n                            ‫َر ْق ُم الدعوى‪23077 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34258025‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n      ‫ديــة ‪ -‬حــادث مــروري ـ مطالبــة بديــة متوفــى بحــادث مــروري ـ طلــب‬\n      ‫تســليم ديــة قتــل اخلطــأ ـ تعــارض التقريريــن املروريــن ـ ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــوى املدعــي ـ إذا اجتمــع املباشــر واملتســبب أضيــف‬\n      ‫احلكــم إلــى املباشــر إال إذا تعــدى املتســبب ـ القــول يف التعــدي قــول‬\n                                            ‫منكــره ـ احلكــم بــرد دعــوى املدعــي‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــال يف كشــاف القنــاع ( ‪ « : ) 131/4‬وإن كانــت إحــدى الســفينتني‬\n      ‫واقفة وكانت األخرى ســائرة واصطدمتا فغرقتا ضمن قيم الســفينة‬\n      ‫الســائرة الســفينة الواقفــة إن فــرط بــأن أمكنــه ردهــا ولــم يفعــل أو لــم‬\n      ‫يكمــل آلتهــا مــن رجــال وحبــال وغيرهمــا ‪ ،‬ألن التلــف حصــل بتقصيــره‬\n      ‫أشــبه مــا لــو نــام وتركهــا ســائرة بنفســها حتــى صدمتهــا ‪ ،‬وأمــا قيــم‬\n      ‫الواقفــة فــا ضمــان عليــه ‪ ،‬ألنــه لــم يوجــد منــه تعــد وال تفريــط ‪،‬‬\n      ‫أشــبه النائــم يف الصحــراء إذا عثــر بــه إنســان فتلــف ‪ ،‬ويأتــي إذا اصطــدم‬\n      ‫ا ‪ ،‬وإن كانــت إحداهمــا منحــدرة‬       ‫نفســان يف كتــاب الديــات مفص ـ ً‬\n      ‫واألخــرى مصعــدة فعلــى صاحبهــا أي املنحــدرة ضمــان املصعــدة ألن‬\n      ‫املنحــدرة تنحــط علــى املصعــدة مــن علــو ‪ ،‬فيكــون ذلــك ســبب ًا لغرقهــا‪،‬‬\n      ‫وال ضمــان علــى قيــم املصعــدة تنزيــا للمنحــدرة منزلــة الســائرة‬\n                                                    ‫واملصعــدة منزلــة الواقفــة أ‪.‬هــ‪.‬‬\n      ‫‪ .2‬قــال ابــن رجــب يف القواعــد ( ‪ ) 274‬القاعــدة ( ‪ « ) 127‬إذا اســتند‬\n‫‪191‬‬\n\f‫إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وتســبب تعلــق الضمــان‬\n                                                  ‫باملباشــرة دون الســبب »‬\n‫‪ .3‬القاعــدة الشــرعية ‪ :‬إذا اجتمــع املباشــر مــع املتســبب أضيــف احلكــم‬\n                                                             ‫إلــى املباشــر ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان بــأن مورثهمــا تــويف بحــادث مــروري ‪ ،‬وأديــن املدعــى‬\n‫عليــه بالتســبب باحلــادث بنســبة ‪ % 75‬وطلبــا أن يســلم املدعــى عليــه ديــة‬\n‫قتــل اخلطــأ مبــا يقابــل هــذه النســبة ‪ ،‬مت طلــب صــك حصــر الورثــة‬\n‫فوجــد انحصــار إرث املتوفــى يف والــده ووالدتــه ـ قامــت والــدة املتوفــى‬\n‫بتوكيــل زوجهــا يف املطالبــة بهــذه الدعــوى ومــا يتعلــق بهــا ـ صــادق‬\n‫املدعــى عليــه علــى وقــوع احلــادث ورفــض احلكــم عليــه ‪ ،‬جــرى االطــاع‬\n‫علــى أوراق املعاملــة فوجــد تقريريــن مروريــن األول منهــا يتضمــن أن‬\n‫النســبة تقــع بحــق املتوفــى بنســبة ‪ % 10‬والثانــي يتضمــن أن النســبة تقــع‬\n‫علــى املتوفــى بنســبة ‪ % 75‬و ‪ % 25‬بحــق املدعــى عليــه ـ أحــد مرافقــي‬\n‫املتوفــى شــهد مــن خــال أوراق القضيــة أن املتوفــى كان يســير بســرعة‬\n‫شــديدة ومت تنبيهــه وصــدم ســيارة املدعــى عليــه مــن اخللــف ـ مت ســؤال‬\n‫املدعــى هــل لديــه بينــة تشــهد علــى املدعــى عليــه باألســباب الــواردة يف‬\n‫التقريــر الثانــي فأجــاب بالنفــي ‪ ،‬ومت إفهامــه بــأن لــه ميــن املدعــى عليــه‬\n‫علــى نفــي مــا ورد يف التقريــر الثانــي فرضــي ميينــه وحلــف املدعــى عليــه‬\n‫اليمــن كمــا طلبــت منــه ‪ ،‬التقريــر األول أقــرب للصــواب ـ ذكــر‬\n‫الفقهــاء أنــه لــو كانــت ســفينة ســائرة وســفينة واقفــة واصطدمتــا ضمــن‬\n‫قيــم الســفينة الســائرة‪ ،‬وهــذه مثــل صــورة احلــادث ـ إذا اجتمــع املباشــر‬\n\n                                                                                      ‫‪192‬‬\n\f      ‫مــع املتســبب أضيــف احلكــم للمباشــر ‪ ،‬إال إذا ثبــت تعــدي املتســبب‬\n      ‫وهــو مــا يؤيــده التقريــر املــروري األول وميــن املدعــى عليــه ـ احلكــم بــرد‬\n      ‫دعــوى املدعــي ـ قــرر املدعــي اعتراضــه علــى احلكــم بالئحــة اعتراضيــة‬\n      ‫فأفهــم بتعليمــات االســتئناف ـ صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 23077‬وتاريــخ ‪1431/5/11‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 31/83275‬يف ‪1431/5/10‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافــق ‪1433/2/13‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي ‪...‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ )...‬واملدعيــة ‪...‬ســعودية مبوجــب‬\n      ‫ســجل مدنــي رقــم (‪ )...‬املعــرف بهــا مــن قبــل زوجهــا املدعــي األول‬\n      ‫بصفتهمــا ورثــة ‪ ...‬مبوجــب صــك حصــر ورثــة صــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 25/119‬وتاريــخ ‪1431/2/29‬ه ـ وادعيــا علــى احلاضــر معــه ‪...‬ميني‬\n      ‫مبوجــب رخصــة إقامــة رقــم (‪ )...‬قائــا يف دعــواه‪ :‬ســبق أن وقــع حــادث‬\n      ‫ســير يف تاريــخ ‪1430/6/6‬ه ـ علــى طريــق خريــص القــدمي بالريــاض‬\n      ‫بــن ســيارتني األولــى مــن نــوع ‪ ...‬موديــل ‪ ...‬رقــم اللوحــة ‪.........‬يســوقها‬\n      ‫مورثنــا ‪...‬ويرافقــه كل مــن ‪ ...‬و‪...‬و‪...‬و‪...‬و‪...‬والثانيــة ســيارة مــن نــوع ‪...‬‬\n      ‫خالطــة موديــل ‪ ...‬رقــم اللوحــة ‪...‬يســوقها املدعــى عليــه هــذا احلاضــر‬\n      ‫ونتــج عــن احلــادث وفــاة مورثنــا ‪ ...‬وأديــن املدعــى عليــه بالتســبب يف‬\n      ‫احلــادث املوصــوف بنســبة ‪ %75‬مبوجــب تقريــر احلــادث املــروري لــذا‬\n      ‫أطلــب إلــزام املدعــى عليــه أن يســلم لنــا ديــة قتــل اخلطــأ ملورثنــا مبــا يقابــل‬\n\n‫‪193‬‬\n\f‫نســبته مــن اإلدانــة هــذه دعوانــا ثــم أضــاف املدعــي األول ‪ ...‬قائــا‪:‬‬\n‫الســيارة األولــى هــي ملكــي وأطلــب تقديــر قيمتهــا قبــل احلــادث وبعــده‬\n‫وإلــزام املدعــى عليــه بتســليمي أرش النقــص بــن القيمتــن هكــذا‬\n‫قــرر وبعرضهــا علــى املدعــى عليــه أجــاب قائــا‪ :‬أطلــب مهلــة للجــواب‬\n‫هكــذا أجــاب وجــرى االطــاع علــى صــك حصــر الورثــة املشــار إليــه‬\n‫أعــاه املتضمــن ثبــوت وفــاة ‪...‬يف ‪1430/6/7‬ه ـ وانحصــار إرثــه يف والده‬\n‫‪...‬ووالدتــه ‪...‬ال وارث لــه ســواهما‪ .‬وقــررت املدعيــة إقامــة زوجهــا املدعــي‬\n‫وكيــا عنهــا يف هــذه الدعــوى بصفتهــا املذكــورة أعــاه ينــوب عنهــا‬\n‫يف املرافعــة واملدافعــة واملطالبــة واإلقــرار واإلنــكار والصلــح والتنــازل‬\n‫وتقــدمي البينــات وطلــب اليمــن وردهــا والقناعــة باحلكــم واالعتــراض‬\n‫عليــه وتقــدمي لوائــح االعتــراض‪ .‬ويف يــوم األحــد املوافــق ‪1433/6/22‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــة ووكالــة ‪ ...‬واملدعــى عليــه‬\n‫‪ ......‬وبســؤاله عــن جوابــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي مــن وقــوع‬\n‫احلــادث املوصــوف بينــي وبــن ابنــه املذكــور فصحيــح ومــا ذكــره مــن‬\n‫وفــاة ابنــه فــا أدري ومــا ذكــره أن مســؤولية احلــادث تقــع علــي بنســبة‬\n‫‪ %75‬فــا أدري وأرفــض احلكــم علــي مبــا طلــب املدعــي هكــذا أجــاب‬\n‫وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى ملــف التحقيــق يف‬\n‫احلــادث املوصــوف واملتضمــن أنــه نتــج عــن احلــادث وفــاة قائــد الســيارة ‪....‬‬\n‫‪ ...‬ومرافقــه ‪...‬واملســؤولية تقــع علــى قائــد ‪... ....‬بنســبة ‪ %100‬لألســباب‬\n‫التاليــة‪ -1 :‬الســرعة العاليــة‪ -2 .‬عــدم االنتبــاه‪ -3 .‬االنشــغال عن القيادة‪.‬‬\n    ‫‪ -4‬عــدم أخــذ احليطــة واحلــذر‪ -5 .‬عــدم التأكــد مــن خلــو الطريــق‪.‬‬\n‫‪ -6‬وجــود إقــرار خطــي علــى أحــد املرافقــن‪ .‬واملنتهــي بتوقيــع جنــدي‬\n‫أول ‪ ...‬ومــازم أول ‪...‬ووكيــل رقيــب ‪ ....‬أهــ‪ .‬وجــرى االطــاع علــى إقــرار‬\n\n\n                                                                                       ‫‪194‬‬\n\f      ‫خطــي علــى امللــف نفســه وهــذا نصــه‪ :‬نعــم أنــا املدعــو ‪ ...‬أقــر بأننــي‬\n      ‫مرافــق مــع ســائق ‪ ....‬الســوبر بــان وراكــب يف املقعــد اخللفــي وكنــا‬\n      ‫نســير علــى طريــق خريــص القــدمي باجتــاه الشــرق وكان الســائق ‪...‬يقــود‬\n      ‫بســرعة عاليــة وقمنــا بتنبيهــه عــن وجــود شــاحنة أمامنــا وقــام مبســك‬\n      ‫الفرامــل وصدمنــا بهــا مــن اخللــف املقــر مبــا فيــه ‪...‬بصمتــه شــاهد علــى‬\n      ‫اإلفــادة منــدوب احلــوادث يف الشــرطة العســكرية جنــدي أول ‪ ....‬كمــا‬\n      ‫جــرى االطــاع علــى تقريــر حــادث لفــة رقــم ‪ 26‬واملتضمــن الوقــوف‬\n      ‫علــى موقــع احلــادث املوصــوف واملعاينــة علــى الطبيعــة ورأت اللجنــة أن‬\n                      ‫املســؤولية تقــع بنســبة ‪ %75‬علــى الســائق ‪ ...‬مينــي اجلنســية‬\n      ‫لألســباب التاليــة‪ -1 :‬عــدم التأكــد مــن خلــو الطريــق‪ -2 .‬عــدم‬\n      ‫التــزام املســار الصحيــح‪ -3 .‬اعتــراض خــط ســير الســيارة األخــرى‪.‬‬\n      ‫وتقــع بنســبة ‪ %25‬علــى الســائق ‪...‬ســعودي اجلنســية لألســباب التاليــة‪:‬‬\n      ‫‪ -1‬الســرعة الزائــدة‪ -2 .‬عــدم أخــذ احليطــة واحلــذر‪ .‬واملنتهــي بتوقيــع‬\n      ‫رقيــب أول ‪...‬ورقيــب أول ‪...‬ورئيــس اللجنــة ومتابعــة احلــوادث الرائــد ‪....‬‬\n      ‫أهــ‪ .‬وبعرضــه علــى الطرفــن أجــاب املدعــي قائــا‪ :‬أمــا التقريــر األول‬\n      ‫فأنــا قدمــت اعتراضــا عليــه يف حينــه لــدى املــرور وخرجــت جلنــة أخــرى‬\n      ‫وكتبــت التقريــر الثانــي وأنــا أمتســك بالتقريــر الثانــي ومــا جــاء يف‬\n      ‫اإلقــرار اخلطــي للمرافــق ‪...‬فــا أدري عنــه هكــذا أجــاب وأجــاب املدعى‬\n      ‫عليــه قائــا‪ :‬أنــا أرفــض التقريــر الثانــي وأمتســك بالتقريــر األول هكــذا‬\n      ‫أجــاب‪ .‬ويف يــوم األربعــاء املوافــق ‪1433/12/22‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي أصالــة ووكالــة ‪ ...‬واملدعــى عليــه ‪...‬وبســؤال‬\n      ‫املدعــي عــن اســتمارة الســيارة التــي وقــع عليهــا احلــادث املــروري أبــرز‬\n      ‫وثيقــة ملكيــة مركبــة باســمه برقــم هيــكل‪ ...‬نــوع ‪ ...‬ســنة الصنــع ‪...‬‬\n\n\n‫‪195‬‬\n\f‫اللــون ‪ ...‬رقــم اللوحــة (‪ )...‬وبســؤال املدعــي هــل مت تقديــر قيمــة الســيارة‬\n‫قبــل احلــادث وبعــده فأجــاب قائــا ‪ :‬لــم يتــم تقديــر قيمــة الســيارة حتــى‬\n‫اآلن وال زالــت التلفيــات علــى حالهــا بعــد احلــادث وهــي يف حجــز املــرور‬\n‫هكــذا أجــاب لــذا أمــرت بالكتابــة إلــى إدارة مــرور الريــاض تقديــر‬\n‫قيمــة الســيارة قبــل احلــادث وبعــده لــدى ثــاث معــارض ســيارات‪ .‬ويف يــوم‬\n‫الثالثــاء ‪1434/04/30‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــة‬\n‫ووكالــة ‪...‬واملدعــى عليــه ‪...‬ووردنــا جــواب مديــر إدارة مــرور الريــاض‬\n‫برقــم ‪ 1832/11/2/7‬وتاريــخ بــدون املتضمــن أن املركبــة (‪ )....‬مت‬\n‫بيعهــا عــن طريــق اللجنــة املختصــة علــى مكبــس احلديــد‪ .‬أ‪.‬ه ـ وبعــرض‬\n‫تقريــر احلــادث الثانــي علــى املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــر فيــه‬\n‫مــن إدانتــي مــن عــدم التأكــد مــن خلــو الطريــق وعــدم إلتزامــي املســار‬\n‫الصحيــح واعتــراض ســير الســيارة اآلخــرى فهــذا غيــر صحيــح هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬بــل مــا ذكــر يف تقريــر‬\n‫احلــادث الثانــي هــو الصحيــح هكــذا أجــاب وبســؤال املدعــي هــل لديــه‬\n‫بينــة تشــهد علــى املدعــى عليــه باألســباب املذكــورة يف تقريــر احلــادث‬\n‫أجــاب قائــا‪ :‬ليــس لــدي بينــة هكــذا أجــاب لــذا أفهمتــه أن لــه ميــن‬\n‫املدعــى عليــه علــى نفــي ذلــك فقبلهــا واســتعد املدعــى عليــه ببذلهــا‬\n‫فأذنــت لــه وحلــف قائــا‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن مــا ذكــر‬\n‫يف تقريــر احلــادث أننــي لــم أتأكــد مــن خلــو الطريــق ولــم ألتــزم املســار‬\n‫الصحيــح واعترضــت خــط ســير الســيارة اآلخــرى فهــذا غيــر صحيــح‬\n‫بــل تأكــدت مــن خلــو الطريــق وألتزمــت املســار الصحيــح هكــذا حلــف‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى التقريــر‬\n‫األول للحــادث والتقريــر الثانــي للحــادث ومبــا أن التقريــر األول للحــادث‬\n\n\n                                                                                      ‫‪196‬‬\n\f                                                                     ‫أقــرب للصــواب‬\n      ‫ألن صــورة احلــادث شــبيهة بالصــورة التــي ذكرهــا يف كشــاف القنــاع‬\n      ‫(‪ )131/4‬قــال‪( :‬وإن كانــت إحــدى الســفينتني واقفــة وكانــت األخــرى‬\n      ‫ســائرة واصطدمتــا فغرقتــا ضمــن قيــم الســفينة الســائرة الســفينة‬\n      ‫الواقفــة إن فــرط بــأن أمكنــه ردهــا ولــم يفعــل أو لــم يكمــل آلتهــا مــن‬\n      ‫رجــال وحبــال وغيرهمــا ألن التلــف حصــل بتقصيــره أشــبه مــا لــو نــام‬\n      ‫وتركهــا ســائرة بنفســها حتــى صدمتهــا وأمــا قيــم الواقفــة فــا ضمــان‬\n      ‫عليــه ألنــه لــم يوجــد منــه تعــد وال تفريــط أشــبه النائــم يف الصحــراء إذا‬\n      ‫عثــر بــه إنســان فتلــف ويأتــي إذا اصطــدم نفســان يف كتــاب الديــات‬\n      ‫مفصــا ‪ .‬وإن كانــت إحداهمــا منحــدرة واألخــرى مصعــدة فعلــى‬\n      ‫صاحبهــا أي‪ :‬املنحــدرة ضمــان املصعــدة ألن املنحــدرة تنحــط علــى‬\n      ‫املصعــدة مــن علــو فيكــون ذلــك ســببا لغرقهــا وال ضمــان علــى قيــم‬\n      ‫املصعــدة تنزيــا للمنحــدرة منزلــة الســائرة وللمصعــدة منزلــة الواقفــة)‪.‬‬\n      ‫أه ـ والســيارة التريــا يف ســيرها ببــطء أشــبه بالواقفــة كمــا أن ســائق‬\n      ‫الســيارة ‪ ....‬باشــر التلــف بصدمــه للســيارة التريــا مــن اخللــف وقــد كان‬\n      ‫ميكنــه تــايف التصــادم باالنتبــاه وأخــذ احليطــة واحلــذر وتــرك الســرعة‬\n      ‫ومبــا أن الطرفــان اختلفــا يف التعــدي حصــل ممــن فالقــول قــول منكــره‬\n      ‫وهــو ســائق التريــا ألنــه ُصــدم مــن اخللــف مــن قبــل الســيارة ‪ ....‬وهــو‬\n      ‫منكــر للخــروج املفاجــئ وحلــف اليمــن علــى نفــي ذلــك كمــا أن‬\n      ‫القاعــدة الشــرعية إذا اجتمــع املباشــر مــع املتســبب أضيــف احلكــم إلــى‬\n      ‫املباشــر قــال ابــن رجــب يف القواعــد ص (‪ )274‬القاعــدة (‪( :)127‬إذا‬\n      ‫اســتند إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وتســبب تعلــق‬\n      ‫الضمــان باملباشــرة دون الســبب)‪ .‬أه ـ وال يغلــب الســبب علــى املباشــرة إال‬\n\n\n‫‪197‬‬\n\f‫إذا تعــدى املتســبب وهــو مــا ينفيــه التقريــر املــروري األول وميــن املدعــى‬\n‫عليــه ويتفــق مــع مــا ذكــره الفقهــاء مــن تصــادم الســفينة الســائرة مــع‬\n‫الواقفــة لــذا قــررت رد دعــوى املدعــي وبــه حكمــت وبإعــان احلكــم‬\n‫قــرر املدعــي املعارضــة وطلــب االســتئناف وســلم صــورة احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يومــا فــإن مضــت املــدة ولــم يقــدم الئحــة‬\n‫اعتراضــه ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                    ‫حــرر يف ‪1434/04/30‬ه ـ‬\n‫ويف يــوم الثالثــاء ‪1434/07/25‬ه ـ افتتحــت اجللســة بنــاء علــى ورود‬\n‫املعاملــة بشــرح رئيــس احملكمــة علــى القيــد رقــم ‪341305820‬‬\n‫وتاريــخ ‪1434/07/18‬ه ـ وبرفقهــا خطــاب رئيــس محكمــة االســتئناف‬\n‫بالريــاض رقــم ‪ 341305820‬وتاريــخ ‪1434/07/12‬ه ـ وبرفقهــا قــرار‬\n‫الدائــرة اجلزائيــة الرابعــة رقــم ‪ 34258025‬وتاريــخ ‪1434/07/03‬ه ـ‬\n‫واملتضمــن املصادقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n                                  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائية الرابعة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪ 34237071‬وتاريــخ‬\n‫‪ 1434 /05/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n             ‫باحملكمــة الشــيخ ‪.../‬املســجل برقــم ‪ 34201873‬وتاريــخ‬\n‫‪ 1434/ 04 /30‬ه ـ اخلــاص بدعــوى ‪...‬ضــد‪... /‬بشــأن حــادث مــروري‬\n‫علــى النحــو املوضــح بالصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل بــه و بدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n\n\n                                                                                    ‫‪198‬‬\n\f      ‫وأوراق املعاملــة قــررت الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلته‬\n      ‫ال وذلــك حســب املادة‬‫إلــى إثبــات اإلدانــة مــن عدمهــا قبــل احلكــم مســتقب ً‬\n      ‫‪ 3‬و ‪ 174‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬و اهلل املوفــق وصلــى اهلل علــى‬\n                                                ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪199‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":191,"source_page_end":199,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d74e11d3c63b09143ef1ad6e63fe0fb173b613d4acecffdadac284c116ca4b0c","normalized_text_hash":"f1718f7fe1e9cd10e6596ac4965e9386e96d8d7d8f7a7806598696112bb2fddf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p191-34201873"},{"id":"db023c61-1b6b-5b19-a67a-0b96cbe03204","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -مطالبة بدية مورث توفى بحادث مروري -دفع املدعى عليه بأن شركة التأمن هي املسؤولة عن دفع الدية -املباشرة مقدمة على التسبب -احلكم بإلزام املدعى عليه بدفع الدية حسب نسبة اإلدانة التي عليه -للمدعى عليه الرجوع على شركة التأمن أو","document_number":"33272212","case_number":"50245","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"دية -مطالبة بدية مورث توفى بحادث مروري -دفع املدعى عليه بأن شركة التأمن هي املسؤولة عن دفع الدية -املباشرة مقدمة على التسبب -احلكم بإلزام املدعى عليه بدفع الدية حسب نسبة اإلدانة التي عليه -للمدعى عليه الرجوع على شركة التأمن أو","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/22 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33272212 :‬‬\n                       ‫َر ْق ُم الدعوى‪50245 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3423835‬تاريخه‪1434/1/26 :‬هـ‬\n\n\n ‫ديــة ‪ -‬مطالبــة بديــة مــورث توفــى بحــادث مــروري ‪ -‬دفــع املدعــى عليــه‬\n ‫بــأن شــركة التأمــن هــي املســؤولة عــن دفــع الديــة‪ -‬املباشــرة مقدمــة‬\n ‫علــى التســبب‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع الديــة حســب نســبة‬\n ‫اإلدانــة التــي عليــه‪ -‬للمدعــى عليــه الرجــوع علــى شــركة التأمــن أو‬\n ‫قصــر ‪.‬‬\n      ‫العاقلــة بالديــة‪ -‬رفــع الدعــوى إلــى محكمــة االســتئناف لوجــود ّ‬\n\n\n\n ‫قــال ابــن رجــب ـ رحمــه اهلل ـ يف القواعــد ( قاعــدة ‪ « ) 127‬إذا اســتند‬\n ‫إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وســبب ‪ ،‬تعلــق الضمــان‬\n ‫باملباشــرة دون الســبب ‪ ،‬إال إذا كانــت املباشــرة مبنيــة علــى الســبب‬\n ‫وناشــئة عنــه ســواء كانــت ملجئــة ثــم إن كانــت املباشــرة واحلالــة هــذه‬\n ‫ال عــدوان فيهــا بالكليــة اســتقل الســبب وحــده بالضمــان ‪ ،‬وإن كان‬\n                          ‫فيهــا عــدوان شــاركت الســبب الضمــان » ‪.‬‬\n\n\n\n\n ‫أقامــت املدعيتــان باألصالــة عــن نفســيهما وبالوكالــة عــن غيرهمــا‬\n ‫القصــر دعــوى تســليم ديــة مورثهمــا الــذي‬\n                                            ‫ّ‬   ‫واألولــى بواليتهــا عــن أبنائهــا‬\n ‫توفــى نتيجــة حــادث مــروري ‪ -‬صــادق املدعــى عليــه علــى ذلــك إال أنــه‬\n ‫رفــض تســليم الديــة مبــرر ًا أن عليهــم مطالبــة شــركة التأمــن‪ ،‬وقــد‬\n\n                                                                                      ‫‪200‬‬\n\f      ‫جــرى نظــر التقريــر املــروري والــذي أســند ‪ %75‬مــن اخلطــأ إلــى املدعــى‬\n      ‫عليــه وقــد نازعــت املدعيتــان يف نســبة اخلطــأ ثــم عادتــا وقنعتــا بهــذه‬\n      ‫النســبة ‪ ،‬وافــق املدعــى عليــه علــى تســليم الديــة املقــررة وأنــه ســيعود‬\n      ‫علــى شــركة التأمــن بعــد ذلــك وقنــع جميــع األطــراف باحلكــم وجــرى‬\n      ‫قصــر وجــرى التصديــق‬  ‫رفــع الدعــوى إلــى محكمــة االســتئناف لوجــود ّ‬\n                                                         ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 50245‬وتاريــخ ‪ 1431/11/25‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 31195226‬وتاريــخ ‪1431/11/22‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1433/3/12‬أفتتحــت اجللســة وقــد عــادت املعاملــة مــن‬\n      ‫مــرور منطقــة الريــاض بعــد شــطبها للمــرة األولــى بكتابهــم رقــم ‪.......‬‬\n      ‫يف ‪1433/1/17‬ه ـ املتضمــن أنــه قــد مت إبــاغ املدعيــن مبتابعــة القضية‬\n      ‫ويف هــذه اجللســة حضــرت ‪ .......‬ســورية اجلنســية حتمــل جــواز ســفر رقــم‬\n      ‫‪ .......‬والــذي تنتهــي الزيــارة بــه بتاريــخ ‪1433/4/4‬ه ـ بصفتهــا أصيلــة عن‬\n      ‫نفســها ووليــة علــى القاصــر ‪ .......‬مبوجــب صــك الواليــة وحصــر الورثــة‬\n      ‫الصــادر مــن احملكمــة الشــرعية بحمــاه برقــم ‪ .......‬يف ‪2011/5/25‬م‬\n      ‫واملصــادق عليــه مــن وزارتــي اخلارجيــة والعــدل يف اململكــة العربيــة‬\n      ‫الســعودية بتاريــخ ‪1433/3/8‬ه ـ واملتضمــن إقامــة املدعيــة وليــة علــى‬\n      ‫القاصــر ‪ .......‬املولــود يف ‪ 1997/1/1‬كمــا تضمــن انحصــار ورثــة‬\n      ‫‪ .......‬يف زوجتــه املدعيــة ‪ .......‬واوالده ‪ .......‬و ‪ .......‬و ‪ .......‬و ‪ .......‬و‬\n\n‫‪201‬‬\n\f‫‪ .......‬و ‪ .......‬ال وارثــه لــه ســواهم كمــا أبــرزت وكالتهــا عــن ‪ .......‬و‬\n‫‪ .......‬و ‪ .......‬أوالد ‪ .......‬مبوجــب الصــادرة مــن كاتــب العــدل بحمــاه‬\n‫رقــم ‪ .......‬جلــد ‪ 2636‬يف ‪1432/7/25‬ه ـ واملصــادق عليــه مــن وزارتــي‬\n‫اخلارجيــة والعــدل يف اململكــة العربيــة الســعودية بتاريــخ ‪1433/3/8‬ه ـ‬\n‫ووكالتهــا عــن ‪ .......‬الصــادرة مــن كاتــب العــدل بحمــاه برقــم ‪.......‬‬\n‫يف ‪ 2648‬يف ‪1432/11/14‬ه ـ واملصــادق عليــه مــن وزارتــي اخلارجيــة‬\n‫والعــدل يف اململكــة العربيــة الســعودية بتاريــخ ‪1433/3/8‬ه ـ وقــد‬\n‫تضمنــت الوكالتــان أن لهــا احلــق يف املطالبــة واســتالم ديــة مورثهــم‬\n‫‪ .......‬كمــا حضــرت ‪ .......‬ســورية اجلنســية حتمــل رخصــة اإلقامــة رقــم‬\n‫‪ .......‬واملعــرف باملدعيتــن احلاضــر ‪ .......‬حامــل الســجل املدنــي رقــم‬\n‫‪ .......‬ولــم يحضــر املدعــى عليــه ولــم يظهــر تبلغــه مبوعــد هــذه اجللســة‬\n‫وقــد قــررت املدعيتــان أنهمــا ال يعرفــان محــل إقامــة املدعــى عليــه‬\n‫هكــذا قررتــا هــذا وســتجري الكتابــة منــا إلمــارة منطقــة الريــاض‬\n‫إلبــاغ املدعــى عليــه مبوعــد اجللســة القادمــة بنــاء علــى املــادة ‪/18‬ط مــن‬\n‫نظــام املرافعــات الشــرعية ويف جلســة أخــرى بتاريــخ ‪ 1433/03/28‬ه ـ‬\n‫حضــرت املدعيتــان واملعــرف بهمــا احلاضــرون يف اجللســة املاضيــة كمــا‬\n‫حضــر املدعــى عليــه ‪ .......‬حامــل بطاقــة الهويــة الوطنيــة رقــم ‪ .......‬وقــد‬\n‫ادعــت املدعيتــان قائلتــان إن هــذا احلاضــر املدعــى عليــه ‪ .......‬قــد حصــل‬\n‫بينــه وبــن مورثنــا ‪ .......‬حــادث تصــادم بحــي النســيم مبدينــة الريــاض‬\n‫عــام ‪1430‬ه ـ تقريبــا نتــج عنــه وفــاة مورثنــا وقــد حضــر املــرور للموقــع‬\n‫وقــرر نســبة احلــادث ب ــنسبة ‪ %75‬علــى املدعــى عليــه نطلــب احلكــم علــى‬\n‫املدعــى عليــه بتســليمنا ديــة مورثنــا املســلم هــذه دعوانــا وبعــرض ذلــك‬\n‫علــى املدعــى عليــه مــا ذكرتــه املدعيتــان يف دعواهمــا فهــو صحيــح‬\n\n\n                                                                                      ‫‪202‬‬\n\f      ‫جملــة وتفصيــا وقــد حضــرت لقســم املــرور ومت إيقــايف ثــم أخلــي‬\n      ‫ســبيلي مبوجــب بطاقــة تأمــن علــى شــركة ‪ ....‬ثــم مت اســتدعائي مــن‬\n      ‫قبــل القاضــي باحملكمــة املســتعجلة ومت عــرض النســبة علــي وتصديــق‬\n      ‫موافقتــي عليهــا ومــن ثــم خرجــت وحتــى اليــوم كنــت أظــن أنهــم قــد‬\n      ‫انتهــوا مــن املوضــوع وأنــا ال مانــع لــدي مبــا أقــررت بــه مبوجــب بطاقــة‬\n      ‫التأمــن ولــن أســلمهم املبلــغ املدعــى بــه وعليهــم مطالبــة التأمــن هكــذا‬\n      ‫أجــاب هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة والتــي مــن ضمنهــا‬\n      ‫تقريــر إدارة املــرور املرفــق باملعاملــة علــى لفــة ‪ 10‬رقــم ‪ .......‬تاريــخ‬\n      ‫‪1431/9/2‬ه ـ واملتضمــن نــوع احلــادث ‪ :‬دهــس ‪ .‬زمــن احلــادث وتاريخــه ‪:‬‬\n      ‫الســاعة ‪ 11.50‬م يــوم اجلمعــة املوافــق ‪1430/8/30‬ه ـ مــكان احلــادث ‪:‬‬\n      ‫حــي النســيم ‪ .‬مــن قبــل الســائق ‪ :‬الطــرف األول ‪ ....... /‬ســعودي اجلنســية‬\n      ‫( ‪ ) .......‬الطــرف الثانــي املاشــي ‪ ....... /‬ســوري اجلنســية ( ‪ ) .......‬نتائــج‬\n      ‫احلــادث ‪ :‬وفــاة املاشــي ‪ ....... /‬مســئولية احلــادث وبيانــات أســباب اإلدانــة‬\n      ‫‪ :‬تقــع نســبة ‪ %75‬علــى الطــرف األول ‪ ....... /‬األســباب اآلتيــة ‪ -1‬عــدم‬\n      ‫االنتبــاه ‪ -2‬عــدم أخــذ احليطــة واحلــذر ‪ -3‬عــدم تــايف احلــادث وتقــع نســبة‬\n                                           ‫‪ %25‬علــى املاشــي ‪ ....... /‬األســباب اآلتيــة‬\n      ‫‪ -1‬عــدم التأكــد مــن خلــو الطريــق ‪ -2‬عــدم االنتبــاه أ‪.‬ه ـ وبعــرض‬\n      ‫التقريــر عليهمــا قالــت املدعيتــان إن هــذه النســبة قليلــة فاملدعــى عليــه‬\n      ‫يتحمــل نســبة ‪ %100‬مــن احلــادث هكــذا أجابتــا كمــا قــرر املدعــى عليه‬\n      ‫قائــا بــأن النســبة عاليــة وقــد صادقــت عليهــا عنــد املــرور ظنــا منــي بــأن‬\n      ‫شــركة التأمــن هــي التــي ستســلم املبلــغ ولكــن اخلطــأ مــن مــورث‬\n      ‫املدعــن بقطعــه الطريــق املخصــص للســيارات هكــذا أجــاب لــذا قررت‬\n      ‫الكتابــة إلدارة املــرور لإلفــادة عمــا جــاء يف إجابــات املدعيتــان واملدعــى‬\n\n\n‫‪203‬‬\n\f‫عليــه املرصــودة أعــاه ويف جلســة أخــرى بتاريــخ ‪ 1433/05/25‬هـ وفيها‬\n‫حضــرت املدعيــة ‪ .......‬أصالــة ووكالــة وواليــة كمــا حضــرت ‪.......‬‬\n‫واملعــرف بهمــا مــن قبــل ‪ .......‬احلاضــرون يف اجللســة الســابقة كما حضر‬\n‫املدعــى عليــه احلاضــر يف اجللســة الســابقة هــذا وقــد قــرر احلاضــرون أنهم‬\n‫عدلــوا عــن اإلســتمرار يف الكتابــة لقســم املــرور املشــار لــه يف اجللســة‬\n‫الســابقة وذلــك ملــا حصــل مــن اإلتفــاق بــن جميــع األطــراف علــى التقريــر‬\n‫الــوارد ســابقا مــن إدارة املــرور رقــم ‪ .......‬وتاريــخ ‪1431/09/02‬ه ـ‬\n‫واملرفــق ضمــن أوراق املعاملــة واملتضمــن (أن مســؤلية احلــادث تقــع بنســبة‬\n‫‪ %75‬علــى الطــرف األول ‪ .......‬وتقــع بنســبة ‪ %25‬علــى املاشــي ‪....... /‬‬\n‫)أ‪.‬ه ـ واملشــار لــه يف اجللســة الســابقة هــذا كمــا جــرى اإلطــاع علــى‬\n‫القــرار الصــادر مــن احملكمــة اجلزئيــة بالريــاض مــن املكتــب القضائــي‬\n‫الثالــث والعشــرين رقــم القــرار ‪ 2300104523008310006‬وتاريــخ‬\n‫‪1431/02/25‬ه ـ املجلــد ‪ 1‬واملتضمــن ( ثبــوت إدانــة املدعــى عليــه ‪.......‬‬\n‫مبســؤوليته عــن احلــادث بنســبة‪ %75‬واملفهــم فيــه بــأن عليــه كفــارة قتــل‬\n‫اخلطــأ والــذي قــرر فيــه قناعتــه مبــا حكم)أ‪.‬ه ـ وقــد قــرر املدعــى عليــه‬\n‫قائــا أصــادق علــى إدانتــي بنســبة ‪ %75‬مــن احلــادث ومســتعد لتســليم‬\n‫املدعــن الديــة وســأطالب شــركة التأمــن بذلــك بعــد صــدور احلكــم‬\n‫علــي هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرره‬\n‫جميــع األطــراف مــن قناعتهــم بتقريــر املــرور املشــار إليــه أعــاه وملــا جــاء‬\n‫يف القاعــدة ( ‪ ) 127‬مــن قواعــد ابــن رجــب ونصهــا ( إذا اســتند إتــاف‬\n‫أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وســبب تعلــق الضمــان باملباشــرة‬\n‫دون الســبب إال إذا كانــت املباشــرة مبنيــة علــى الســبب وناشــئة عنــه‬\n‫ســواء كانــت ملجئــة ثــم إن كانــت املباشــرة واحلالــة هــذه ال عــدوان‬\n\n\n                                                                                        ‫‪204‬‬\n\f      ‫فيهــا بالكليــة اســتقل الســبب وحــده بالضمــان وإن كان فيهــا عــدوان‬\n      ‫شــاركت الســبب يف الضمــان ) أ ه ـ فقــد ألزمــت املدعــى عليــه ‪.......‬‬\n      ‫أن يســلم مبــا نســبته ‪ %75‬مــن ديــة قتــل اخلطــأ املســلم للمدعيتــان أصالــة‬\n      ‫ووكالــة وواليــة وقدرهــا مائتــان وخمســة وعشــرون ألــف ريــال تقســم‬\n      ‫بــن ورثــة ‪ .......‬حســب امليــراث الشــرعي وبــه حكمــت كمــا أفهمــت‬\n      ‫املدعــى عليــه بــأن لــه مطالبــة عاقلتــه بقيمــة الديــة املذكــورة أعــاه‬\n      ‫وبعــد إعــان احلكــم قنــع بــه جميــع األطــراف وقــررت بعثــه حملكمــة‬\n      ‫اإلســتئناف لتدقيقــه لوجــود قاصــر ولــم يحكــم بكامــل الديــة‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1433/05/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/08/14‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 331114459‬وتاريــخ ‪1433/7/20‬ه ـ واملرفــق بــه قــرار الدائــرة األولــى‬\n      ‫لتمييــز القضايــا اجلزائيــة برقــم ‪ 33338478‬وتاريــخ ‪1433/07/13‬ه ـ و‬\n      ‫نــص احلاجــة منــه مــا يلــي ( لوحــظ أن فضيلتــه ذكــر يف الســطر الثامــن‬\n      ‫و التاســع مــن الصفحــة األولــى مــن الصــك انحصــار إرث املتوفــى علــي‬\n      ‫املذكــور يف زوجتــه وأوالده املذكوريــن ال وارث لــه ســواهم بينمــا‬\n      ‫يوجــد يف صــك حصــر اإلرث الــذي أشــار إليــه فضيلتــه أن والــدة‬\n      ‫املتوفــى مــن ضمــن الورثــة ولــم يوجــد مــا يثبــت حضورهــا أو توكيلهــا‬\n      ‫فعلــى فضيلتــه إجــراء مــا يلــزم و تصحيــح اخلطــأ يف الســطر اخلامــس‬\n      ‫مــن الصفحــة األولــى و املعلــم عليــه بقلــم الرصــاص و إيضــاح نصيــب‬\n      ‫كل وارث مــن الديــة كمــا إن إفهامــه بالرجــوع علــى العاقلــة فيــه نظــر‬\n      ‫مــع مــا ذكــره مــن وجــود بطاقــة تأمــن كمــا أن فضيلــة القاضــي لــم‬\n\n\n‫‪205‬‬\n\f‫يقســم الديــة علــى الورثــة ويوضــح ســهم أو نصيــب كل وارث ومــن يســلم‬\n‫لــه نصيــب القاصر)أ‪.‬ه ـ وفيهــا حضــرت املدعيــة أصالــة ووكالــة وواليــة‬\n‫‪ .......‬واملدعيــة ‪ .......‬واملعــرف بهمــا مــن قبــل ‪ .......‬احلاضــر يف اجللســة‬\n‫املاضيــة كمــا حضــر املدعــى عليــه‪ ،‬وجــرى تصحيــح اخلطــأ الكتابــي‬\n‫يف الصــك ‪ ،‬وأمــا الرجــوع علــى العاقلــة فلــم يظهــر لــي ســوى مــا أجريتــه‬\n‫‪ ،‬وجــرى االطــاع علــى صــك حصــر الورثــة فوجدنــا أن مــن ضمــن‬\n‫ورثتــه والدتــه ‪ .............‬وقــررت املدعيــة قائلــة‪ :‬إن أم مورثنــا ال تســتطيع‬\n‫احلضــور وال التوكيــل الضطــراب األوضــاع يف ســوريا نطلــب تســليمنا‬\n‫نصيبنــا مــن الديــة دون نصيــب األم وهــو مبلــغ وقــدره ســبعة وثالثــن‬\n‫ألفــا وخمســمائة ريــال وكذلــك تســليمي نصيــب القاصــر ‪ .......‬للنفقــة‬\n‫عليــه منــه هكــذا قــررت‪ .‬لــذا فقــد رجعــت عمــا حكمــت بــه ســابقا‬\n‫وألزمــت املدعــى عليــه بــأن يســلم للمدعــن أصالــة ووكالــة وواليــة مــن‬\n‫ديــة مورثهــم وهــو مبلــغ وقــدره مائــة وســبعة وثمانــون ألفــا وخمســمائة‬\n‫ريــال‪ ،‬نصيــب الزوجــة منــه مبلغــا وقــدره ثمانيــة وعشــرون ألفــا ومائــة‬\n‫وخمســة وعشــرون ريــاال‪ ،‬ونصيــب كل واحــد مــن األبنــاء مبلــغ وقــدره‬\n‫واحــد وثالثــون ألفــا وثمامنائــة وخمســة وســبعني ريــاال‪ ،‬ونصيــب كل‬\n‫بنــت مبلــغ وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون ريــاال‬\n‫ونصــف الريــال‪ .‬وتســليم نصيــب القاصــر لوليتــه املدعيــة ‪ .......‬وبــه‬\n‫حكمــت وبعــد إعالنــه قنعــوا بــه وقــررت إحلــاق ذلــك بالصــك وســجله‬\n‫وإعــادة املعاملــة حملكمــة االســتئناف‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/14‬هـ‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم االثنــن ‪1433/12/20‬ه ـ افتتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف بكتابهــم رقــم‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪ 33164340‬يف ‪1433/11/2‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى‬\n      ‫برقــم ‪ 33426238‬يف ‪1433/10/15‬ه ـ ونــص احلاجــة منــه‪( :‬وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قــرار الدائــرة رقــم ‪ 333387478‬وتاريــخ ‪1433/7/13‬ه ـ لوحظ أن‬\n      ‫صــك حصــر الوراثــة والوصايــة والوكالــة غيــر مكتملــة يف تصديقاتهــا‬\n      ‫حســب التعليمات من وزارة اخلارجية الســعودية ووزارة العدل الســعودية)‬\n      ‫اهــ‪ .‬وعليــه جنيــب أصحــاب الفضيلــة بــأن الــوكاالت وحصــر الورثــة‬\n      ‫والواليــة مصدقــة مــن وزارتــي اخلارجيــة والعــدل الســعوديتني‪ ،‬ولكــن‬\n      ‫لــم تصــور التصديقــات ألنهــا يف خلــف الصكــوك‪ ،‬وقــد مت تصويرهــا‬\n      ‫‪ ،‬وقــررت رفــع املعاملــة حملكمــة االســتئناف إلكمــال الــازم حســب‬\n      ‫املتبــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331958164‬وتاريــخ ‪1433/12/22‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪....... /‬‬\n      ‫املسجل برقم ‪ 33272212‬وتاريخ ‪1433/5/29‬هـ اخلاص بدعوى‪ /‬ورثة‬\n      ‫‪ .......‬ضــد ‪ .......‬بشــأن طلبهــم النســبة املقــررة مــن ديــة مورثهــم املوضحــة‬\n      ‫بالصــك واملتضمــن أن فضيلتــه حكــم مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى القــرار‬\n      ‫رقــم ‪ 33426238‬وتاريــخ ‪1433/10/15‬ه ـ تقــرر الدائــرة املصادقــة على‬\n\n\n‫‪207‬‬\n\f                                ‫احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n‫واهلل املوفق وصلى اهلل على نبينا محمد و على آله وصحبه وسلم ‪.‬‬\n\n\n\n\n                                                                    ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":200,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"59d70df0d43cb58df2b7ec3648ed70e57e5191798d036cf53cac56bcd1fae28e","normalized_text_hash":"713d2ee50bc1a971f0f712514edada3d5deba5453719266eb6010fdff9673c52","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p200-33272212"},{"id":"a3ba3d04-6804-5608-9e0f-8785213f2683","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري -طلب تسليم دية متوفى -إقرار املدعى عليه -مشاركة املدعى عليه املتوفى اخلطأ يف احلادث -تقرير املرور من جنس رأي اخلبير تستأنس به المحكمة وال يلزمها -من تسبب يف موت إنسان معصوم لزمته ديته عدم األخذ بتقرير املرور يف مقدار نسبة اإلدانة -دية القتل اخلطأ مؤجلة ثاث سنوات كفارة قتل اخلطأ .","document_number":"3450453","case_number":"32185860","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/30","year":"1434","subject":"دية متوفى -حادث مروري -طلب تسليم دية متوفى -إقرار املدعى عليه -مشاركة املدعى عليه املتوفى اخلطأ يف احلادث -تقرير املرور من جنس رأي اخلبير تستأنس به المحكمة وال يلزمها -من تسبب يف موت إنسان معصوم لزمته ديته عدم األخذ بتقرير املرور يف مقدار نسبة اإلدانة -دية القتل اخلطأ مؤجلة ثاث سنوات كفارة قتل اخلطأ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/30 :‬هـ َر ْق ُم‬\n                               ‫ُ‬                ‫َر ْق ُم َّ‬\n                                   ‫الص ِّك‪3450453 :‬‬\n                                    ‫الدعوى‪32185860 :‬‬\n                  ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                        ‫‪ 34202202‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n         ‫ديــة متوفــى ‪ -‬حــادث مــروري ‪ -‬طلــب تســليم ديــة متوفــى ‪ -‬إقــرار املدعــى‬\n         ‫عليــه ‪ -‬مشــاركة املدعــى عليــه املتوفــى اخلطــأ يف احلــادث ‪ -‬تقريــر‬\n         ‫املــرور مــن جنــس رأي اخلبيــر تســتأنس بــه احملكمــة وال يلزمهــا ‪ -‬مــن‬\n         ‫تســبب يف مــوت إنســان معصــوم لزمتــه ديتــه ـ عــدم األخــذ بتقريــر املــرور‬\n         ‫يف مقــدار نســبة اإلدانــة ‪ -‬ديــة القتــل اخلطــأ مؤجلــة ثــاث ســنوات ـ‬\n                                                                  ‫كفــارة قتــل اخلطــأ ‪.‬‬\n\n\n\n         ‫‪ .1‬قولــه تعالــى ‪ ( :‬ومــن قتــل مؤمن ـ ًا متعمــد ًا فتحريــر رقبــة مؤمنــة‬\n                                                         ‫وديــة مســلمة إلــى أهلــه ) ‪.‬‬\n              ‫‪ .2‬مسألة ( ما لو اصطدم راكب وسائر ) ينظر ‪ :‬كشاف القناع‬\n                                                                          ‫( ‪) 2918/8‬‬\n                ‫‪ .3‬ما نص عليه الشيخ محمد بن إبراهيم يف فتاويه ( ‪) 316/11‬‬\n         ‫‪ .4‬مــن تســبب يف مــوت إنســان معصــوم لزمتــه ديتــه ( الــروض املربــع‬\n                                                                               ‫‪. ) 646‬‬\n         ‫‪ .5‬مــا قــرره أهــل العلــم أن ديــة قتــل اخلطــأ مؤجلــة علــى ثــاث ســنوات‬\n         ‫مــن حينــه وهــي علــى العاقلــة‪ .‬ينظــر كشــاف القنــاع ( ‪) 2968-2913/8‬‬\n         ‫وهــذا قــول عمــر وعلــي رضــي اهلل عنهمــا ـ ولــم يعــرف لهمــا مخالــف‬\n                                 ‫فــكان إجماع ـ ًا ‪ ،‬فيكــون كل ســنة ثلــث الديــة ‪.‬‬\n         ‫‪ .6‬مــا قــرره األصحــاب أن الوكيــل يف القبــض لــه أن يخاصــم ‪ ،‬قــال يف‬\n‫‪209‬‬\n\f‫الــروض املربــع ( ‪( : ) 398‬الوكيــل يف القبــض لــه اخلصومــة ‪ ،‬ألنــه ال‬\n                           ‫يتوصــل إليهــا إال بهــا ‪ ،‬فهــو أذن فيهــا عرفـ ًا )‪.‬‬\n‫‪ .7‬األمــر الســامي البرقــي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ املبنــي علــى‬\n       ‫قــرار احملكمــة العليــا بهيئتهــا العامــة رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ ‪.‬‬\n\n\n\n\n‫حضــر املدعــي بالوكالــة عــن ورثــة امليــت وقــد خـ ّـول لــه يف الوكالــة‬\n‫بتحصيــل الشــيك ملبلــغ التعويــض مــن صاحــب الســيارة ‪ ،‬وجميــع‬\n‫الــوكاالت والصكــوك مصــادق عليهــا مــن اجلهــات الرســمية ‪ ،‬وقــرر‬\n‫ناظــر القضيــة اإلذن لــه بتحريــر دعــواه ‪ ،‬ألن الوكيــل يف القبــض لــه‬\n‫أن يخاصــم كمــا قــرره احلنابلــة ‪ ،‬طلــب املدعــي وكالــة تســليمه ديــة‬\n‫املتوفــى ـ بعــرض دعــوى املدعــي وكالــة علــى املدعــى عليــه أنكــر مــا‬\n‫ال فخــرج إليه املتوفى‬ ‫جــاء فيهــا وقــرر أنــه كان يســير يف طريــق مظلم لي ً‬\n‫فجــأة واصطــدم بــه ـ أقــر أن شــركة التأمــن مســتعدة لدفــع مــا يحكــم‬\n‫بــه شــرع ًا ـ مت االطــاع علــى محضــر املعاينــة ومحضــر نســبة احلــادث‬\n‫املــروري املعــد مــن قبــل رجــال املــرور واملتضمــن أن املدعــى عليــه يتحمــل‬\n‫نســبة ‪ % 25‬مــن مســؤولية احلــادث ـ ظهــر للقاضــي أن العــدل واحلالــة هــذه‬\n‫أن يتحمــل كل واحــد منهــا نصــف الضمــان ـ تقريــر املــرور مــن جنــس‬\n‫رأي اخلبيــر ‪ ،‬ال تلــزم بــه احملكمــة ـ مــن تســبب يف مــوت إنســان معصــوم‬\n‫لزمتــه ديتــه ـ االطــاع علــى األمــر الســامي املتضمــن أن ديــة قتــل اخلطــأ‬\n‫ثالثمائــة ألــف ريــال ـ قــرر أهــل العلــم أن ديــة اخلطــأ تكــون علــى العاقلــة‬\n‫‪ ،‬وتكــون مؤجلــة ملــدة ثــاث ســنوات مــن حينــه كل ســنة ثلــث الديــة ـ‬\n‫احلكــم علــى املدعــى عليــه بتســليم املدعــن نصــف الديــة مائــة وخمســن‬\n\n                                                                                        ‫‪210‬‬\n\f      ‫ألــف ريــال ـ احلكــم بــرد دعــوى املدعــن فيمــا زاد عــن ذلــك وإفهــام‬\n      ‫املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ وهــي عتــق رقبــة مؤمنــة فــإن‬\n      ‫لــم يجــد فصيــام شــهرين متتابعــن ‪ -‬إفهــام املدعــى عليــه بالرجــوع علــى‬\n      ‫العاقلــة ـ قــرر املدعــى وكالــة قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم‬\n                               ‫قناعتــه صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32185860‬وتاريــخ ‪1432/05/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 32575949‬وتاريــخ ‪ 1432/05/20‬ه ـ‬\n      ‫حضــر ‪ ...‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬بصفتــه وكيــا‬\n      ‫ورثــة ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل بكاماريــدي‬\n      ‫بالهنــد برقــم ‪ 043053‬ايــه ‪ 45‬يف ‪2012/2/7‬م واملصدقــة مــن اجلهــات‬\n      ‫ذات العالقــة آخرهــا فــرع وزارة العــدل مبكــة املكرمــة برقــم ‪2045‬‬\n      ‫يف ‪1433/8/17‬ه ـ والتــي تخولــه حتصيــل الشــيك ملبلــغ التعويــض مــن‬\n      ‫صاحــب الســيارة اجلانــي إلــخ والورثــة هــم ‪ ...‬و ‪ ...‬و ‪ ...‬احملصــور بحصــر‬\n      ‫الورثــة الصــادر مــن حكومــة آنداهــر إبراديــش برقــم ‪44/21/2012‬‬\n      ‫يف ‪2012/1/3‬م املصــدق مــن اجلهــات ذات االختصــاص أخرهــا فــرع‬\n      ‫وزارة العــدل مبكــة كمــا حضــر املدعــى عليــه ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬ونظــر ًا ملــا قــرره األصحــاب أن الوكيــل‬\n      ‫يف القبــض لــه أن يخاصــم قــال يف الــروض املربــع ص ‪( 398‬الوكيــل‬\n      ‫يف القبــض لــه اخلصومــة ألنــه ال يتوصــل إليــه إال بهــا فهــو أذن فيهــا‬\n\n‫‪211‬‬\n\f‫عرف ـاً) فقــد قــررت الســير بالقضيــة لــذا ســألته عــن دعــواه فقــال‬\n‫بواســطة مترجــم احملكمــة ‪ ...‬باكســتاني اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ ...‬أن املدعــى عليــه صــدم مــورث موكلــي بســيارته وتوفــى علــى‬\n‫أثــر ذلــك أطلــب احلكــم عليــه بتســليمي ديــة املتوفــى وأســاله اجلــواب‬\n‫هــذه دعــواي فطلبــت منــه بيانهــا وزيــادة إيضاحهــا فقــال لــم أكــن‬\n‫حاضــر ًا يف احلــادث فأطلــب االطــاع علــى ملــف املعاملــة ورصــد مــا يلــزم‬\n‫مــن واقــع األوراق املرفقــة والتحقيقــات وبعرضهــا علــى املدعــى عليــه‬\n‫قــال مــا ذكــره املدعــي أننــي صدمــت مــورث موكلــه غيــر صحيــح‬\n‫والصحيــح أننــي كنــت أســير علــى ســيارتي ‪ ...‬علــى طريــق املدينــة‬\n‫القــدمي اخلــارج مــن عســفان املتجــه شــما ًال إلــى خليــص وحينمــا حاذيــت‬\n‫مصنــع ‪ ...‬للبلــك كان هنــاك اشــخاص قادمــون مــن جهــة املصنــع علــى‬\n‫الطريــق الســريع اجلديــد علــى يســاري يريــدون قطــع الطريــق وحينمــا‬\n‫قربــت منهــم كان هنــاك مجموعــة قطعــت الطريــق ومجموعــة بقيــت‬\n‫لــم تقطــع فقربــت بســيارتي فخــرج علــي مــورث املدعــن فجــأة مــن بــن‬\n‫ا واملــكان مظلم ـ ًا‬  ‫األشــخاص الذيــن لــم يقطعــوا وكان الوقــت لي ـ ً‬\n‫وحاولــت تفاديــه وانحرفــت إلــى جهــة اليمــن إال أنــه حلقنــي وصــدم‬\n‫بســيارتي مبرآتهــا اليســرى وكانــت الضربــة علــى رأســه ومــا يحكــم‬\n‫علــي بــه فشــركة التأمــن التــي تعاقــدت معهــا مســتعدة بتســليم ذلــك‬\n‫هكــذا أجــاب وبعرضــه علــى املدعــي وكالــة قــال مــا ذكــره املدعــى‬\n‫عليــه فــا أعلمــه عنــه لكــن أصدقــه علــى ذلــك ألننــي لــم أكــن حاضــر ًا‬\n‫وال احــد مــن الورثــة هكــذا قــرر ثــم أطلعــت علــى أوراق املعاملــة فرأيــت‬\n‫دفتــر التحقيــق علــى لفــه (‪ )1‬ص ‪ 2‬وفيــه مــا نصــه محضــر معاينــة بتاريــخ‬\n‫‪1431/6/17‬ه ـ البــاغ تبلغــت أنــا رئيــس رقبــاء ‪ ...‬ضابــط خفــر حــوادث‬\n\n\n                                                                                   ‫‪212‬‬\n\f      ‫الغــرب بتاريــخ ‪1431/6/17‬ه ـ مبنطقــة غــران بالقــرب مــن مصنــع‪...‬‬\n      ‫عــن وقــوع حــادث مــروري عبــارة عــن دهــس شــخص مــن قبــل ســيارة‬\n      ‫‪ ...‬رقــم اللوحــة ‪ ...‬موديــل ‪ ...‬جنــم عــن احلــادث وفــاة الشــخص املدهــوس‬\n      ‫اإلجــراء املتخــذ مت االنتقــال الفــوري والســريع إلــى موقــع احلــادث بعــد‬\n      ‫إبــاغ الشرشــورة تنقــل املتوفــى والســطحه لتنقــل الســيارة إلــى احلجــز‬\n      ‫كيفيــة وقــوع احلــادث وقــع احلــادث علــى الطريــق الواصــل بــن عســفان‬\n      ‫وخليــص ومبنطقــة غــران بالقــرب مــن مصنــع ‪ ...‬والطريــق عبــارة خــط‬\n      ‫اجتــاه واحــد ذهــاب و إيــاب وكان الســائق يســير يف مســاره الصحيــح‬\n      ‫تفاجــأ مبجموعــة مــن العمــال يعبــرون الطريــق وإذا أحــد العمــال يتأخــر‬\n      ‫عــن البقيــة ممــا أدى إلــى صدمــه مــن قبــل الســائق باجلانــب األيســر مــن‬\n      ‫بــاب الســائق مــع املــراه وكان أســباب احلــادث عــدم آخــذ احليطــة واحلــذر‬\n      ‫مــن الســائق الطقــس ومحضــر التفتيــش الرويــة احلــادث وقــع يف الليــل‬\n      ‫الســاعة ‪ 8،30‬تقريب ـ ًا والطريــق غيــر منــور واليوجــد عوائــق حتجــب‬\n      ‫الرؤيــا أثنــاء القيــادة وقــع تفتيــش الســيارة وال يوجــد مــا يوجــب الرفــع‬\n      ‫عنــه مــن احملرمــات وغيرهــا ضابــط القضيــة ‪ ...‬توقيــع أ‪.‬ه ـ ويف ص‪9‬‬\n      ‫محضــر نســبة حــادث مــروري يــدان الســائق ‪ ...‬بنســبة ‪ %25‬مــن احلــادث‬\n                                               ‫املــروري وذلــك لألســباب التاليــة ‪:‬‬\n                                           ‫‪1‬ـ عدم أخذ احليطة واحلذر أثناء القيادة‬\n      ‫‪2‬ـ يحمــل رخصــة قيــادة والواجــب عليــه التقيــد بأنظمــة وقواعــد املــرور‬\n      ‫أثنــاء القيــادة ‪ ،‬ثانيـ ًا يــدان الشــخص املدهــوس بنســبة ‪ %75‬مــن احلــادث‬\n      ‫املــروري لألســباب التاليــة ‪1‬ـ قطــع اخلــط عرضـ ًا مــن قبــل املدهــوس دون‬\n      ‫التأكــد مــن خلــوه مــن الســيارات ‪ -2‬البــد أنــه رأى الســيارة علــى بعــد‬\n      ‫مــن ســيرها وذلــك بواســطة االنــوار األماميــة وميكــن عــرض حياتــة‬\n\n\n‫‪213‬‬\n\f‫خلطــر مميــت كمــا حصــل ‪ -3‬كونــه عاقــا و مــدركا ملخاطــر‬\n‫الطريــق كان املفــروض ان يكــون حــذر ًا ضابــط خفــر رئيــس رقبــاء ‪...‬‬\n‫و ضابــط التحقيــق نقيــب ‪ ...‬و مديــر شــعبة احلــوادث مقــدم ‪ ...‬أ‪.‬ه ـ وبعــد‬\n‫التأمــل يف الدعــوى واإلجابــة ونظــرا ملــا قــرره املدعــى عليــه مــن صفــة‬\n‫وقــوع احلــادث وتصديــق املدعــي وكالــة علــى ذلــك وألن مــورث املدعــن‬\n‫بذلــك يعتبــر مفرطـ ًا يف حفــظ نفســه واالحتيــاط لهــا فيكــون مشــارك ًا‬\n‫للمدعــى عليــه يف اخلطــأ ونظــر ًا ملــا جــاء يف أقــوال املدعــى عليــه ان‬\n‫الطريــق كان مظلمـ ًا وأن أمامــه أنــاس يريــدون قطــع الطريــق فالواجــب‬\n‫ملثــل ذلــك أن يحــذر ويحتــاط ويخفــف ســرعته حتســب ًا ألي عــارض علــى‬\n‫الطريــق وعليــه فهــو مــدان يف ذلــك يتحصــل مــن مجمــوع ذلــك اشــتراك‬\n‫الطرفــن يف الضمــان نظــر ًا الشــتراكهما يف ســبب اجلنايــة فالعــدل أن‬\n‫يتحمــل كل واحــد منهمــا نصــف الضمــان وينظــر يف مثــل ذلــك مــا نــص‬\n‫عليــه األصحــاب يف مســألة مــا لــو اصطــدم راكــب وســائر ينظــر يف‬\n‫كشــاف القنــاع ص ‪ 2918‬ج ‪ 8‬وكــذا مــا نــص عليــه الشــيخ محمــد بــن‬\n‫إبراهيــم يف فتاويــه ‪ 316/11‬وعليــه يتحمــل املدعــى عليــه نصــف الديــة‬\n‫وأمــا تقريــر املــرور فهــو مــن جنــس رأي اخلبيــر تســتأنس بــه احملكمــة وال‬\n‫يقيدهــا كمــا نصــت املــادة ‪ 134‬مــن نظــام املرافعــات الشــرعية ونظــرا‬\n‫ملــا قــرره اهــل العلــم ان مــن تســبب يف مــوت انســان معصــوم لزمتــه ديتــه‬\n‫الــروض املربــع ص‪ 646‬وهــي هنــا النصــف كمــا شــرحته وتاسيســا‬\n‫علــى قولــه تعالــى (ومــن قتــل مؤمنــا متعمــدا فتحريــر رقبــة مؤمنــه وديــة‬\n‫مســلمة الــى اهلــه ) ونظــرا ملــا جــاء يف تعميــم املجلــس االعلــى للقضــاء‬\n‫رقــم ‪/192‬ت يف ‪1432/10/9‬ه ـ مبــا قررتــه احملكمــة العليــا بهيئتهــا‬\n‫العامــه بالقــرار رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ ان ديــة القتــل اخلطــا الكاملــة‬\n\n\n                                                                                    ‫‪214‬‬\n\f      ‫ثالثمائــة الــف ريــال واملعتمــد باالمــر الســامي البرقــي رقــم ‪ 43108‬يف‬\n      ‫‪1432/10/2‬ه ـ وبعــد اطالعــي علــى تقريــر احلــادث وجــدت ان تاريــخ‬\n      ‫الواقعــه كان يف ‪1432/11/15‬ه ـ ونظــرا ملــا قــرره اهــل العلــم ان ديــة‬\n      ‫القتــل اخلطــا مؤجلــه علــى ثــاث ســنني مــن حينــه وانهــا علــى العاقلــة‬\n      ‫كمــا يف كشــاف القنــاع ص ‪ 2913‬ويف ص ‪ 2968‬وذلــك لقــول عمــر‬\n      ‫وعلــي رضــي اهلل عنهمــا يف اخلطــا ولــم يعــرف لهمــا مخالــف فــكان‬\n      ‫اجماعــا يف اخــر كل ســنة ثلــث ولكــون واقعــة احلــادث كانــت يف‬\n      ‫‪1431/6/17‬ه ـ وعليــه فقــد حــل كامــل الديــة ولذلــك فقــد حكمــت‬\n      ‫علــى املدعــى عليــه تســليم املدعــن نصــف ديــة مورثهــم مائــه وخمســن‬\n      ‫الــف ريــال ورددت دعــوى املدعــن فيمــا زاد عــن ذلــك وافهمــت املدعــى‬\n      ‫عليــه بــان عليــه كفــارة قتــل اخلطــا عتــق رقبــه مؤمنــه فــان لــم يجــد صــام‬\n      ‫شــهرين متتابعــن اليفصــل بينهمــا بفطــر اال لعــذر مــن مــرض او ســفر‬\n      ‫كمــا افهمتــه بالرجــوع علــى العاقلــة وبعرضــه علــى املدعــي وكالــه قنــع‬\n      ‫بــه وبعرضــه علــى املدعــى عليــه قــرر عــدم القناعــه فافهمتــه بتعليمــات‬\n      ‫االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/20‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬ـ ـ نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة جــرى منــا االطــاع علــى الصــك رقــم‪ 3450453‬وتاريــخ‬\n      ‫‪1434/2/30‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة‬\n      ‫العامــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ‪ ...‬وكالــة ضــد‪ ... /‬يف‬\n      ‫حــادث مــروري ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n\n\n‫‪215‬‬\n\f‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪216‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":209,"source_page_end":216,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9dd8b8b896b158b8d2adde7959c758315c09b04786e08351d675476522f93698","normalized_text_hash":"722ac3a64e8a893223dbbc7858ef662d2891917f164956aa3944bac2afa174d1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p209-3450453"},{"id":"997cc226-3fe1-5582-9d4a-ba4ed4f51e4b","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -دهس بسيارة تسبب يف وفاة -صدور صك من المحكمة بإثبات نسبة اخلطأ على املدعى عليه ودفع الدية -إيداع مبلغ الدية بيت املال يف المحكمة لتسليمها للورثة -مطالبة بيت املال بتسليم مبلغ الدية -إلزام بيت مال المحكمة بتسليم مبلغ الدية املودع به للورثة ما استند إليه القاضي من مبادئ وقواعد العدالة العامة الواردة يف","document_number":"3456993","case_number":"3412850","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة قائا يف دعواه إنه ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"دية -دهس بسيارة تسبب يف وفاة -صدور صك من المحكمة بإثبات نسبة اخلطأ على املدعى عليه ودفع الدية -إيداع مبلغ الدية بيت املال يف المحكمة لتسليمها للورثة -مطالبة بيت املال بتسليم مبلغ الدية -إلزام بيت مال المحكمة بتسليم مبلغ الدية املودع به للورثة ما استند إليه القاضي من مبادئ وقواعد العدالة العامة الواردة يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/7 :‬هـ َر ْق ُم‬\n                              ‫ُ‬                ‫َر ْق ُم َّ‬\n                                  ‫الص ِّك‪3456993 :‬‬\n                                    ‫الدعوى‪3412850 :‬‬\n                 ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 34266053‬تاريخه‪1434/7/11 :‬هـ‬\n\n\n       ‫ديــة‪ -‬دهــس بســيارة تســبب يف وفــاة‪ -‬صــدور صــك مــن احملكمــة بإثبــات‬\n       ‫نســبة اخلطــأ علــى املدعــى عليــه ودفــع الديــة‪ -‬إيــداع مبلــغ الديــة بيــت‬\n       ‫املــال يف احملكمــة لتســليمها للورثــة‪ -‬مطالبــة بيــت املــال بتســليم مبلــغ‬\n       ‫الديــة‪ -‬إلــزام بيــت مــال احملكمــة بتســليم مبلــغ الديــة املــودع بــه للورثــة‬\n\n\n\n\n       ‫مــا اســتند إليــه القاضــي مــن مبــادئ وقواعــد العدالــة العامــة الــواردة يف‬\n                                                                     ‫تســبيب احلكم‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــن بــأن مــورث موكليــه تعــرض حلــادث دهــس ممــا‬\n       ‫تســبب يف وفاتــه وقــد أديــن ســائق الســيارة التــي دهســته بكامــل نســبة‬\n       ‫اخلطــأ فقــام بإيــداع مبلــغ الديــة يف بيــت مــال احملكمــة‪ ،‬ولــذا فقــد‬\n       ‫طلــب احلكــم علــى بيــت املــال بتســليم موكليــه املدعــن ديــة مورثهــم‬\n       ‫املودعــة ‪ -‬طلبــت احملكمــة إفــادة مديــر بيــت املــال فأفــاد بــأن مبلــغ‬\n       ‫ديــة مــورث املدعــن مت إيداعــه يف بيــت مــال احملكمــة كمــا حتققــت‬\n       ‫مــن املســتندات املرفقــة مبلــف القضيــة فوجدتهــا مطابقــة ملــا جــاء يف‬\n       ‫الدعــوى‪ -‬قضــت احملكمــة بثبــوت صحــة الدعــوى وحكمــت علــى‬\n       ‫بيــت مــال احملكمــة بتســليم املدعــي وكالــة املبلــغ املــودع لديهــم كمــا‬\n\n‫‪217‬‬\n\f‫أفهمتــه بالنصيــب الشــرعي لــكل وارث‪ -‬قــررت محكمــة االســتئناف‬\n                      ‫املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 3412850‬وتاريــخ‬\n‫‪ 1434/01/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3459783‬وتاريــخ‬\n‫‪ 1434/01/07‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/03/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 : 45‬وفيهــا حضــر‪ ...........‬مينــي اجلنســية مبوجــب‬\n‫جــواز الســفر رقــم ‪ ...........‬بصفتــه وكيــا عــن ورثــة ‪ ...........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن وزارة العــدل اليمنيــة برقــم ‪ 186‬وتاريــخ‬\n‫‪1433/10/13‬ه ـ واملصــادق عليهــا مــن وزارة اخلارجيــة الســعودية وادعى‬\n‫علــى مديــر بيــت املــال يف احملكمــة العامــة باملدينــة املنــورة قائــا يف‬\n‫دعــواه إنــه بتاريــخ ‪1432/10/9‬ه وقــع حــادث دهــس مــورث موكلــي ‪....‬‬\n‫بشــارع اإلمــام البخــاري يف حــي العزيزيــة باملدينــة املنــورة مــن قبــل ســيارة‬\n‫‪ ...........‬كان يقودهــا احلــدث‪ ...........‬وقــد نتــج عــن احلــادث وفــاة مــورث‬\n‫موكلــي وقــد قــرر رجــال املــرور أن نســبة اخلطــأ كاملــة ‪ %100‬علــى‬\n‫الســائق وقــد صــدر منكــم قــرار شــرعي بذلــك برقــم ‪ 3437916‬يف‬\n‫‪1434/2/16‬ه ـ يتضمــن اثبــات النســبة املذكــورة وحيــث إن الســائق‬\n‫املذكــور قــد أودع مبلــغ الديــة الشــرعي وقــدره ثالثمائــة ألــف ريــال يف‬\n‫بيــت املــال يف احملكمــة لتســليمها للورثــة الشــرعيني فأطلــب احلكــم‬\n‫علــى بيــت املــال بتســليمي املبلــغ املــودع لديهــم وقــدره ثالثمائــة ألــف ريــال‬\n\n                                                                                          ‫‪218‬‬\n\f      ‫هــذه دعــواي وبســؤال املدعــى عليــه مديــر بيــت املال يف احملكمــة العامة‬\n      ‫أجــاب بخطابــه رقــم ‪ 34/549611‬يف ‪1434/3/3‬ه ـ املتضمــن نفيدكم‬\n      ‫أنــه وردنــا مبلــغ ثالثمائــة ألــف ريــال مــن قبــل بإيصــال اســتالم رقــم‬\n      ‫‪ 11/020907‬يف ‪1433/11/14‬ه ـ وذلــك ديــة ‪ .....‬ومــازال املبلــغ موجــود‬\n      ‫لدينــا حتــى تاريخــه هكــذا أجــاب فجــرى االطــاع علــى أوراق املعاملــة‬\n      ‫ومنهــا مــا جــاء يف القــرار الشــرعي املذكــور كمــا جــرى االطــاع علــى‬\n      ‫وثيقــة الوكالــة مــن املدعــي وطلبــت مــن املدعــي وكالــة صــك حصــر‬\n      ‫الورثــة فأبــرزه لدينــا فــاذا هــو صــادر مــن وزارة العــدل اليمنيــة برقــم‬\n      ‫‪ 114‬وتاريــخ ‪1434/10/11‬ه ـ يتضمــن إثبــات انحصــار ورثــة ‪ ....‬بســبب‬\n      ‫حــادث مــروري يف املدينــة املنــورة وخلــف ورثتــه وهــم والــده ‪ ....‬ووالدته ‪....‬‬\n      ‫وزوجتــه ‪ ....‬وولديــه ‪ ...........‬وعمــره خمــس ســنوات ‪ ...........‬وعمــره ثــاث‬\n      ‫ســنوات فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى‬\n      ‫خطــاب مديــر بيــت املــال يف احملكمــة يتضمــن كــون املبلــغ مــودع لديهم‬\n      ‫وبعــد االطــاع علــى القــرار الشــرعي الصــادر منــا وبنــاء علــى مــا تقــدم‬\n      ‫فقــد ثبــت لــدي صحــة الدعــوى وحكمــت علــى بيــت مــال احملكمــة‬\n      ‫بتســليم املدعــي وكالــة املبلــغ املــودع لديهــم وقــدره ثالثمائــة ألــف ريــال‬\n      ‫وبعــرض احلكــم قــرر املدعــي وكالــة القناعــة بــه وقــد أفهمــت املدعــى‬\n      ‫وكالــة بــأن قســمة املبلــغ حســب النصيــب الشــرعي كالتالــي ‪ :‬حيــث‬\n      ‫إن الورثــة هــم والــده ووالدتــه وزوجتــه وولديــه فيكــون نصيــب األب‬\n      ‫وقــدره خمســون ألــف ريــال ونصيــب االم وقــدره خمســون ألــف ريــال‬\n      ‫ونصيــب الزوجــة شــرقة الثمــن وقــدره ســبعة وثالثــون ألفــا وخمســمائة‬\n      ‫ريــال والباقــي يكــون للولديــن بالتســاوي فيكــون نصيــب كل ولــد‬\n      ‫مبلــغ وقــدره واحــد وثمانــون ألفــا ومئتــان وخمســون ريــاال ففهــم ذلــك‬\n\n\n‫‪219‬‬\n\f‫املدعــي وكالــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/7‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/06/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9 : 00‬صباحــا افتتحــت اجللســة وقــد عــادت‬\n‫إلينــا أوراق املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة وبرفقــه‬\n‫قرارهــا رقــم ‪ 34213518‬وتاريــخ ‪1434/5/15‬ه ـ املتضمــن مالحظتهــا‬\n‫باألكثريــة مــا يلــي‪ -1 ( :‬الوكالــة غيــر مصدقــة مــن فــرع وزارة العــدل‬\n‫حســب املتبــع ال ســيما أن فضيلــة حاكــم القضيــة ذكــر أنهــا وثيقــة‬\n‫عندمــا اطلــع عليهــا كذلــك صــك حصــر الورثــة غيــر مصــدق حســب‬\n‫املتبــع يف ذلــك ‪ -2‬لــم يذكــر اســم ممثــل بيــت املــال الــذي صــادق عليــه‬\n‫‪ -3‬لــم يشــر فضيلتــه هــل يحــق للوكيــل املذكــور اســتالم الديــة أو ال‬\n‫‪ -4‬علــى فضيلتــه إعــادة النظــر والتأمــل واإلفــادة هــل ســبق أن أفهــم‬\n‫املتســبب يف الوفــاة بكفــارة القتــل اخلطــأ أو ال )‪ .‬وفيهــا حضــر املدعــي‬\n‫وكالــة وجــرى إعــادة التأمــل يف أوراق القضيــة وقــال املدعــي إننــي ســبق‬\n‫أحضــرت لكــم صكــي الوكالــة وحصــر الورثــة وهمــا مصدقــان‬\n‫مــن وزارة اخلارجيــة الســعودية ومــن فــرع وزارة العــدل يف املدينــة املنــورة‬\n‫كمــا طلبتــم منــي ســابقا فهــذا جــواب املالحظــة األولــى وأمــا عــن جــواب‬\n‫املالحظــة الثانيــة فــإن اســم ممثــل بيــت املــال هــو وأمــا عــن املالحظــة‬\n‫الثالثــة فقــد جــرى بيــان أن للمدعــي حــق اســتالم الديــة احملكــوم بهــا‬\n‫بنــاء علــى الوكالــة الصــادرة لــه وأمــا عــن املالحظــة الرابعــة فإنــه ســبق‬\n‫إفهــام الســائق املتســبب يف الوف ــاة بكفــارة قتــل اخل ـ ــطأ وبــاهلل التوفي ـ ــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محـ ــمد وعلــى آلـ ـ ــه وصحبــه وســلم ‪ .‬ح ـ ــرر يف‬\n                                                                     ‫‪1434/6/24‬ه‪.‬‬\n\n\n                                                                                          ‫‪220‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة باملدينة‬\n      ‫املنــورة والقائــم بعمــل فضيلــة القاضــي اثنــاء فتــرة أجازتــه عليــه ففــي‬\n      ‫هــذا اليــوم الســبت املوافــق‪ 1434/07/29‬ه ـ وحيــث وردة مــن محكمــة‬\n      ‫االســتئناف مشــفوعة بالقــرار رقــم ‪ 34266053‬وتاريــخ ‪1434/7/11‬ه‬\n      ‫املتضمــن وبدراســة القــرار وصــورة ضبطــه تقــررت باملوافقــة علــى‬\n      ‫احلكــم بعــد اإليضــاح األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/29‬ه‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":217,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7373c76e3cf371ed390c6a3b71530b599260451f7a9a7e54d04540fd25141c69","normalized_text_hash":"fdde89f26a889ac26cce6256867af540eded03742af4352b031f388eb8e31825","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p217-3456993"},{"id":"30636b05-ac74-51a4-9b9d-210e6eb05792","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متويف -حادث مروري -سماع الدعوى ضد بيت املال لعدم معرفة القاتل -اإلذن بسماع الدعوى ضد بيت املال -ال يبطل دم امرئ مسلم -احلكم بدفع الدية من بيت املال .","document_number":"345007","case_number":"32145803","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف بالعمل يف املكتب القضائي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/6","year":"1434","subject":"دية متويف -حادث مروري -سماع الدعوى ضد بيت املال لعدم معرفة القاتل -اإلذن بسماع الدعوى ضد بيت املال -ال يبطل دم امرئ مسلم -احلكم بدفع الدية من بيت املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/6 :‬هـ َر ْق ُم‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪345007 :‬‬\n                            ‫الدعوى‪32145803 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3461200‬تاريخه‪1434/3/14 :‬هـ‬\n\n\n‫ديــة متــويف ‪ -‬حــادث مــروري ‪ -‬ســماع الدعــوى ضــد بيــت املــال لعــدم‬\n‫معرفــة القاتــل ‪ -‬اإلذن بســماع الدعــوى ضــد بيــت املــال ‪ -‬ال يبطــل دم‬\n                   ‫امــرئ مســلم ‪ -‬احلكــم بدفــع الديــة مــن بيــت املــال ‪.‬‬\n\n\n\n\n‫‪ .1‬أن النبــي صلــى اهلل عليــه وســلم ودى األنصــاري الــذي قتــل يف خبيــر‬\n                                                               ‫مــن بيــت املــال ‪.‬‬\n‫ا قتــل يف زحــام يف زمــن عمــر فلــم يعــرف قاتلــه فقــال‬\n                                                           ‫‪ .2‬مــا روي أن رجـ ً‬\n‫علــي لعمــر‪ :‬يــا أميــر املؤمنــن ال يبطــل دم امــرئ مســلم فــأدى ديتــه مــن‬\n                                                                     ‫بيــت املــال ‪.‬‬\n‫‪ .3‬اإلذن بســماع الدعــوى الصــادرة مــن نائــب رئيــس مجلــس الــوزراء‬\n                                      ‫برقــم ‪/1451‬م وتاريــخ ‪1432/3/2‬ه ـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي باألصالــة عــن نفســه وبالوكالــة عــن والدتــه وأخيــه‬\n‫الشــقيق وجميــع الــوكاالت والصكــوك مصــادق عليهــا مــن اجلهــات‬\n‫الرســمية وادعــى قائـاً‪ :‬إن مورثــه كان يقطــع أحــد الطــرق يف الريــاض‬\n‫مــن الغــرب إلــى الشــرق وعندمــا وصــل إلــى املســار األيســر قدمــت‬\n‫ســيارة مــن نــوع ( ‪ ) ...‬ال يعــرف لوحتهــا مــن اجتــاه الشــمال إلــى اجلنــوب‬\n\n                                                                                       ‫‪222‬‬\n\f      ‫واصطدمــت مبورثــه ولــم يقــم بإســعافه ويطلــب احلكــم لــه بصــرف الدية‬\n      ‫مــن بيــت املــال ـ بعــرض دعــوى املدعــي وكالــة وأصالــة علــى منــدوب‬\n      ‫وزارة املاليــة طلــب متكينــه مــن االطــاع علــى املعاملــة ‪ -‬تبــن صحــة‬\n      ‫مــا ادعــى بــه املدعــي أصالــة ووكالــة ـ صــدر اإلذن مــن املقــام الســامي‬\n      ‫بســماع الدعــوى ضــد بيــت املــال ‪ -‬مت االطــاع علــى تقريــر املــرور ـ‬\n      ‫احلكــم بإلــزام املدعــى عليــه بدفــع ديــة قتــل اخلطــأ ملــورث املدعــي ـ قــرر‬\n      ‫املدعــي أصالــة ووكالــة قناعتــه باحلكــم وقــرر املدعــي عليــه اعتراضــه‬\n      ‫علــى احلكــم بــدون الئحــة ـ صــدق احلكــم مــن محكمــة االســتئناف‬\n      ‫باألغلبيــة ـ ســلم يف جلســة أخــرى الشــيك للمدعــي أصالــة ووكالــة‬\n                        ‫حيــث إن وكالتــه مخــول لــه فيهــا حــق اســتالم الديــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي باحملكمــة‬\n      ‫العامــة بالريــاض واملكلــف بالعمــل يف املكتــب القضائــي رقــم «‪»35‬‬\n      ‫مــن تاريــخ ‪1433/6/21‬ه ـ ب ــموجب قــرار فضيلــة رئيــس احملكمــة‬\n      ‫رقــم ‪ 331143899‬وتاريــخ ‪1433/06/17‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n      ‫‪1433/80/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 08.15‬وفيهــا حضــر ‪...‬‬\n      ‫باألصالــة عــن نفســه وبالوكالــة عــن والدتــه ‪ ...‬اندونيســية اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة بالريــاض برقــم ‪ 20418‬يف ‪1433/03/14‬ه ـ وبالوكالــة‬\n      ‫عــن ‪ ...‬بخطــاب الوكالــة رقــم ‪ 2012/432508/60‬واملصــادق عليهــا‬\n      ‫مــن عمــدة ناحيــة فســانغان ‪ ...‬ختــم وتوقيــع ومــن رئيــس قريــة فوتــوان‬\n      ‫الوك ‪ ...‬ختــم وتوقيــع وبســؤال املدعــي أصالــة ووكالــة عمــا طلــب منــه‬\n\n‫‪223‬‬\n\f‫يف اجللســة الســابقة مــن تصديــق حصــر الورثــة والوكالــة قــدم حصــر‬\n‫الورثــة والوكالــة مصدقــة مــن قبــل وزارة اخلارجيــة ووزارة العــدل وقــد‬\n‫تضمــن حصــر الورثــة الصــادر مــن احملكمــة الدينيــة ب ـ فاميكاســان‬\n‫املختصــة بالنظــر والفصــل للقضايــا املدنيــة التــي ترفــع أمــام احملكمــة‬\n‫االبتدائيــة بإثبــات األحــكام يف قضيــة طلــب أصــدار صــك حصــر‬\n‫الورثــة واملتضمــن انحصــار ورثــة ‪ ... ...‬بزوجتــه ‪ ...‬و أبنائــه ‪ ...‬و‪... ...‬‬\n‫‪ .‬وحضــر حلضــوره منــدوب بيــت املــال ‪ ...‬مبوجــب خطــاب مديــر عــام‬\n‫اإلدارة القانونيــة بــوزارة املاليــة برقــم ‪ 26719‬وتاريــخ ‪1433/04/28‬ه ـ‬\n‫وادعــى األول بقولــه حصــل علــى مورثنــا حــادث دهــس يف شــارع ‪ ...‬يف‬\n‫حــي ‪ ...‬بالريــاض حيــث كان مورثنــا يقطــع الطريــق مــن الغــرب إلــى‬\n‫الشــرق وعندمــا وصــل إلــى املســار األيســر حيــث قدمــت ســيارة مــن نــوع‬\n‫‪ ...‬أبيــض اللــون ال يعــرف رقــم لوحتهــا مــن اجتــاه الشــمال إلــى اجلنــوب‬\n‫حيــث اصطــدم مبورثنــا ولــم يتوقــف إلســعافه وحيــث لــم يعــرف املتســبب‬\n‫يف احلــادث لــذا نطلــب صــرف الديــة مــن بيــت املــال هــذه دعــواي وبعــرض‬\n‫ذلــك علــى منــدوب بيــت املــال طلــب اإلطــاع علــى املعاملــة وبعــد متكينــه‬\n‫مــن اإلطــاع علــى املعاملــة أجــاب بقولــه نطلــب احلكــم الشــرعي يف‬\n‫القضيــة والنتهــاء وقــت اجللســة رفعــت الســاعة ‪ 08.35‬وحــدد موعــد‬\n‫اجللســة القادمــة يــوم األحــد املوافــق ‪1433/12/19‬ه ـ الســاعة ‪08.30‬‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                          ‫يف ‪1433/08/21‬ه ـ‬\n‫ويف جلســة أخــرى يف يــوم األحــد املوافــق ‪1434/01/04‬ه ـ لــدي أنــا ‪...‬‬\n‫املــازم القضائــي لــدى فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫يف الريــاض افتتحــت اجللســة الســاعة ‪ 10: 15‬وفيهــا حضــر املدعــي‬\n\n\n                                                                                    ‫‪224‬‬\n\f      ‫أصالــة ووكالــة ‪ ...‬إندونيســي اجلنســية املــدون مــا يثبــت هويتــه ووكالتــه‬\n      ‫يف جلســة ســابقة وحضــر حلضــوره منــدوب بيــت املــال ‪ ...‬املــدون مــا‬\n      ‫يثبــت هويتــه يف جلســة ســابقة ومت عــرض الدعــوى علــى املدعــى عليــه‬\n      ‫وكالــة و أجــاب قائــا ‪ :‬اطلــع الوكيــل احلاضــر يف اجللســة الســابقة‬\n      ‫علــى دعــوى املدعــي ومســتنداته وبعــد الرجــوع خلطابــات وزارة الداخليــة‬\n      ‫تبــن لنــا صحــة مــا ذكــره املدعــي أصالــة ووكالــة جملــة وتفصيــا هــذه‬\n      ‫إجابتــي لــذا رفعــت اجللســة الســاعة ‪ 11: 30‬إلــى يــوم الثالثــاء املوافــق‬\n      ‫‪1434/01/06‬ه ـ الســاعة ‪ 11: 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم‬\n         ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬حــرر يف ‪1434/1/4‬ه ـ‬\n      ‫ويف جلســة أخــرى يــوم الثالثــاء املوافق ‪1434/01/06‬هـ افتتحت اجللســة‬\n      ‫‪ 10: 30‬وفيهــا حضــر املدعــي واملدعــى عليــه املفــوض ‪ ...‬املــدون مــا يثبــت‬\n      ‫هويتهمــا يف جلســة ســابقة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومصادقــة املدعــى عليــه املفــوض مــن قبــل بيــت املــال علــى جميــع مــا‬\n      ‫ادعــى بــه املدعــي وبنــاء علــى اإلذن بســماع الدعــوى الصــادرة مــن نائــب‬\n      ‫رئيــس مجلــس الــوزراء برقــم ‪/1451‬م وتاريــخ ‪1432/03/02‬ه ـ وبنــاء‬\n      ‫علــى تقريــر املــرور برقــم ‪ 5414746‬والــذي ينــص علــى هــروب الســائق‬\n      ‫القاتــل وحتملــه مســؤولية احلــادث بنســبة ‪ %100‬وألن النبــي صلــى اهلل‬\n      ‫عليــه وســلم ودى األنصــاري الــذي قتــل يف خيبــر مــن بيــت املــال وملــا روي‬\n      ‫أن رجــا قتــل يف زحــام يف زمــن عمــر فلــم يعــرف قاتلــه فقــال علــي لعمــر‬\n      ‫يــا أميــر املؤمنــن ال يبطــل دم امــرئ مســلم فــأدى ديتــه مــن بيــت املــال‬\n      ‫وعليــه فقــد ألزمــت املدعــى عليــه بدفــع ديــة قتــل اخلطــأ مبلغــا وقــدره‬\n      ‫ثالثمائــة ألــف ريــال لورثــة ‪ ...‬وبــه حكمــت وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــي أصالــة ووكالــة القناعــة بينمــا قــرر املدعــى عليــه‬\n\n\n‫‪225‬‬\n\f‫املفــوض عدمهــا وأقــر قائــا أطلــب رفعهــا لالســتئناف بــدون الئحــة‬\n‫اعتراضيــة هكــذا أقــر وختمــت اجللســة يف متــام الســاعة ‪ 12: 00‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                              ‫‪1434/01/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وقــد صــدق احلكــم مــن الدائــرة اجلزائيــة األولــى لتمييــز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض مبوجــب قرارهــا‬\n‫رقــم ‪ 3461200‬يف ‪ 1434/03/14‬قاضــي اســتئناف ‪ ...‬لــه وجهــة نظــر‬\n‫ختــم وتوقيــع قاضــي اســتئناف د‪ ....‬ختــم وتوقيــع رئيــس الدائــرة ‪ ...‬ختــم‬\n‫وتوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/7/11‬ه ـ حضــر‬\n‫املدعــي اصالــة ووكالــة بوكالتــه املشــار لهــا ســابق ًا املخولــة لــه حــق‬\n‫اســتالم الديــة واســتلم الشــيك رقــم ‪ 8328770‬يف ‪1434/6/19‬ه ـ‬\n‫املســحوب مــن وزارة املاليــة مببلــغ وقــدره ثالثمائــة ألــف ريــال لصالــح‬\n‫الورثــة املذكوريــن يف الدعــوى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫برقــم ‪ 33552138‬وتاريــخ ‪1434/2/23‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪ .../‬املســجل برقــم‬\n‫‪ 345007‬وتاريــخ ‪1434/1/6‬ه ـ اخلــاص بدعــوى املدعــي ‪ ...‬اصالــة عــن‬\n\n\n                                                                                   ‫‪226‬‬\n\f      ‫نفســه ووكالــة عــن ‪ -1‬والدتــه ‪ ...‬اندونســية اجلنســية ‪ ...-2‬ضــد بيــت‬\n      ‫املــال بشــأن املطالبــة بديــة متوفــى علــى النحــو املوضــح بالصــك املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة وباهلل‬\n                                                                          ‫التوفيــق ‪.‬‬\n\n\n\n\n‫‪227‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":222,"source_page_end":227,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ca3d3d1eecf7f9f812e02676db6b63b83187a9d73cdf6303527bb79a875d72b6","normalized_text_hash":"4d11cdb5b7c8a6c7c7dafa5ac71d5079f41db2429e5d2eaac1b431f4649ea81e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p222-345007"},{"id":"65a3246f-cd49-5a94-a7f3-f86cd30e6a3b","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة نتيجة دهس بالسيارة -املطالبة بدية قتل خطأ -إثبات اإلدانة مبوجب تقرير املرور -حتمل املدهوس نسبة من اخلطأ -إلزام املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ","document_number":"3422286","case_number":"32205393","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/26","year":"1434","subject":"دية -حادث مروري -وفاة نتيجة دهس بالسيارة -املطالبة بدية قتل خطأ -إثبات اإلدانة مبوجب تقرير املرور -حتمل املدهوس نسبة من اخلطأ -إلزام املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/26 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3422286 :‬‬\n                              ‫الدعوى‪32205393 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34318301‬تاريخه‪1434/9/14 :‬هـ‬\n\n\n   ‫ديــة ‪ -‬حــادث مــروري ‪ -‬وفــاة نتيجــة دهــس بالســيارة ‪ -‬املطالبــة بديــة‬\n   ‫قتــل خطــأ ‪ -‬إثبــات اإلدانــة مبوجــب تقريــر املــرور ‪ -‬حتمــل املدهــوس‬\n   ‫نســبة مــن اخلطــأ ‪ -‬إلــزام املدعــى عليــه بدفــع الديــة مقابــل نســبة‬\n   ‫اخلطــأ التــي عليــه ‪ -‬إفهــام املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ‬\n                                                                                    ‫‪.‬‬\n\n\n\n\n   ‫‪ -1‬قولــه تعالــى ‪ ( :‬ومــا كان ملؤمــن أن يقتــل مؤمنــا إال خطــأ ومــن‬\n   ‫قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه إال أن‬\n                                                                      ‫يصدقــوا) ‪.‬‬\n   ‫‪ -2‬القاعــدة ‪ ( :‬أن كل مــن أتلــف إنســان ًا مبباشــرة أو تســبب فإنــه ملــزم‬\n                                                                         ‫بديتــه ) ‪.‬‬\n\n\n\n\n   ‫ادعــى وكيــل الورثــة علــى املدعــى عليــه بأنــه تســبب يف وفــاة مــورث‬\n   ‫موكلــه عــن طريــق دهســه بالســيارة ‪ -‬طلــب إلــزام املدعــى عليــه بدفــع‬\n   ‫الديــة ‪ -‬صــادق املدعــى عليــه علــى الدعــوى وقــرر املدعــى عليــه بأنــه‬\n   ‫كان يســير يف طريقــه عنــد إحــدى اإلشــارات بســرعة منخفضــة وكان‬\n   ‫يف أقصــى اليمــن وكان املتوفــى متجهــا نحــو الســيارة ولــم يــره حتــى‬\n\n                                                                                        ‫‪228‬‬\n\f      ‫ســمع صــوت االصطــدام ‪ -‬قــرر املدعــى عليــه بــأن املــرور حمــل مــورث‬\n      ‫املدعــن النســبة األكبــر مــن اخلطــأ ‪ -‬قــرر املدعــى عليــه اســتعداده‬\n      ‫بدفــع الديــة مقابــل نســبة اخلطــأ التــي عليــه ‪ -‬جــرى رجــوع القاضــي إلــى‬\n      ‫تقريــر احلــادث الصــادر مــن املــرور املتضمــن إدانــة مــورث املدعــن بنســبة‬\n      ‫‪ %75‬وإدانــة املدعــى عليــه بنســبة ‪ - %25‬صــدر احلكــم بإلــزام املدعــى‬\n      ‫عليــه بدفــع ديــة مــورث املدعــن مقابــل نســبة اخلطــأ التــي عليــه خمســة‬\n      ‫وســبعني ألــف ريــال ‪ -‬إفهــام املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ‬\n                                   ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي يف احملكمة اجلزائية بخميس‬\n      ‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط برقــم ‪ 32205393‬وتاريــخ ‪ 1432/06/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 32639797‬وتاريــخ ‪ 1432/06/01‬ه ـ ففــي‬\n                 ‫يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10 : 00‬وفيهــا حضــر ‪...‬مينــي اجلنســية مبوجــب جــواز الســفر رقــم‬\n      ‫‪...‬حلضــوره ‪...‬ســعودي اجلنســية ســجل مدنــي رقــم ‪...‬وقــد حضــر ‪...‬وكالــة‬\n      ‫عــن ورثــة املتوفــى ‪...‬وهــم كال مــن والــده ‪...‬ووالدته‪...‬كمــا هــو مبــن يف‬\n      ‫انحصــار اإلرث الصــادر مــن محكمــة الزهــرة االبتدائيــة بالرقــم ‪30‬‬\n      ‫واملصــدق مــن اجلهــات الرســمية وأخرهــا وزارة العــدل برقــم ‪ 2048‬يف‬\n      ‫‪ 1433/3/16‬وذلــك بالوكالــة عــن وارثــي املتــويف بالوكالــة رقــم ‪218‬‬\n      ‫واملتضمــن توكيــل املدعــي يف املطالبــة واســتالم كل مــا وجــب لهــم مــن‬\n      ‫حــق خــاص مقابــل وفــاة ولدهــم ‪ ...‬علــى اثــر احلــادث املــروري الذي تعرض‬\n\n‫‪229‬‬\n\f‫لــه يف محافظــة صامطــة وادعــى قائــا‪ :‬إن هــذا احلاضــر ‪...‬قــد تســبب يف‬\n‫وفــاة مــورث موكلــي دهســا يف محافظــة صامطــة وأطلــب إلزامــه بدفــع‬\n‫الديــة الشــرعية للمتوفــى هكــذا ادعــى وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه أجــاب قائــا‪ :‬مــا جــاء يف دعــوى املدعــي وكالــة صحيــح فقــد‬\n‫كنــت أســير يف طريقــي عنــد إحــدى اإلشــارات وســرعتي ثالثــن تقريبــا‬\n‫وكنــت يف أقصــى اليمــن وقــد كان املتوفــى متجهــا نحــو الســيارة ولــم‬\n‫أره حتــى ســمعت صــوت اإلصطــدام وقــد قــرر املــرور إدانتــي بنســبة ‪%25‬‬\n‫وأنــا مقتنــع بهــا هكــذا أجــاب ‪ .‬وإلنتهــاء وقــت اجللســة فقــد رفعتهــا‬\n‫وحــددت لهــا موعــدا يف يــوم األحــد املوافــق ‪1434/5/26‬ه ـ ‪ .‬أقفلــت‬\n‫اجللســة يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/25‬هـ‬\n‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي يف احملكمة اجلزائية بخميس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بخميــس مشــيط برقــم ‪ 32205393‬وتاريــخ ‪1432/06/01‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32639797‬وتاريــخ ‪ 1432/06/01‬ه ـ‬\n‫ففــي يــوم األحــد املوافــق‪ 1434/05/26‬ه ـ افتتحــت اجللســة الســاعة‬\n‫احلاديــة عشــرة والنصــف وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وجــرى اإلطــاع علــى أوراق املعاملــة ومــا جــاء يف طياتهــا ومــا جــاء يف‬\n‫تقريــر احلــادث رقــم ‪ 7/32800027/30‬واملرفــق باملعاملــة لفــه رقــم ‪11‬‬\n‫واملتضمــن توجيــه املســئولية للمدعــى عليــه بنســبة ‪ %25‬وذلــك لعــدم‬\n‫انتباهــه أثنــاء القيــادة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى إقــرار املدعــى عليــه بنســبة دعــس املتوفــى ‪...‬بالوصــف املذكــور‬\n‫يف التقريــر املــروري واقتناعــه بالنســبة املروريــة وهــي ‪ %25‬وملــا كان‬\n\n\n                                                                                         ‫‪230‬‬\n\f      ‫حــادث الدعــس بســبب خطــأ كل مــن الســائق واملاشــي فــإن الضمــان‬\n      ‫بالنســبة املذكــورة متوجــه علــى املدعــى عليــه ملــا ذكــر مــن أســباب يف‬\n      ‫رأي أهــل اخلبــرة املتقــرر فقهــا اعتبــاره والرجــوع إليــه يف مثــل هــذه احلــال‬\n      ‫ومبــا أن احلــادث نتــاج فعــل املدعــى عليــه مبباشــرته للدعــس فالقاعــدة‬\n      ‫أن كل مــن أتلــف إنســانا مبباشــرة أو تســبب فإنــه ملــزم بديتــه ولقــول‬\n      ‫اهلل تعالــى (ومــا كان ملؤمــن أن يقتــل مؤمنــا إال خطــأ ومــن قتــل مؤمنــا‬\n      ‫خطــأ فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه إال أن يصدقــوا)‬\n      ‫لــذا فقــد قــررت إلــزام املدعــى عليــه بدفــع مبلــغ وقــدره خمســة وســبعون‬\n      ‫ألــف ريــال تســلم لوكيــل ورثــة املتوفــى هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫وأفهمــت املدعــي أن هــذا املبلــغ يكــون نصيــب األم منــه إن لــم يكــن‬\n      ‫لــه جمــع مــن األخــوة الثلــث وإن كان لــه جمــع مــن األخــوة فنصيبهــا‬\n      ‫الســدس ويف احلالتــن مــا تبقــى يكــون لــأب وبعرضــه علــى املدعــي‬\n      ‫قــرر قناعتــه باحلكــم وبعرضــه علــى املدعــى عليــه قــرر عــدم قناعتــه‬\n      ‫باحلكــم وطلــب رفعــه إلــى محكمــة اإلســتئناف بــدون الئحــة أقفلــت‬\n      ‫اجللســة يف متــام الســاعة الثانيــة عشــر ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/26‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫مبنطقة ‪...‬بخطاب فضيلة رئيسها رقم ‪ 341352239‬يف ‪1434/7/11‬هـ‬\n      ‫واملرفــق بــه قــرار املالحظــة رقــم ‪ 34244151‬يف ‪1434/6/18‬ه ـ‬\n      ‫واملتضمــن أنــه لوحــظ مــا يلــي أوال‪ :‬حكــم فضيلتــه بثبــوت إدانــة املدعــى‬\n      ‫عليــه ‪...‬بدهــس املدعــو‪... /‬بنســبة ‪ %25‬ولــم جنــد أن فضيلتــه أفهمــه أن‬\n      ‫عليــه كفــارة قتــل اخلطــأ رغــم استشــهاده بنــص القــرآن وال بــد مــن ذلك ‪.‬‬\n      ‫ثانيــا‪ :‬صــورة الوكالــة وحصــر اإلرث لــم يصــدق فضيلتــه عليهــا بأنــه مت‬\n\n\n‫‪231‬‬\n\f‫اإلطــاع عليهــا ووجــدت مطابقــة لألصــل حســب مــا نــص عليــه النظــام‬\n‫‪ .‬ثالثــا‪ :‬يكتفــى بتدويــن اســم القاضــي يف مســتهل الضبــط وقــراره‬\n‫الشــرعي والصــك دون التكــرار يف كل جلســة عمــا بالتعليمــات ‪.‬‬\n‫وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل علــى املالحظــة األولــى‬\n‫بأنــه جــرى إفهــام املدعــى عليــه بــأن عليــه كفــارة القتــل اخلطــأ أثنــاء‬\n‫اجللســة وقــد تــرك ضبطهــا ســهوا وســيتم تــدارك ذلــك مســتقبال إن شــاء‬\n‫اهلل ‪ .‬وأمــا الثانيــة فقــد جــرى املصادقــة علــى صــور الــوكاالت وحصــر‬\n‫اإلرث والثالثــة متــت إضافتــه أثنــاء التنســيق ســهوا وســيتم مالحظــة ذلــك‬\n‫مســتقبال إن شــاء اهلل وبهــذا متــت إجابــة أصحــاب الفضيلــة وفقهــم اهلل‬\n‫واختتمــت اجللســة الســاعة احلاديــة عشــر والنصــف ‪ .‬واهلل املوفــق وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‪... ...‬علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط‬\n‫املســاعد برقــم ‪ 341766963‬وتاريــخ ‪1434/8/7‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪... /‬برقــم ‪...‬وتاريــخ‬\n‫‪1434/5/26‬ه ـ اخلــاص بدعــوى ‪( ... ... /‬مينــي اجلنســية) وكالــة ضــد‬\n‫‪... /‬يف قضيــة (مطالبــة بديــة متوفــى يف حــادث مــروري) علــى الصفــة‬\n‫املوضحــة يف الصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n‫ـاء علــى قرارنــا‬\n                ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n‫رقــم ‪ 34244151‬وتاريــخ ‪1434/6/18‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                              ‫وصحبــه وســلم ‪.‬‬\n                                                                                    ‫‪232‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":228,"source_page_end":232,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0fd25d61872c0b11e98479f35907daab4278f5f977260796cb18283744fc675","normalized_text_hash":"d714e55cbb63e43dfc7e5b730c87e482545daba3d7c137cef7b1df9c0488d0ec","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p228-3422286"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7bb4becc-65e3-5269-baf4-5d9a70f1209a","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري طلب تسليم دية قتل اخلطأ تعارض التقريرين املرورين مين املدعى عليه على نفي دعوى املدعي إذا اجتمع املباشر واملتسبب أضيف احلكم إلى املباشر إال إذا تعدى املتسبب القول يف التعدي قول منكره احلكم برد دعوى املدعي.","document_number":"34201873","case_number":"23077","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة اجلزائية الرابعة رقم 34258025وتاريخ 1434/07/03ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/30","year":"1434","subject":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري طلب تسليم دية قتل اخلطأ تعارض التقريرين املرورين مين املدعى عليه على نفي دعوى املدعي إذا اجتمع املباشر واملتسبب أضيف احلكم إلى املباشر إال إذا تعدى املتسبب القول يف التعدي قول منكره احلكم برد دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/30 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34201873 :‬‬\n                            ‫َر ْق ُم الدعوى‪23077 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34258025‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n      ‫ديــة ‪ -‬حــادث مــروري ـ مطالبــة بديــة متوفــى بحــادث مــروري ـ طلــب‬\n      ‫تســليم ديــة قتــل اخلطــأ ـ تعــارض التقريريــن املروريــن ـ ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــوى املدعــي ـ إذا اجتمــع املباشــر واملتســبب أضيــف‬\n      ‫احلكــم إلــى املباشــر إال إذا تعــدى املتســبب ـ القــول يف التعــدي قــول‬\n                                            ‫منكــره ـ احلكــم بــرد دعــوى املدعــي‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــال يف كشــاف القنــاع ( ‪ « : ) 131/4‬وإن كانــت إحــدى الســفينتني‬\n      ‫واقفة وكانت األخرى ســائرة واصطدمتا فغرقتا ضمن قيم الســفينة‬\n      ‫الســائرة الســفينة الواقفــة إن فــرط بــأن أمكنــه ردهــا ولــم يفعــل أو لــم‬\n      ‫يكمــل آلتهــا مــن رجــال وحبــال وغيرهمــا ‪ ،‬ألن التلــف حصــل بتقصيــره‬\n      ‫أشــبه مــا لــو نــام وتركهــا ســائرة بنفســها حتــى صدمتهــا ‪ ،‬وأمــا قيــم‬\n      ‫الواقفــة فــا ضمــان عليــه ‪ ،‬ألنــه لــم يوجــد منــه تعــد وال تفريــط ‪،‬‬\n      ‫أشــبه النائــم يف الصحــراء إذا عثــر بــه إنســان فتلــف ‪ ،‬ويأتــي إذا اصطــدم‬\n      ‫ا ‪ ،‬وإن كانــت إحداهمــا منحــدرة‬       ‫نفســان يف كتــاب الديــات مفص ـ ً‬\n      ‫واألخــرى مصعــدة فعلــى صاحبهــا أي املنحــدرة ضمــان املصعــدة ألن‬\n      ‫املنحــدرة تنحــط علــى املصعــدة مــن علــو ‪ ،‬فيكــون ذلــك ســبب ًا لغرقهــا‪،‬‬\n      ‫وال ضمــان علــى قيــم املصعــدة تنزيــا للمنحــدرة منزلــة الســائرة‬\n                                                    ‫واملصعــدة منزلــة الواقفــة أ‪.‬هــ‪.‬‬\n      ‫‪ .2‬قــال ابــن رجــب يف القواعــد ( ‪ ) 274‬القاعــدة ( ‪ « ) 127‬إذا اســتند‬\n‫‪191‬‬\n\f‫إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وتســبب تعلــق الضمــان‬\n                                                  ‫باملباشــرة دون الســبب »‬\n‫‪ .3‬القاعــدة الشــرعية ‪ :‬إذا اجتمــع املباشــر مــع املتســبب أضيــف احلكــم‬\n                                                             ‫إلــى املباشــر ‪.‬‬\n\n\n\n\n‫ادعــى املدعيــان بــأن مورثهمــا تــويف بحــادث مــروري ‪ ،‬وأديــن املدعــى‬\n‫عليــه بالتســبب باحلــادث بنســبة ‪ % 75‬وطلبــا أن يســلم املدعــى عليــه ديــة‬\n‫قتــل اخلطــأ مبــا يقابــل هــذه النســبة ‪ ،‬مت طلــب صــك حصــر الورثــة‬\n‫فوجــد انحصــار إرث املتوفــى يف والــده ووالدتــه ـ قامــت والــدة املتوفــى‬\n‫بتوكيــل زوجهــا يف املطالبــة بهــذه الدعــوى ومــا يتعلــق بهــا ـ صــادق‬\n‫املدعــى عليــه علــى وقــوع احلــادث ورفــض احلكــم عليــه ‪ ،‬جــرى االطــاع‬\n‫علــى أوراق املعاملــة فوجــد تقريريــن مروريــن األول منهــا يتضمــن أن‬\n‫النســبة تقــع بحــق املتوفــى بنســبة ‪ % 10‬والثانــي يتضمــن أن النســبة تقــع‬\n‫علــى املتوفــى بنســبة ‪ % 75‬و ‪ % 25‬بحــق املدعــى عليــه ـ أحــد مرافقــي‬\n‫املتوفــى شــهد مــن خــال أوراق القضيــة أن املتوفــى كان يســير بســرعة‬\n‫شــديدة ومت تنبيهــه وصــدم ســيارة املدعــى عليــه مــن اخللــف ـ مت ســؤال‬\n‫املدعــى هــل لديــه بينــة تشــهد علــى املدعــى عليــه باألســباب الــواردة يف‬\n‫التقريــر الثانــي فأجــاب بالنفــي ‪ ،‬ومت إفهامــه بــأن لــه ميــن املدعــى عليــه‬\n‫علــى نفــي مــا ورد يف التقريــر الثانــي فرضــي ميينــه وحلــف املدعــى عليــه‬\n‫اليمــن كمــا طلبــت منــه ‪ ،‬التقريــر األول أقــرب للصــواب ـ ذكــر‬\n‫الفقهــاء أنــه لــو كانــت ســفينة ســائرة وســفينة واقفــة واصطدمتــا ضمــن‬\n‫قيــم الســفينة الســائرة‪ ،‬وهــذه مثــل صــورة احلــادث ـ إذا اجتمــع املباشــر‬\n\n                                                                                      ‫‪192‬‬\n\f      ‫مــع املتســبب أضيــف احلكــم للمباشــر ‪ ،‬إال إذا ثبــت تعــدي املتســبب‬\n      ‫وهــو مــا يؤيــده التقريــر املــروري األول وميــن املدعــى عليــه ـ احلكــم بــرد‬\n      ‫دعــوى املدعــي ـ قــرر املدعــي اعتراضــه علــى احلكــم بالئحــة اعتراضيــة‬\n      ‫فأفهــم بتعليمــات االســتئناف ـ صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 23077‬وتاريــخ ‪1431/5/11‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 31/83275‬يف ‪1431/5/10‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافــق ‪1433/2/13‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي ‪...‬‬\n      ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ )...‬واملدعيــة ‪...‬ســعودية مبوجــب‬\n      ‫ســجل مدنــي رقــم (‪ )...‬املعــرف بهــا مــن قبــل زوجهــا املدعــي األول‬\n      ‫بصفتهمــا ورثــة ‪ ...‬مبوجــب صــك حصــر ورثــة صــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 25/119‬وتاريــخ ‪1431/2/29‬ه ـ وادعيــا علــى احلاضــر معــه ‪...‬ميني‬\n      ‫مبوجــب رخصــة إقامــة رقــم (‪ )...‬قائــا يف دعــواه‪ :‬ســبق أن وقــع حــادث‬\n      ‫ســير يف تاريــخ ‪1430/6/6‬ه ـ علــى طريــق خريــص القــدمي بالريــاض‬\n      ‫بــن ســيارتني األولــى مــن نــوع ‪ ...‬موديــل ‪ ...‬رقــم اللوحــة ‪.........‬يســوقها‬\n      ‫مورثنــا ‪...‬ويرافقــه كل مــن ‪ ...‬و‪...‬و‪...‬و‪...‬و‪...‬والثانيــة ســيارة مــن نــوع ‪...‬‬\n      ‫خالطــة موديــل ‪ ...‬رقــم اللوحــة ‪...‬يســوقها املدعــى عليــه هــذا احلاضــر‬\n      ‫ونتــج عــن احلــادث وفــاة مورثنــا ‪ ...‬وأديــن املدعــى عليــه بالتســبب يف‬\n      ‫احلــادث املوصــوف بنســبة ‪ %75‬مبوجــب تقريــر احلــادث املــروري لــذا‬\n      ‫أطلــب إلــزام املدعــى عليــه أن يســلم لنــا ديــة قتــل اخلطــأ ملورثنــا مبــا يقابــل‬\n\n‫‪193‬‬\n\f‫نســبته مــن اإلدانــة هــذه دعوانــا ثــم أضــاف املدعــي األول ‪ ...‬قائــا‪:‬‬\n‫الســيارة األولــى هــي ملكــي وأطلــب تقديــر قيمتهــا قبــل احلــادث وبعــده‬\n‫وإلــزام املدعــى عليــه بتســليمي أرش النقــص بــن القيمتــن هكــذا‬\n‫قــرر وبعرضهــا علــى املدعــى عليــه أجــاب قائــا‪ :‬أطلــب مهلــة للجــواب‬\n‫هكــذا أجــاب وجــرى االطــاع علــى صــك حصــر الورثــة املشــار إليــه‬\n‫أعــاه املتضمــن ثبــوت وفــاة ‪...‬يف ‪1430/6/7‬ه ـ وانحصــار إرثــه يف والده‬\n‫‪...‬ووالدتــه ‪...‬ال وارث لــه ســواهما‪ .‬وقــررت املدعيــة إقامــة زوجهــا املدعــي‬\n‫وكيــا عنهــا يف هــذه الدعــوى بصفتهــا املذكــورة أعــاه ينــوب عنهــا‬\n‫يف املرافعــة واملدافعــة واملطالبــة واإلقــرار واإلنــكار والصلــح والتنــازل‬\n‫وتقــدمي البينــات وطلــب اليمــن وردهــا والقناعــة باحلكــم واالعتــراض‬\n‫عليــه وتقــدمي لوائــح االعتــراض‪ .‬ويف يــوم األحــد املوافــق ‪1433/6/22‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــة ووكالــة ‪ ...‬واملدعــى عليــه‬\n‫‪ ......‬وبســؤاله عــن جوابــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي مــن وقــوع‬\n‫احلــادث املوصــوف بينــي وبــن ابنــه املذكــور فصحيــح ومــا ذكــره مــن‬\n‫وفــاة ابنــه فــا أدري ومــا ذكــره أن مســؤولية احلــادث تقــع علــي بنســبة‬\n‫‪ %75‬فــا أدري وأرفــض احلكــم علــي مبــا طلــب املدعــي هكــذا أجــاب‬\n‫وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى ملــف التحقيــق يف‬\n‫احلــادث املوصــوف واملتضمــن أنــه نتــج عــن احلــادث وفــاة قائــد الســيارة ‪....‬‬\n‫‪ ...‬ومرافقــه ‪...‬واملســؤولية تقــع علــى قائــد ‪... ....‬بنســبة ‪ %100‬لألســباب‬\n‫التاليــة‪ -1 :‬الســرعة العاليــة‪ -2 .‬عــدم االنتبــاه‪ -3 .‬االنشــغال عن القيادة‪.‬‬\n    ‫‪ -4‬عــدم أخــذ احليطــة واحلــذر‪ -5 .‬عــدم التأكــد مــن خلــو الطريــق‪.‬‬\n‫‪ -6‬وجــود إقــرار خطــي علــى أحــد املرافقــن‪ .‬واملنتهــي بتوقيــع جنــدي‬\n‫أول ‪ ...‬ومــازم أول ‪...‬ووكيــل رقيــب ‪ ....‬أهــ‪ .‬وجــرى االطــاع علــى إقــرار‬\n\n\n                                                                                       ‫‪194‬‬\n\f      ‫خطــي علــى امللــف نفســه وهــذا نصــه‪ :‬نعــم أنــا املدعــو ‪ ...‬أقــر بأننــي‬\n      ‫مرافــق مــع ســائق ‪ ....‬الســوبر بــان وراكــب يف املقعــد اخللفــي وكنــا‬\n      ‫نســير علــى طريــق خريــص القــدمي باجتــاه الشــرق وكان الســائق ‪...‬يقــود‬\n      ‫بســرعة عاليــة وقمنــا بتنبيهــه عــن وجــود شــاحنة أمامنــا وقــام مبســك‬\n      ‫الفرامــل وصدمنــا بهــا مــن اخللــف املقــر مبــا فيــه ‪...‬بصمتــه شــاهد علــى‬\n      ‫اإلفــادة منــدوب احلــوادث يف الشــرطة العســكرية جنــدي أول ‪ ....‬كمــا‬\n      ‫جــرى االطــاع علــى تقريــر حــادث لفــة رقــم ‪ 26‬واملتضمــن الوقــوف‬\n      ‫علــى موقــع احلــادث املوصــوف واملعاينــة علــى الطبيعــة ورأت اللجنــة أن‬\n                      ‫املســؤولية تقــع بنســبة ‪ %75‬علــى الســائق ‪ ...‬مينــي اجلنســية‬\n      ‫لألســباب التاليــة‪ -1 :‬عــدم التأكــد مــن خلــو الطريــق‪ -2 .‬عــدم‬\n      ‫التــزام املســار الصحيــح‪ -3 .‬اعتــراض خــط ســير الســيارة األخــرى‪.‬‬\n      ‫وتقــع بنســبة ‪ %25‬علــى الســائق ‪...‬ســعودي اجلنســية لألســباب التاليــة‪:‬‬\n      ‫‪ -1‬الســرعة الزائــدة‪ -2 .‬عــدم أخــذ احليطــة واحلــذر‪ .‬واملنتهــي بتوقيــع‬\n      ‫رقيــب أول ‪...‬ورقيــب أول ‪...‬ورئيــس اللجنــة ومتابعــة احلــوادث الرائــد ‪....‬‬\n      ‫أهــ‪ .‬وبعرضــه علــى الطرفــن أجــاب املدعــي قائــا‪ :‬أمــا التقريــر األول‬\n      ‫فأنــا قدمــت اعتراضــا عليــه يف حينــه لــدى املــرور وخرجــت جلنــة أخــرى‬\n      ‫وكتبــت التقريــر الثانــي وأنــا أمتســك بالتقريــر الثانــي ومــا جــاء يف‬\n      ‫اإلقــرار اخلطــي للمرافــق ‪...‬فــا أدري عنــه هكــذا أجــاب وأجــاب املدعى‬\n      ‫عليــه قائــا‪ :‬أنــا أرفــض التقريــر الثانــي وأمتســك بالتقريــر األول هكــذا‬\n      ‫أجــاب‪ .‬ويف يــوم األربعــاء املوافــق ‪1433/12/22‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي أصالــة ووكالــة ‪ ...‬واملدعــى عليــه ‪...‬وبســؤال‬\n      ‫املدعــي عــن اســتمارة الســيارة التــي وقــع عليهــا احلــادث املــروري أبــرز‬\n      ‫وثيقــة ملكيــة مركبــة باســمه برقــم هيــكل‪ ...‬نــوع ‪ ...‬ســنة الصنــع ‪...‬‬\n\n\n‫‪195‬‬\n\f‫اللــون ‪ ...‬رقــم اللوحــة (‪ )...‬وبســؤال املدعــي هــل مت تقديــر قيمــة الســيارة‬\n‫قبــل احلــادث وبعــده فأجــاب قائــا ‪ :‬لــم يتــم تقديــر قيمــة الســيارة حتــى‬\n‫اآلن وال زالــت التلفيــات علــى حالهــا بعــد احلــادث وهــي يف حجــز املــرور‬\n‫هكــذا أجــاب لــذا أمــرت بالكتابــة إلــى إدارة مــرور الريــاض تقديــر‬\n‫قيمــة الســيارة قبــل احلــادث وبعــده لــدى ثــاث معــارض ســيارات‪ .‬ويف يــوم‬\n‫الثالثــاء ‪1434/04/30‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــة‬\n‫ووكالــة ‪...‬واملدعــى عليــه ‪...‬ووردنــا جــواب مديــر إدارة مــرور الريــاض‬\n‫برقــم ‪ 1832/11/2/7‬وتاريــخ بــدون املتضمــن أن املركبــة (‪ )....‬مت‬\n‫بيعهــا عــن طريــق اللجنــة املختصــة علــى مكبــس احلديــد‪ .‬أ‪.‬ه ـ وبعــرض‬\n‫تقريــر احلــادث الثانــي علــى املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــر فيــه‬\n‫مــن إدانتــي مــن عــدم التأكــد مــن خلــو الطريــق وعــدم إلتزامــي املســار‬\n‫الصحيــح واعتــراض ســير الســيارة اآلخــرى فهــذا غيــر صحيــح هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬بــل مــا ذكــر يف تقريــر‬\n‫احلــادث الثانــي هــو الصحيــح هكــذا أجــاب وبســؤال املدعــي هــل لديــه‬\n‫بينــة تشــهد علــى املدعــى عليــه باألســباب املذكــورة يف تقريــر احلــادث‬\n‫أجــاب قائــا‪ :‬ليــس لــدي بينــة هكــذا أجــاب لــذا أفهمتــه أن لــه ميــن‬\n‫املدعــى عليــه علــى نفــي ذلــك فقبلهــا واســتعد املدعــى عليــه ببذلهــا‬\n‫فأذنــت لــه وحلــف قائــا‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن مــا ذكــر‬\n‫يف تقريــر احلــادث أننــي لــم أتأكــد مــن خلــو الطريــق ولــم ألتــزم املســار‬\n‫الصحيــح واعترضــت خــط ســير الســيارة اآلخــرى فهــذا غيــر صحيــح‬\n‫بــل تأكــدت مــن خلــو الطريــق وألتزمــت املســار الصحيــح هكــذا حلــف‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى التقريــر‬\n‫األول للحــادث والتقريــر الثانــي للحــادث ومبــا أن التقريــر األول للحــادث‬\n\n\n                                                                                      ‫‪196‬‬\n\f                                                                     ‫أقــرب للصــواب‬\n      ‫ألن صــورة احلــادث شــبيهة بالصــورة التــي ذكرهــا يف كشــاف القنــاع‬\n      ‫(‪ )131/4‬قــال‪( :‬وإن كانــت إحــدى الســفينتني واقفــة وكانــت األخــرى‬\n      ‫ســائرة واصطدمتــا فغرقتــا ضمــن قيــم الســفينة الســائرة الســفينة‬\n      ‫الواقفــة إن فــرط بــأن أمكنــه ردهــا ولــم يفعــل أو لــم يكمــل آلتهــا مــن‬\n      ‫رجــال وحبــال وغيرهمــا ألن التلــف حصــل بتقصيــره أشــبه مــا لــو نــام‬\n      ‫وتركهــا ســائرة بنفســها حتــى صدمتهــا وأمــا قيــم الواقفــة فــا ضمــان‬\n      ‫عليــه ألنــه لــم يوجــد منــه تعــد وال تفريــط أشــبه النائــم يف الصحــراء إذا‬\n      ‫عثــر بــه إنســان فتلــف ويأتــي إذا اصطــدم نفســان يف كتــاب الديــات‬\n      ‫مفصــا ‪ .‬وإن كانــت إحداهمــا منحــدرة واألخــرى مصعــدة فعلــى‬\n      ‫صاحبهــا أي‪ :‬املنحــدرة ضمــان املصعــدة ألن املنحــدرة تنحــط علــى‬\n      ‫املصعــدة مــن علــو فيكــون ذلــك ســببا لغرقهــا وال ضمــان علــى قيــم‬\n      ‫املصعــدة تنزيــا للمنحــدرة منزلــة الســائرة وللمصعــدة منزلــة الواقفــة)‪.‬‬\n      ‫أه ـ والســيارة التريــا يف ســيرها ببــطء أشــبه بالواقفــة كمــا أن ســائق‬\n      ‫الســيارة ‪ ....‬باشــر التلــف بصدمــه للســيارة التريــا مــن اخللــف وقــد كان‬\n      ‫ميكنــه تــايف التصــادم باالنتبــاه وأخــذ احليطــة واحلــذر وتــرك الســرعة‬\n      ‫ومبــا أن الطرفــان اختلفــا يف التعــدي حصــل ممــن فالقــول قــول منكــره‬\n      ‫وهــو ســائق التريــا ألنــه ُصــدم مــن اخللــف مــن قبــل الســيارة ‪ ....‬وهــو‬\n      ‫منكــر للخــروج املفاجــئ وحلــف اليمــن علــى نفــي ذلــك كمــا أن‬\n      ‫القاعــدة الشــرعية إذا اجتمــع املباشــر مــع املتســبب أضيــف احلكــم إلــى‬\n      ‫املباشــر قــال ابــن رجــب يف القواعــد ص (‪ )274‬القاعــدة (‪( :)127‬إذا‬\n      ‫اســتند إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وتســبب تعلــق‬\n      ‫الضمــان باملباشــرة دون الســبب)‪ .‬أه ـ وال يغلــب الســبب علــى املباشــرة إال‬\n\n\n‫‪197‬‬\n\f‫إذا تعــدى املتســبب وهــو مــا ينفيــه التقريــر املــروري األول وميــن املدعــى‬\n‫عليــه ويتفــق مــع مــا ذكــره الفقهــاء مــن تصــادم الســفينة الســائرة مــع‬\n‫الواقفــة لــذا قــررت رد دعــوى املدعــي وبــه حكمــت وبإعــان احلكــم‬\n‫قــرر املدعــي املعارضــة وطلــب االســتئناف وســلم صــورة احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يومــا فــإن مضــت املــدة ولــم يقــدم الئحــة‬\n‫اعتراضــه ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                    ‫حــرر يف ‪1434/04/30‬ه ـ‬\n‫ويف يــوم الثالثــاء ‪1434/07/25‬ه ـ افتتحــت اجللســة بنــاء علــى ورود‬\n‫املعاملــة بشــرح رئيــس احملكمــة علــى القيــد رقــم ‪341305820‬‬\n‫وتاريــخ ‪1434/07/18‬ه ـ وبرفقهــا خطــاب رئيــس محكمــة االســتئناف‬\n‫بالريــاض رقــم ‪ 341305820‬وتاريــخ ‪1434/07/12‬ه ـ وبرفقهــا قــرار‬\n‫الدائــرة اجلزائيــة الرابعــة رقــم ‪ 34258025‬وتاريــخ ‪1434/07/03‬ه ـ‬\n‫واملتضمــن املصادقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n                                  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائية الرابعة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم ‪ 34237071‬وتاريــخ‬\n‫‪ 1434 /05/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n             ‫باحملكمــة الشــيخ ‪.../‬املســجل برقــم ‪ 34201873‬وتاريــخ‬\n‫‪ 1434/ 04 /30‬ه ـ اخلــاص بدعــوى ‪...‬ضــد‪... /‬بشــأن حــادث مــروري‬\n‫علــى النحــو املوضــح بالصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل بــه و بدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n\n\n                                                                                    ‫‪198‬‬\n\f      ‫وأوراق املعاملــة قــررت الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلته‬\n      ‫ال وذلــك حســب املادة‬‫إلــى إثبــات اإلدانــة مــن عدمهــا قبــل احلكــم مســتقب ً‬\n      ‫‪ 3‬و ‪ 174‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬و اهلل املوفــق وصلــى اهلل علــى‬\n                                                ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪199‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":191,"source_page_end":199,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d74e11d3c63b09143ef1ad6e63fe0fb173b613d4acecffdadac284c116ca4b0c","normalized_text_hash":"f1718f7fe1e9cd10e6596ac4965e9386e96d8d7d8f7a7806598696112bb2fddf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p191-34201873"},{"id":"db023c61-1b6b-5b19-a67a-0b96cbe03204","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -مطالبة بدية مورث توفى بحادث مروري -دفع املدعى عليه بأن شركة التأمن هي املسؤولة عن دفع الدية -املباشرة مقدمة على التسبب -احلكم بإلزام املدعى عليه بدفع الدية حسب نسبة اإلدانة التي عليه -للمدعى عليه الرجوع على شركة التأمن أو","document_number":"33272212","case_number":"50245","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"دية -مطالبة بدية مورث توفى بحادث مروري -دفع املدعى عليه بأن شركة التأمن هي املسؤولة عن دفع الدية -املباشرة مقدمة على التسبب -احلكم بإلزام املدعى عليه بدفع الدية حسب نسبة اإلدانة التي عليه -للمدعى عليه الرجوع على شركة التأمن أو","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/22 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33272212 :‬‬\n                       ‫َر ْق ُم الدعوى‪50245 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3423835‬تاريخه‪1434/1/26 :‬هـ‬\n\n\n ‫ديــة ‪ -‬مطالبــة بديــة مــورث توفــى بحــادث مــروري ‪ -‬دفــع املدعــى عليــه‬\n ‫بــأن شــركة التأمــن هــي املســؤولة عــن دفــع الديــة‪ -‬املباشــرة مقدمــة‬\n ‫علــى التســبب‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع الديــة حســب نســبة‬\n ‫اإلدانــة التــي عليــه‪ -‬للمدعــى عليــه الرجــوع علــى شــركة التأمــن أو‬\n ‫قصــر ‪.‬‬\n      ‫العاقلــة بالديــة‪ -‬رفــع الدعــوى إلــى محكمــة االســتئناف لوجــود ّ‬\n\n\n\n ‫قــال ابــن رجــب ـ رحمــه اهلل ـ يف القواعــد ( قاعــدة ‪ « ) 127‬إذا اســتند‬\n ‫إتــاف أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وســبب ‪ ،‬تعلــق الضمــان‬\n ‫باملباشــرة دون الســبب ‪ ،‬إال إذا كانــت املباشــرة مبنيــة علــى الســبب‬\n ‫وناشــئة عنــه ســواء كانــت ملجئــة ثــم إن كانــت املباشــرة واحلالــة هــذه‬\n ‫ال عــدوان فيهــا بالكليــة اســتقل الســبب وحــده بالضمــان ‪ ،‬وإن كان‬\n                          ‫فيهــا عــدوان شــاركت الســبب الضمــان » ‪.‬‬\n\n\n\n\n ‫أقامــت املدعيتــان باألصالــة عــن نفســيهما وبالوكالــة عــن غيرهمــا‬\n ‫القصــر دعــوى تســليم ديــة مورثهمــا الــذي‬\n                                            ‫ّ‬   ‫واألولــى بواليتهــا عــن أبنائهــا‬\n ‫توفــى نتيجــة حــادث مــروري ‪ -‬صــادق املدعــى عليــه علــى ذلــك إال أنــه‬\n ‫رفــض تســليم الديــة مبــرر ًا أن عليهــم مطالبــة شــركة التأمــن‪ ،‬وقــد‬\n\n                                                                                      ‫‪200‬‬\n\f      ‫جــرى نظــر التقريــر املــروري والــذي أســند ‪ %75‬مــن اخلطــأ إلــى املدعــى‬\n      ‫عليــه وقــد نازعــت املدعيتــان يف نســبة اخلطــأ ثــم عادتــا وقنعتــا بهــذه‬\n      ‫النســبة ‪ ،‬وافــق املدعــى عليــه علــى تســليم الديــة املقــررة وأنــه ســيعود‬\n      ‫علــى شــركة التأمــن بعــد ذلــك وقنــع جميــع األطــراف باحلكــم وجــرى‬\n      ‫قصــر وجــرى التصديــق‬  ‫رفــع الدعــوى إلــى محكمــة االســتئناف لوجــود ّ‬\n                                                         ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 50245‬وتاريــخ ‪ 1431/11/25‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 31195226‬وتاريــخ ‪1431/11/22‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1433/3/12‬أفتتحــت اجللســة وقــد عــادت املعاملــة مــن‬\n      ‫مــرور منطقــة الريــاض بعــد شــطبها للمــرة األولــى بكتابهــم رقــم ‪.......‬‬\n      ‫يف ‪1433/1/17‬ه ـ املتضمــن أنــه قــد مت إبــاغ املدعيــن مبتابعــة القضية‬\n      ‫ويف هــذه اجللســة حضــرت ‪ .......‬ســورية اجلنســية حتمــل جــواز ســفر رقــم‬\n      ‫‪ .......‬والــذي تنتهــي الزيــارة بــه بتاريــخ ‪1433/4/4‬ه ـ بصفتهــا أصيلــة عن‬\n      ‫نفســها ووليــة علــى القاصــر ‪ .......‬مبوجــب صــك الواليــة وحصــر الورثــة‬\n      ‫الصــادر مــن احملكمــة الشــرعية بحمــاه برقــم ‪ .......‬يف ‪2011/5/25‬م‬\n      ‫واملصــادق عليــه مــن وزارتــي اخلارجيــة والعــدل يف اململكــة العربيــة‬\n      ‫الســعودية بتاريــخ ‪1433/3/8‬ه ـ واملتضمــن إقامــة املدعيــة وليــة علــى‬\n      ‫القاصــر ‪ .......‬املولــود يف ‪ 1997/1/1‬كمــا تضمــن انحصــار ورثــة‬\n      ‫‪ .......‬يف زوجتــه املدعيــة ‪ .......‬واوالده ‪ .......‬و ‪ .......‬و ‪ .......‬و ‪ .......‬و‬\n\n‫‪201‬‬\n\f‫‪ .......‬و ‪ .......‬ال وارثــه لــه ســواهم كمــا أبــرزت وكالتهــا عــن ‪ .......‬و‬\n‫‪ .......‬و ‪ .......‬أوالد ‪ .......‬مبوجــب الصــادرة مــن كاتــب العــدل بحمــاه‬\n‫رقــم ‪ .......‬جلــد ‪ 2636‬يف ‪1432/7/25‬ه ـ واملصــادق عليــه مــن وزارتــي‬\n‫اخلارجيــة والعــدل يف اململكــة العربيــة الســعودية بتاريــخ ‪1433/3/8‬ه ـ‬\n‫ووكالتهــا عــن ‪ .......‬الصــادرة مــن كاتــب العــدل بحمــاه برقــم ‪.......‬‬\n‫يف ‪ 2648‬يف ‪1432/11/14‬ه ـ واملصــادق عليــه مــن وزارتــي اخلارجيــة‬\n‫والعــدل يف اململكــة العربيــة الســعودية بتاريــخ ‪1433/3/8‬ه ـ وقــد‬\n‫تضمنــت الوكالتــان أن لهــا احلــق يف املطالبــة واســتالم ديــة مورثهــم‬\n‫‪ .......‬كمــا حضــرت ‪ .......‬ســورية اجلنســية حتمــل رخصــة اإلقامــة رقــم‬\n‫‪ .......‬واملعــرف باملدعيتــن احلاضــر ‪ .......‬حامــل الســجل املدنــي رقــم‬\n‫‪ .......‬ولــم يحضــر املدعــى عليــه ولــم يظهــر تبلغــه مبوعــد هــذه اجللســة‬\n‫وقــد قــررت املدعيتــان أنهمــا ال يعرفــان محــل إقامــة املدعــى عليــه‬\n‫هكــذا قررتــا هــذا وســتجري الكتابــة منــا إلمــارة منطقــة الريــاض‬\n‫إلبــاغ املدعــى عليــه مبوعــد اجللســة القادمــة بنــاء علــى املــادة ‪/18‬ط مــن‬\n‫نظــام املرافعــات الشــرعية ويف جلســة أخــرى بتاريــخ ‪ 1433/03/28‬ه ـ‬\n‫حضــرت املدعيتــان واملعــرف بهمــا احلاضــرون يف اجللســة املاضيــة كمــا‬\n‫حضــر املدعــى عليــه ‪ .......‬حامــل بطاقــة الهويــة الوطنيــة رقــم ‪ .......‬وقــد‬\n‫ادعــت املدعيتــان قائلتــان إن هــذا احلاضــر املدعــى عليــه ‪ .......‬قــد حصــل‬\n‫بينــه وبــن مورثنــا ‪ .......‬حــادث تصــادم بحــي النســيم مبدينــة الريــاض‬\n‫عــام ‪1430‬ه ـ تقريبــا نتــج عنــه وفــاة مورثنــا وقــد حضــر املــرور للموقــع‬\n‫وقــرر نســبة احلــادث ب ــنسبة ‪ %75‬علــى املدعــى عليــه نطلــب احلكــم علــى‬\n‫املدعــى عليــه بتســليمنا ديــة مورثنــا املســلم هــذه دعوانــا وبعــرض ذلــك‬\n‫علــى املدعــى عليــه مــا ذكرتــه املدعيتــان يف دعواهمــا فهــو صحيــح‬\n\n\n                                                                                      ‫‪202‬‬\n\f      ‫جملــة وتفصيــا وقــد حضــرت لقســم املــرور ومت إيقــايف ثــم أخلــي‬\n      ‫ســبيلي مبوجــب بطاقــة تأمــن علــى شــركة ‪ ....‬ثــم مت اســتدعائي مــن‬\n      ‫قبــل القاضــي باحملكمــة املســتعجلة ومت عــرض النســبة علــي وتصديــق‬\n      ‫موافقتــي عليهــا ومــن ثــم خرجــت وحتــى اليــوم كنــت أظــن أنهــم قــد‬\n      ‫انتهــوا مــن املوضــوع وأنــا ال مانــع لــدي مبــا أقــررت بــه مبوجــب بطاقــة‬\n      ‫التأمــن ولــن أســلمهم املبلــغ املدعــى بــه وعليهــم مطالبــة التأمــن هكــذا‬\n      ‫أجــاب هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة والتــي مــن ضمنهــا‬\n      ‫تقريــر إدارة املــرور املرفــق باملعاملــة علــى لفــة ‪ 10‬رقــم ‪ .......‬تاريــخ‬\n      ‫‪1431/9/2‬ه ـ واملتضمــن نــوع احلــادث ‪ :‬دهــس ‪ .‬زمــن احلــادث وتاريخــه ‪:‬‬\n      ‫الســاعة ‪ 11.50‬م يــوم اجلمعــة املوافــق ‪1430/8/30‬ه ـ مــكان احلــادث ‪:‬‬\n      ‫حــي النســيم ‪ .‬مــن قبــل الســائق ‪ :‬الطــرف األول ‪ ....... /‬ســعودي اجلنســية‬\n      ‫( ‪ ) .......‬الطــرف الثانــي املاشــي ‪ ....... /‬ســوري اجلنســية ( ‪ ) .......‬نتائــج‬\n      ‫احلــادث ‪ :‬وفــاة املاشــي ‪ ....... /‬مســئولية احلــادث وبيانــات أســباب اإلدانــة‬\n      ‫‪ :‬تقــع نســبة ‪ %75‬علــى الطــرف األول ‪ ....... /‬األســباب اآلتيــة ‪ -1‬عــدم‬\n      ‫االنتبــاه ‪ -2‬عــدم أخــذ احليطــة واحلــذر ‪ -3‬عــدم تــايف احلــادث وتقــع نســبة‬\n                                           ‫‪ %25‬علــى املاشــي ‪ ....... /‬األســباب اآلتيــة‬\n      ‫‪ -1‬عــدم التأكــد مــن خلــو الطريــق ‪ -2‬عــدم االنتبــاه أ‪.‬ه ـ وبعــرض‬\n      ‫التقريــر عليهمــا قالــت املدعيتــان إن هــذه النســبة قليلــة فاملدعــى عليــه‬\n      ‫يتحمــل نســبة ‪ %100‬مــن احلــادث هكــذا أجابتــا كمــا قــرر املدعــى عليه‬\n      ‫قائــا بــأن النســبة عاليــة وقــد صادقــت عليهــا عنــد املــرور ظنــا منــي بــأن‬\n      ‫شــركة التأمــن هــي التــي ستســلم املبلــغ ولكــن اخلطــأ مــن مــورث‬\n      ‫املدعــن بقطعــه الطريــق املخصــص للســيارات هكــذا أجــاب لــذا قررت‬\n      ‫الكتابــة إلدارة املــرور لإلفــادة عمــا جــاء يف إجابــات املدعيتــان واملدعــى‬\n\n\n‫‪203‬‬\n\f‫عليــه املرصــودة أعــاه ويف جلســة أخــرى بتاريــخ ‪ 1433/05/25‬هـ وفيها‬\n‫حضــرت املدعيــة ‪ .......‬أصالــة ووكالــة وواليــة كمــا حضــرت ‪.......‬‬\n‫واملعــرف بهمــا مــن قبــل ‪ .......‬احلاضــرون يف اجللســة الســابقة كما حضر‬\n‫املدعــى عليــه احلاضــر يف اجللســة الســابقة هــذا وقــد قــرر احلاضــرون أنهم‬\n‫عدلــوا عــن اإلســتمرار يف الكتابــة لقســم املــرور املشــار لــه يف اجللســة‬\n‫الســابقة وذلــك ملــا حصــل مــن اإلتفــاق بــن جميــع األطــراف علــى التقريــر‬\n‫الــوارد ســابقا مــن إدارة املــرور رقــم ‪ .......‬وتاريــخ ‪1431/09/02‬ه ـ‬\n‫واملرفــق ضمــن أوراق املعاملــة واملتضمــن (أن مســؤلية احلــادث تقــع بنســبة‬\n‫‪ %75‬علــى الطــرف األول ‪ .......‬وتقــع بنســبة ‪ %25‬علــى املاشــي ‪....... /‬‬\n‫)أ‪.‬ه ـ واملشــار لــه يف اجللســة الســابقة هــذا كمــا جــرى اإلطــاع علــى‬\n‫القــرار الصــادر مــن احملكمــة اجلزئيــة بالريــاض مــن املكتــب القضائــي‬\n‫الثالــث والعشــرين رقــم القــرار ‪ 2300104523008310006‬وتاريــخ‬\n‫‪1431/02/25‬ه ـ املجلــد ‪ 1‬واملتضمــن ( ثبــوت إدانــة املدعــى عليــه ‪.......‬‬\n‫مبســؤوليته عــن احلــادث بنســبة‪ %75‬واملفهــم فيــه بــأن عليــه كفــارة قتــل‬\n‫اخلطــأ والــذي قــرر فيــه قناعتــه مبــا حكم)أ‪.‬ه ـ وقــد قــرر املدعــى عليــه‬\n‫قائــا أصــادق علــى إدانتــي بنســبة ‪ %75‬مــن احلــادث ومســتعد لتســليم‬\n‫املدعــن الديــة وســأطالب شــركة التأمــن بذلــك بعــد صــدور احلكــم‬\n‫علــي هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرره‬\n‫جميــع األطــراف مــن قناعتهــم بتقريــر املــرور املشــار إليــه أعــاه وملــا جــاء‬\n‫يف القاعــدة ( ‪ ) 127‬مــن قواعــد ابــن رجــب ونصهــا ( إذا اســتند إتــاف‬\n‫أمــوال اآلدميــن ونفوســهم إلــى مباشــرة وســبب تعلــق الضمــان باملباشــرة‬\n‫دون الســبب إال إذا كانــت املباشــرة مبنيــة علــى الســبب وناشــئة عنــه‬\n‫ســواء كانــت ملجئــة ثــم إن كانــت املباشــرة واحلالــة هــذه ال عــدوان‬\n\n\n                                                                                        ‫‪204‬‬\n\f      ‫فيهــا بالكليــة اســتقل الســبب وحــده بالضمــان وإن كان فيهــا عــدوان‬\n      ‫شــاركت الســبب يف الضمــان ) أ ه ـ فقــد ألزمــت املدعــى عليــه ‪.......‬‬\n      ‫أن يســلم مبــا نســبته ‪ %75‬مــن ديــة قتــل اخلطــأ املســلم للمدعيتــان أصالــة‬\n      ‫ووكالــة وواليــة وقدرهــا مائتــان وخمســة وعشــرون ألــف ريــال تقســم‬\n      ‫بــن ورثــة ‪ .......‬حســب امليــراث الشــرعي وبــه حكمــت كمــا أفهمــت‬\n      ‫املدعــى عليــه بــأن لــه مطالبــة عاقلتــه بقيمــة الديــة املذكــورة أعــاه‬\n      ‫وبعــد إعــان احلكــم قنــع بــه جميــع األطــراف وقــررت بعثــه حملكمــة‬\n      ‫اإلســتئناف لتدقيقــه لوجــود قاصــر ولــم يحكــم بكامــل الديــة‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪ 1433/05/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/08/14‬ه ـ‬\n      ‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 331114459‬وتاريــخ ‪1433/7/20‬ه ـ واملرفــق بــه قــرار الدائــرة األولــى‬\n      ‫لتمييــز القضايــا اجلزائيــة برقــم ‪ 33338478‬وتاريــخ ‪1433/07/13‬ه ـ و‬\n      ‫نــص احلاجــة منــه مــا يلــي ( لوحــظ أن فضيلتــه ذكــر يف الســطر الثامــن‬\n      ‫و التاســع مــن الصفحــة األولــى مــن الصــك انحصــار إرث املتوفــى علــي‬\n      ‫املذكــور يف زوجتــه وأوالده املذكوريــن ال وارث لــه ســواهم بينمــا‬\n      ‫يوجــد يف صــك حصــر اإلرث الــذي أشــار إليــه فضيلتــه أن والــدة‬\n      ‫املتوفــى مــن ضمــن الورثــة ولــم يوجــد مــا يثبــت حضورهــا أو توكيلهــا‬\n      ‫فعلــى فضيلتــه إجــراء مــا يلــزم و تصحيــح اخلطــأ يف الســطر اخلامــس‬\n      ‫مــن الصفحــة األولــى و املعلــم عليــه بقلــم الرصــاص و إيضــاح نصيــب‬\n      ‫كل وارث مــن الديــة كمــا إن إفهامــه بالرجــوع علــى العاقلــة فيــه نظــر‬\n      ‫مــع مــا ذكــره مــن وجــود بطاقــة تأمــن كمــا أن فضيلــة القاضــي لــم‬\n\n\n‫‪205‬‬\n\f‫يقســم الديــة علــى الورثــة ويوضــح ســهم أو نصيــب كل وارث ومــن يســلم‬\n‫لــه نصيــب القاصر)أ‪.‬ه ـ وفيهــا حضــرت املدعيــة أصالــة ووكالــة وواليــة‬\n‫‪ .......‬واملدعيــة ‪ .......‬واملعــرف بهمــا مــن قبــل ‪ .......‬احلاضــر يف اجللســة‬\n‫املاضيــة كمــا حضــر املدعــى عليــه‪ ،‬وجــرى تصحيــح اخلطــأ الكتابــي‬\n‫يف الصــك ‪ ،‬وأمــا الرجــوع علــى العاقلــة فلــم يظهــر لــي ســوى مــا أجريتــه‬\n‫‪ ،‬وجــرى االطــاع علــى صــك حصــر الورثــة فوجدنــا أن مــن ضمــن‬\n‫ورثتــه والدتــه ‪ .............‬وقــررت املدعيــة قائلــة‪ :‬إن أم مورثنــا ال تســتطيع‬\n‫احلضــور وال التوكيــل الضطــراب األوضــاع يف ســوريا نطلــب تســليمنا‬\n‫نصيبنــا مــن الديــة دون نصيــب األم وهــو مبلــغ وقــدره ســبعة وثالثــن‬\n‫ألفــا وخمســمائة ريــال وكذلــك تســليمي نصيــب القاصــر ‪ .......‬للنفقــة‬\n‫عليــه منــه هكــذا قــررت‪ .‬لــذا فقــد رجعــت عمــا حكمــت بــه ســابقا‬\n‫وألزمــت املدعــى عليــه بــأن يســلم للمدعــن أصالــة ووكالــة وواليــة مــن‬\n‫ديــة مورثهــم وهــو مبلــغ وقــدره مائــة وســبعة وثمانــون ألفــا وخمســمائة‬\n‫ريــال‪ ،‬نصيــب الزوجــة منــه مبلغــا وقــدره ثمانيــة وعشــرون ألفــا ومائــة‬\n‫وخمســة وعشــرون ريــاال‪ ،‬ونصيــب كل واحــد مــن األبنــاء مبلــغ وقــدره‬\n‫واحــد وثالثــون ألفــا وثمامنائــة وخمســة وســبعني ريــاال‪ ،‬ونصيــب كل‬\n‫بنــت مبلــغ وقــدره خمســة عشــر ألفــا وتســعمائة وســبعة وثالثــون ريــاال‬\n‫ونصــف الريــال‪ .‬وتســليم نصيــب القاصــر لوليتــه املدعيــة ‪ .......‬وبــه‬\n‫حكمــت وبعــد إعالنــه قنعــوا بــه وقــررت إحلــاق ذلــك بالصــك وســجله‬\n‫وإعــادة املعاملــة حملكمــة االســتئناف‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/14‬هـ‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم االثنــن ‪1433/12/20‬ه ـ افتتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف بكتابهــم رقــم‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪ 33164340‬يف ‪1433/11/2‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى‬\n      ‫برقــم ‪ 33426238‬يف ‪1433/10/15‬ه ـ ونــص احلاجــة منــه‪( :‬وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قــرار الدائــرة رقــم ‪ 333387478‬وتاريــخ ‪1433/7/13‬ه ـ لوحظ أن‬\n      ‫صــك حصــر الوراثــة والوصايــة والوكالــة غيــر مكتملــة يف تصديقاتهــا‬\n      ‫حســب التعليمات من وزارة اخلارجية الســعودية ووزارة العدل الســعودية)‬\n      ‫اهــ‪ .‬وعليــه جنيــب أصحــاب الفضيلــة بــأن الــوكاالت وحصــر الورثــة‬\n      ‫والواليــة مصدقــة مــن وزارتــي اخلارجيــة والعــدل الســعوديتني‪ ،‬ولكــن‬\n      ‫لــم تصــور التصديقــات ألنهــا يف خلــف الصكــوك‪ ،‬وقــد مت تصويرهــا‬\n      ‫‪ ،‬وقــررت رفــع املعاملــة حملكمــة االســتئناف إلكمــال الــازم حســب‬\n      ‫املتبــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/20‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331958164‬وتاريــخ ‪1433/12/22‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪....... /‬‬\n      ‫املسجل برقم ‪ 33272212‬وتاريخ ‪1433/5/29‬هـ اخلاص بدعوى‪ /‬ورثة‬\n      ‫‪ .......‬ضــد ‪ .......‬بشــأن طلبهــم النســبة املقــررة مــن ديــة مورثهــم املوضحــة‬\n      ‫بالصــك واملتضمــن أن فضيلتــه حكــم مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى القــرار‬\n      ‫رقــم ‪ 33426238‬وتاريــخ ‪1433/10/15‬ه ـ تقــرر الدائــرة املصادقــة على‬\n\n\n‫‪207‬‬\n\f                                ‫احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n‫واهلل املوفق وصلى اهلل على نبينا محمد و على آله وصحبه وسلم ‪.‬‬\n\n\n\n\n                                                                    ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":200,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"59d70df0d43cb58df2b7ec3648ed70e57e5191798d036cf53cac56bcd1fae28e","normalized_text_hash":"713d2ee50bc1a971f0f712514edada3d5deba5453719266eb6010fdff9673c52","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p200-33272212"},{"id":"a3ba3d04-6804-5608-9e0f-8785213f2683","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري -طلب تسليم دية متوفى -إقرار املدعى عليه -مشاركة املدعى عليه املتوفى اخلطأ يف احلادث -تقرير املرور من جنس رأي اخلبير تستأنس به المحكمة وال يلزمها -من تسبب يف موت إنسان معصوم لزمته ديته عدم األخذ بتقرير املرور يف مقدار نسبة اإلدانة -دية القتل اخلطأ مؤجلة ثاث سنوات كفارة قتل اخلطأ .","document_number":"3450453","case_number":"32185860","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/30","year":"1434","subject":"دية متوفى -حادث مروري -طلب تسليم دية متوفى -إقرار املدعى عليه -مشاركة املدعى عليه املتوفى اخلطأ يف احلادث -تقرير املرور من جنس رأي اخلبير تستأنس به المحكمة وال يلزمها -من تسبب يف موت إنسان معصوم لزمته ديته عدم األخذ بتقرير املرور يف مقدار نسبة اإلدانة -دية القتل اخلطأ مؤجلة ثاث سنوات كفارة قتل اخلطأ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/30 :‬هـ َر ْق ُم‬\n                               ‫ُ‬                ‫َر ْق ُم َّ‬\n                                   ‫الص ِّك‪3450453 :‬‬\n                                    ‫الدعوى‪32185860 :‬‬\n                  ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                        ‫‪ 34202202‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n         ‫ديــة متوفــى ‪ -‬حــادث مــروري ‪ -‬طلــب تســليم ديــة متوفــى ‪ -‬إقــرار املدعــى‬\n         ‫عليــه ‪ -‬مشــاركة املدعــى عليــه املتوفــى اخلطــأ يف احلــادث ‪ -‬تقريــر‬\n         ‫املــرور مــن جنــس رأي اخلبيــر تســتأنس بــه احملكمــة وال يلزمهــا ‪ -‬مــن‬\n         ‫تســبب يف مــوت إنســان معصــوم لزمتــه ديتــه ـ عــدم األخــذ بتقريــر املــرور‬\n         ‫يف مقــدار نســبة اإلدانــة ‪ -‬ديــة القتــل اخلطــأ مؤجلــة ثــاث ســنوات ـ‬\n                                                                  ‫كفــارة قتــل اخلطــأ ‪.‬‬\n\n\n\n         ‫‪ .1‬قولــه تعالــى ‪ ( :‬ومــن قتــل مؤمن ـ ًا متعمــد ًا فتحريــر رقبــة مؤمنــة‬\n                                                         ‫وديــة مســلمة إلــى أهلــه ) ‪.‬‬\n              ‫‪ .2‬مسألة ( ما لو اصطدم راكب وسائر ) ينظر ‪ :‬كشاف القناع‬\n                                                                          ‫( ‪) 2918/8‬‬\n                ‫‪ .3‬ما نص عليه الشيخ محمد بن إبراهيم يف فتاويه ( ‪) 316/11‬‬\n         ‫‪ .4‬مــن تســبب يف مــوت إنســان معصــوم لزمتــه ديتــه ( الــروض املربــع‬\n                                                                               ‫‪. ) 646‬‬\n         ‫‪ .5‬مــا قــرره أهــل العلــم أن ديــة قتــل اخلطــأ مؤجلــة علــى ثــاث ســنوات‬\n         ‫مــن حينــه وهــي علــى العاقلــة‪ .‬ينظــر كشــاف القنــاع ( ‪) 2968-2913/8‬‬\n         ‫وهــذا قــول عمــر وعلــي رضــي اهلل عنهمــا ـ ولــم يعــرف لهمــا مخالــف‬\n                                 ‫فــكان إجماع ـ ًا ‪ ،‬فيكــون كل ســنة ثلــث الديــة ‪.‬‬\n         ‫‪ .6‬مــا قــرره األصحــاب أن الوكيــل يف القبــض لــه أن يخاصــم ‪ ،‬قــال يف‬\n‫‪209‬‬\n\f‫الــروض املربــع ( ‪( : ) 398‬الوكيــل يف القبــض لــه اخلصومــة ‪ ،‬ألنــه ال‬\n                           ‫يتوصــل إليهــا إال بهــا ‪ ،‬فهــو أذن فيهــا عرفـ ًا )‪.‬‬\n‫‪ .7‬األمــر الســامي البرقــي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ املبنــي علــى‬\n       ‫قــرار احملكمــة العليــا بهيئتهــا العامــة رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ ‪.‬‬\n\n\n\n\n‫حضــر املدعــي بالوكالــة عــن ورثــة امليــت وقــد خـ ّـول لــه يف الوكالــة‬\n‫بتحصيــل الشــيك ملبلــغ التعويــض مــن صاحــب الســيارة ‪ ،‬وجميــع‬\n‫الــوكاالت والصكــوك مصــادق عليهــا مــن اجلهــات الرســمية ‪ ،‬وقــرر‬\n‫ناظــر القضيــة اإلذن لــه بتحريــر دعــواه ‪ ،‬ألن الوكيــل يف القبــض لــه‬\n‫أن يخاصــم كمــا قــرره احلنابلــة ‪ ،‬طلــب املدعــي وكالــة تســليمه ديــة‬\n‫املتوفــى ـ بعــرض دعــوى املدعــي وكالــة علــى املدعــى عليــه أنكــر مــا‬\n‫ال فخــرج إليه املتوفى‬ ‫جــاء فيهــا وقــرر أنــه كان يســير يف طريــق مظلم لي ً‬\n‫فجــأة واصطــدم بــه ـ أقــر أن شــركة التأمــن مســتعدة لدفــع مــا يحكــم‬\n‫بــه شــرع ًا ـ مت االطــاع علــى محضــر املعاينــة ومحضــر نســبة احلــادث‬\n‫املــروري املعــد مــن قبــل رجــال املــرور واملتضمــن أن املدعــى عليــه يتحمــل‬\n‫نســبة ‪ % 25‬مــن مســؤولية احلــادث ـ ظهــر للقاضــي أن العــدل واحلالــة هــذه‬\n‫أن يتحمــل كل واحــد منهــا نصــف الضمــان ـ تقريــر املــرور مــن جنــس‬\n‫رأي اخلبيــر ‪ ،‬ال تلــزم بــه احملكمــة ـ مــن تســبب يف مــوت إنســان معصــوم‬\n‫لزمتــه ديتــه ـ االطــاع علــى األمــر الســامي املتضمــن أن ديــة قتــل اخلطــأ‬\n‫ثالثمائــة ألــف ريــال ـ قــرر أهــل العلــم أن ديــة اخلطــأ تكــون علــى العاقلــة‬\n‫‪ ،‬وتكــون مؤجلــة ملــدة ثــاث ســنوات مــن حينــه كل ســنة ثلــث الديــة ـ‬\n‫احلكــم علــى املدعــى عليــه بتســليم املدعــن نصــف الديــة مائــة وخمســن‬\n\n                                                                                        ‫‪210‬‬\n\f      ‫ألــف ريــال ـ احلكــم بــرد دعــوى املدعــن فيمــا زاد عــن ذلــك وإفهــام‬\n      ‫املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ وهــي عتــق رقبــة مؤمنــة فــإن‬\n      ‫لــم يجــد فصيــام شــهرين متتابعــن ‪ -‬إفهــام املدعــى عليــه بالرجــوع علــى‬\n      ‫العاقلــة ـ قــرر املدعــى وكالــة قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم‬\n                               ‫قناعتــه صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32185860‬وتاريــخ ‪1432/05/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 32575949‬وتاريــخ ‪ 1432/05/20‬ه ـ‬\n      ‫حضــر ‪ ...‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬بصفتــه وكيــا‬\n      ‫ورثــة ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل بكاماريــدي‬\n      ‫بالهنــد برقــم ‪ 043053‬ايــه ‪ 45‬يف ‪2012/2/7‬م واملصدقــة مــن اجلهــات‬\n      ‫ذات العالقــة آخرهــا فــرع وزارة العــدل مبكــة املكرمــة برقــم ‪2045‬‬\n      ‫يف ‪1433/8/17‬ه ـ والتــي تخولــه حتصيــل الشــيك ملبلــغ التعويــض مــن‬\n      ‫صاحــب الســيارة اجلانــي إلــخ والورثــة هــم ‪ ...‬و ‪ ...‬و ‪ ...‬احملصــور بحصــر‬\n      ‫الورثــة الصــادر مــن حكومــة آنداهــر إبراديــش برقــم ‪44/21/2012‬‬\n      ‫يف ‪2012/1/3‬م املصــدق مــن اجلهــات ذات االختصــاص أخرهــا فــرع‬\n      ‫وزارة العــدل مبكــة كمــا حضــر املدعــى عليــه ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬ونظــر ًا ملــا قــرره األصحــاب أن الوكيــل‬\n      ‫يف القبــض لــه أن يخاصــم قــال يف الــروض املربــع ص ‪( 398‬الوكيــل‬\n      ‫يف القبــض لــه اخلصومــة ألنــه ال يتوصــل إليــه إال بهــا فهــو أذن فيهــا‬\n\n‫‪211‬‬\n\f‫عرف ـاً) فقــد قــررت الســير بالقضيــة لــذا ســألته عــن دعــواه فقــال‬\n‫بواســطة مترجــم احملكمــة ‪ ...‬باكســتاني اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ ...‬أن املدعــى عليــه صــدم مــورث موكلــي بســيارته وتوفــى علــى‬\n‫أثــر ذلــك أطلــب احلكــم عليــه بتســليمي ديــة املتوفــى وأســاله اجلــواب‬\n‫هــذه دعــواي فطلبــت منــه بيانهــا وزيــادة إيضاحهــا فقــال لــم أكــن‬\n‫حاضــر ًا يف احلــادث فأطلــب االطــاع علــى ملــف املعاملــة ورصــد مــا يلــزم‬\n‫مــن واقــع األوراق املرفقــة والتحقيقــات وبعرضهــا علــى املدعــى عليــه‬\n‫قــال مــا ذكــره املدعــي أننــي صدمــت مــورث موكلــه غيــر صحيــح‬\n‫والصحيــح أننــي كنــت أســير علــى ســيارتي ‪ ...‬علــى طريــق املدينــة‬\n‫القــدمي اخلــارج مــن عســفان املتجــه شــما ًال إلــى خليــص وحينمــا حاذيــت‬\n‫مصنــع ‪ ...‬للبلــك كان هنــاك اشــخاص قادمــون مــن جهــة املصنــع علــى‬\n‫الطريــق الســريع اجلديــد علــى يســاري يريــدون قطــع الطريــق وحينمــا‬\n‫قربــت منهــم كان هنــاك مجموعــة قطعــت الطريــق ومجموعــة بقيــت‬\n‫لــم تقطــع فقربــت بســيارتي فخــرج علــي مــورث املدعــن فجــأة مــن بــن‬\n‫ا واملــكان مظلم ـ ًا‬  ‫األشــخاص الذيــن لــم يقطعــوا وكان الوقــت لي ـ ً‬\n‫وحاولــت تفاديــه وانحرفــت إلــى جهــة اليمــن إال أنــه حلقنــي وصــدم‬\n‫بســيارتي مبرآتهــا اليســرى وكانــت الضربــة علــى رأســه ومــا يحكــم‬\n‫علــي بــه فشــركة التأمــن التــي تعاقــدت معهــا مســتعدة بتســليم ذلــك‬\n‫هكــذا أجــاب وبعرضــه علــى املدعــي وكالــة قــال مــا ذكــره املدعــى‬\n‫عليــه فــا أعلمــه عنــه لكــن أصدقــه علــى ذلــك ألننــي لــم أكــن حاضــر ًا‬\n‫وال احــد مــن الورثــة هكــذا قــرر ثــم أطلعــت علــى أوراق املعاملــة فرأيــت‬\n‫دفتــر التحقيــق علــى لفــه (‪ )1‬ص ‪ 2‬وفيــه مــا نصــه محضــر معاينــة بتاريــخ‬\n‫‪1431/6/17‬ه ـ البــاغ تبلغــت أنــا رئيــس رقبــاء ‪ ...‬ضابــط خفــر حــوادث‬\n\n\n                                                                                   ‫‪212‬‬\n\f      ‫الغــرب بتاريــخ ‪1431/6/17‬ه ـ مبنطقــة غــران بالقــرب مــن مصنــع‪...‬‬\n      ‫عــن وقــوع حــادث مــروري عبــارة عــن دهــس شــخص مــن قبــل ســيارة‬\n      ‫‪ ...‬رقــم اللوحــة ‪ ...‬موديــل ‪ ...‬جنــم عــن احلــادث وفــاة الشــخص املدهــوس‬\n      ‫اإلجــراء املتخــذ مت االنتقــال الفــوري والســريع إلــى موقــع احلــادث بعــد‬\n      ‫إبــاغ الشرشــورة تنقــل املتوفــى والســطحه لتنقــل الســيارة إلــى احلجــز‬\n      ‫كيفيــة وقــوع احلــادث وقــع احلــادث علــى الطريــق الواصــل بــن عســفان‬\n      ‫وخليــص ومبنطقــة غــران بالقــرب مــن مصنــع ‪ ...‬والطريــق عبــارة خــط‬\n      ‫اجتــاه واحــد ذهــاب و إيــاب وكان الســائق يســير يف مســاره الصحيــح‬\n      ‫تفاجــأ مبجموعــة مــن العمــال يعبــرون الطريــق وإذا أحــد العمــال يتأخــر‬\n      ‫عــن البقيــة ممــا أدى إلــى صدمــه مــن قبــل الســائق باجلانــب األيســر مــن‬\n      ‫بــاب الســائق مــع املــراه وكان أســباب احلــادث عــدم آخــذ احليطــة واحلــذر‬\n      ‫مــن الســائق الطقــس ومحضــر التفتيــش الرويــة احلــادث وقــع يف الليــل‬\n      ‫الســاعة ‪ 8،30‬تقريب ـ ًا والطريــق غيــر منــور واليوجــد عوائــق حتجــب‬\n      ‫الرؤيــا أثنــاء القيــادة وقــع تفتيــش الســيارة وال يوجــد مــا يوجــب الرفــع‬\n      ‫عنــه مــن احملرمــات وغيرهــا ضابــط القضيــة ‪ ...‬توقيــع أ‪.‬ه ـ ويف ص‪9‬‬\n      ‫محضــر نســبة حــادث مــروري يــدان الســائق ‪ ...‬بنســبة ‪ %25‬مــن احلــادث‬\n                                               ‫املــروري وذلــك لألســباب التاليــة ‪:‬‬\n                                           ‫‪1‬ـ عدم أخذ احليطة واحلذر أثناء القيادة‬\n      ‫‪2‬ـ يحمــل رخصــة قيــادة والواجــب عليــه التقيــد بأنظمــة وقواعــد املــرور‬\n      ‫أثنــاء القيــادة ‪ ،‬ثانيـ ًا يــدان الشــخص املدهــوس بنســبة ‪ %75‬مــن احلــادث‬\n      ‫املــروري لألســباب التاليــة ‪1‬ـ قطــع اخلــط عرضـ ًا مــن قبــل املدهــوس دون‬\n      ‫التأكــد مــن خلــوه مــن الســيارات ‪ -2‬البــد أنــه رأى الســيارة علــى بعــد‬\n      ‫مــن ســيرها وذلــك بواســطة االنــوار األماميــة وميكــن عــرض حياتــة‬\n\n\n‫‪213‬‬\n\f‫خلطــر مميــت كمــا حصــل ‪ -3‬كونــه عاقــا و مــدركا ملخاطــر‬\n‫الطريــق كان املفــروض ان يكــون حــذر ًا ضابــط خفــر رئيــس رقبــاء ‪...‬‬\n‫و ضابــط التحقيــق نقيــب ‪ ...‬و مديــر شــعبة احلــوادث مقــدم ‪ ...‬أ‪.‬ه ـ وبعــد‬\n‫التأمــل يف الدعــوى واإلجابــة ونظــرا ملــا قــرره املدعــى عليــه مــن صفــة‬\n‫وقــوع احلــادث وتصديــق املدعــي وكالــة علــى ذلــك وألن مــورث املدعــن‬\n‫بذلــك يعتبــر مفرطـ ًا يف حفــظ نفســه واالحتيــاط لهــا فيكــون مشــارك ًا‬\n‫للمدعــى عليــه يف اخلطــأ ونظــر ًا ملــا جــاء يف أقــوال املدعــى عليــه ان‬\n‫الطريــق كان مظلمـ ًا وأن أمامــه أنــاس يريــدون قطــع الطريــق فالواجــب‬\n‫ملثــل ذلــك أن يحــذر ويحتــاط ويخفــف ســرعته حتســب ًا ألي عــارض علــى‬\n‫الطريــق وعليــه فهــو مــدان يف ذلــك يتحصــل مــن مجمــوع ذلــك اشــتراك‬\n‫الطرفــن يف الضمــان نظــر ًا الشــتراكهما يف ســبب اجلنايــة فالعــدل أن‬\n‫يتحمــل كل واحــد منهمــا نصــف الضمــان وينظــر يف مثــل ذلــك مــا نــص‬\n‫عليــه األصحــاب يف مســألة مــا لــو اصطــدم راكــب وســائر ينظــر يف‬\n‫كشــاف القنــاع ص ‪ 2918‬ج ‪ 8‬وكــذا مــا نــص عليــه الشــيخ محمــد بــن‬\n‫إبراهيــم يف فتاويــه ‪ 316/11‬وعليــه يتحمــل املدعــى عليــه نصــف الديــة‬\n‫وأمــا تقريــر املــرور فهــو مــن جنــس رأي اخلبيــر تســتأنس بــه احملكمــة وال‬\n‫يقيدهــا كمــا نصــت املــادة ‪ 134‬مــن نظــام املرافعــات الشــرعية ونظــرا‬\n‫ملــا قــرره اهــل العلــم ان مــن تســبب يف مــوت انســان معصــوم لزمتــه ديتــه‬\n‫الــروض املربــع ص‪ 646‬وهــي هنــا النصــف كمــا شــرحته وتاسيســا‬\n‫علــى قولــه تعالــى (ومــن قتــل مؤمنــا متعمــدا فتحريــر رقبــة مؤمنــه وديــة‬\n‫مســلمة الــى اهلــه ) ونظــرا ملــا جــاء يف تعميــم املجلــس االعلــى للقضــاء‬\n‫رقــم ‪/192‬ت يف ‪1432/10/9‬ه ـ مبــا قررتــه احملكمــة العليــا بهيئتهــا‬\n‫العامــه بالقــرار رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ ان ديــة القتــل اخلطــا الكاملــة‬\n\n\n                                                                                    ‫‪214‬‬\n\f      ‫ثالثمائــة الــف ريــال واملعتمــد باالمــر الســامي البرقــي رقــم ‪ 43108‬يف‬\n      ‫‪1432/10/2‬ه ـ وبعــد اطالعــي علــى تقريــر احلــادث وجــدت ان تاريــخ‬\n      ‫الواقعــه كان يف ‪1432/11/15‬ه ـ ونظــرا ملــا قــرره اهــل العلــم ان ديــة‬\n      ‫القتــل اخلطــا مؤجلــه علــى ثــاث ســنني مــن حينــه وانهــا علــى العاقلــة‬\n      ‫كمــا يف كشــاف القنــاع ص ‪ 2913‬ويف ص ‪ 2968‬وذلــك لقــول عمــر‬\n      ‫وعلــي رضــي اهلل عنهمــا يف اخلطــا ولــم يعــرف لهمــا مخالــف فــكان‬\n      ‫اجماعــا يف اخــر كل ســنة ثلــث ولكــون واقعــة احلــادث كانــت يف‬\n      ‫‪1431/6/17‬ه ـ وعليــه فقــد حــل كامــل الديــة ولذلــك فقــد حكمــت‬\n      ‫علــى املدعــى عليــه تســليم املدعــن نصــف ديــة مورثهــم مائــه وخمســن‬\n      ‫الــف ريــال ورددت دعــوى املدعــن فيمــا زاد عــن ذلــك وافهمــت املدعــى‬\n      ‫عليــه بــان عليــه كفــارة قتــل اخلطــا عتــق رقبــه مؤمنــه فــان لــم يجــد صــام‬\n      ‫شــهرين متتابعــن اليفصــل بينهمــا بفطــر اال لعــذر مــن مــرض او ســفر‬\n      ‫كمــا افهمتــه بالرجــوع علــى العاقلــة وبعرضــه علــى املدعــي وكالــه قنــع‬\n      ‫بــه وبعرضــه علــى املدعــى عليــه قــرر عــدم القناعــه فافهمتــه بتعليمــات‬\n      ‫االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/20‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬ـ ـ نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة جــرى منــا االطــاع علــى الصــك رقــم‪ 3450453‬وتاريــخ‬\n      ‫‪1434/2/30‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة‬\n      ‫العامــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ‪ ...‬وكالــة ضــد‪ ... /‬يف‬\n      ‫حــادث مــروري ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n\n\n‫‪215‬‬\n\f‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪216‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":209,"source_page_end":216,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9dd8b8b896b158b8d2adde7959c758315c09b04786e08351d675476522f93698","normalized_text_hash":"722ac3a64e8a893223dbbc7858ef662d2891917f164956aa3944bac2afa174d1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p209-3450453"},{"id":"997cc226-3fe1-5582-9d4a-ba4ed4f51e4b","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -دهس بسيارة تسبب يف وفاة -صدور صك من المحكمة بإثبات نسبة اخلطأ على املدعى عليه ودفع الدية -إيداع مبلغ الدية بيت املال يف المحكمة لتسليمها للورثة -مطالبة بيت املال بتسليم مبلغ الدية -إلزام بيت مال المحكمة بتسليم مبلغ الدية املودع به للورثة ما استند إليه القاضي من مبادئ وقواعد العدالة العامة الواردة يف","document_number":"3456993","case_number":"3412850","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة قائا يف دعواه إنه ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"دية -دهس بسيارة تسبب يف وفاة -صدور صك من المحكمة بإثبات نسبة اخلطأ على املدعى عليه ودفع الدية -إيداع مبلغ الدية بيت املال يف المحكمة لتسليمها للورثة -مطالبة بيت املال بتسليم مبلغ الدية -إلزام بيت مال المحكمة بتسليم مبلغ الدية املودع به للورثة ما استند إليه القاضي من مبادئ وقواعد العدالة العامة الواردة يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/7 :‬هـ َر ْق ُم‬\n                              ‫ُ‬                ‫َر ْق ُم َّ‬\n                                  ‫الص ِّك‪3456993 :‬‬\n                                    ‫الدعوى‪3412850 :‬‬\n                 ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 34266053‬تاريخه‪1434/7/11 :‬هـ‬\n\n\n       ‫ديــة‪ -‬دهــس بســيارة تســبب يف وفــاة‪ -‬صــدور صــك مــن احملكمــة بإثبــات‬\n       ‫نســبة اخلطــأ علــى املدعــى عليــه ودفــع الديــة‪ -‬إيــداع مبلــغ الديــة بيــت‬\n       ‫املــال يف احملكمــة لتســليمها للورثــة‪ -‬مطالبــة بيــت املــال بتســليم مبلــغ‬\n       ‫الديــة‪ -‬إلــزام بيــت مــال احملكمــة بتســليم مبلــغ الديــة املــودع بــه للورثــة‬\n\n\n\n\n       ‫مــا اســتند إليــه القاضــي مــن مبــادئ وقواعــد العدالــة العامــة الــواردة يف‬\n                                                                     ‫تســبيب احلكم‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــن بــأن مــورث موكليــه تعــرض حلــادث دهــس ممــا‬\n       ‫تســبب يف وفاتــه وقــد أديــن ســائق الســيارة التــي دهســته بكامــل نســبة‬\n       ‫اخلطــأ فقــام بإيــداع مبلــغ الديــة يف بيــت مــال احملكمــة‪ ،‬ولــذا فقــد‬\n       ‫طلــب احلكــم علــى بيــت املــال بتســليم موكليــه املدعــن ديــة مورثهــم‬\n       ‫املودعــة ‪ -‬طلبــت احملكمــة إفــادة مديــر بيــت املــال فأفــاد بــأن مبلــغ‬\n       ‫ديــة مــورث املدعــن مت إيداعــه يف بيــت مــال احملكمــة كمــا حتققــت‬\n       ‫مــن املســتندات املرفقــة مبلــف القضيــة فوجدتهــا مطابقــة ملــا جــاء يف‬\n       ‫الدعــوى‪ -‬قضــت احملكمــة بثبــوت صحــة الدعــوى وحكمــت علــى‬\n       ‫بيــت مــال احملكمــة بتســليم املدعــي وكالــة املبلــغ املــودع لديهــم كمــا‬\n\n‫‪217‬‬\n\f‫أفهمتــه بالنصيــب الشــرعي لــكل وارث‪ -‬قــررت محكمــة االســتئناف‬\n                      ‫املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 3412850‬وتاريــخ‬\n‫‪ 1434/01/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3459783‬وتاريــخ‬\n‫‪ 1434/01/07‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/03/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 : 45‬وفيهــا حضــر‪ ...........‬مينــي اجلنســية مبوجــب‬\n‫جــواز الســفر رقــم ‪ ...........‬بصفتــه وكيــا عــن ورثــة ‪ ...........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن وزارة العــدل اليمنيــة برقــم ‪ 186‬وتاريــخ‬\n‫‪1433/10/13‬ه ـ واملصــادق عليهــا مــن وزارة اخلارجيــة الســعودية وادعى‬\n‫علــى مديــر بيــت املــال يف احملكمــة العامــة باملدينــة املنــورة قائــا يف‬\n‫دعــواه إنــه بتاريــخ ‪1432/10/9‬ه وقــع حــادث دهــس مــورث موكلــي ‪....‬‬\n‫بشــارع اإلمــام البخــاري يف حــي العزيزيــة باملدينــة املنــورة مــن قبــل ســيارة‬\n‫‪ ...........‬كان يقودهــا احلــدث‪ ...........‬وقــد نتــج عــن احلــادث وفــاة مــورث‬\n‫موكلــي وقــد قــرر رجــال املــرور أن نســبة اخلطــأ كاملــة ‪ %100‬علــى‬\n‫الســائق وقــد صــدر منكــم قــرار شــرعي بذلــك برقــم ‪ 3437916‬يف‬\n‫‪1434/2/16‬ه ـ يتضمــن اثبــات النســبة املذكــورة وحيــث إن الســائق‬\n‫املذكــور قــد أودع مبلــغ الديــة الشــرعي وقــدره ثالثمائــة ألــف ريــال يف‬\n‫بيــت املــال يف احملكمــة لتســليمها للورثــة الشــرعيني فأطلــب احلكــم‬\n‫علــى بيــت املــال بتســليمي املبلــغ املــودع لديهــم وقــدره ثالثمائــة ألــف ريــال‬\n\n                                                                                          ‫‪218‬‬\n\f      ‫هــذه دعــواي وبســؤال املدعــى عليــه مديــر بيــت املال يف احملكمــة العامة‬\n      ‫أجــاب بخطابــه رقــم ‪ 34/549611‬يف ‪1434/3/3‬ه ـ املتضمــن نفيدكم‬\n      ‫أنــه وردنــا مبلــغ ثالثمائــة ألــف ريــال مــن قبــل بإيصــال اســتالم رقــم‬\n      ‫‪ 11/020907‬يف ‪1433/11/14‬ه ـ وذلــك ديــة ‪ .....‬ومــازال املبلــغ موجــود‬\n      ‫لدينــا حتــى تاريخــه هكــذا أجــاب فجــرى االطــاع علــى أوراق املعاملــة‬\n      ‫ومنهــا مــا جــاء يف القــرار الشــرعي املذكــور كمــا جــرى االطــاع علــى‬\n      ‫وثيقــة الوكالــة مــن املدعــي وطلبــت مــن املدعــي وكالــة صــك حصــر‬\n      ‫الورثــة فأبــرزه لدينــا فــاذا هــو صــادر مــن وزارة العــدل اليمنيــة برقــم‬\n      ‫‪ 114‬وتاريــخ ‪1434/10/11‬ه ـ يتضمــن إثبــات انحصــار ورثــة ‪ ....‬بســبب‬\n      ‫حــادث مــروري يف املدينــة املنــورة وخلــف ورثتــه وهــم والــده ‪ ....‬ووالدته ‪....‬‬\n      ‫وزوجتــه ‪ ....‬وولديــه ‪ ...........‬وعمــره خمــس ســنوات ‪ ...........‬وعمــره ثــاث‬\n      ‫ســنوات فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى‬\n      ‫خطــاب مديــر بيــت املــال يف احملكمــة يتضمــن كــون املبلــغ مــودع لديهم‬\n      ‫وبعــد االطــاع علــى القــرار الشــرعي الصــادر منــا وبنــاء علــى مــا تقــدم‬\n      ‫فقــد ثبــت لــدي صحــة الدعــوى وحكمــت علــى بيــت مــال احملكمــة‬\n      ‫بتســليم املدعــي وكالــة املبلــغ املــودع لديهــم وقــدره ثالثمائــة ألــف ريــال‬\n      ‫وبعــرض احلكــم قــرر املدعــي وكالــة القناعــة بــه وقــد أفهمــت املدعــى‬\n      ‫وكالــة بــأن قســمة املبلــغ حســب النصيــب الشــرعي كالتالــي ‪ :‬حيــث‬\n      ‫إن الورثــة هــم والــده ووالدتــه وزوجتــه وولديــه فيكــون نصيــب األب‬\n      ‫وقــدره خمســون ألــف ريــال ونصيــب االم وقــدره خمســون ألــف ريــال‬\n      ‫ونصيــب الزوجــة شــرقة الثمــن وقــدره ســبعة وثالثــون ألفــا وخمســمائة‬\n      ‫ريــال والباقــي يكــون للولديــن بالتســاوي فيكــون نصيــب كل ولــد‬\n      ‫مبلــغ وقــدره واحــد وثمانــون ألفــا ومئتــان وخمســون ريــاال ففهــم ذلــك‬\n\n\n‫‪219‬‬\n\f‫املدعــي وكالــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/7‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/06/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9 : 00‬صباحــا افتتحــت اجللســة وقــد عــادت‬\n‫إلينــا أوراق املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة وبرفقــه‬\n‫قرارهــا رقــم ‪ 34213518‬وتاريــخ ‪1434/5/15‬ه ـ املتضمــن مالحظتهــا‬\n‫باألكثريــة مــا يلــي‪ -1 ( :‬الوكالــة غيــر مصدقــة مــن فــرع وزارة العــدل‬\n‫حســب املتبــع ال ســيما أن فضيلــة حاكــم القضيــة ذكــر أنهــا وثيقــة‬\n‫عندمــا اطلــع عليهــا كذلــك صــك حصــر الورثــة غيــر مصــدق حســب‬\n‫املتبــع يف ذلــك ‪ -2‬لــم يذكــر اســم ممثــل بيــت املــال الــذي صــادق عليــه‬\n‫‪ -3‬لــم يشــر فضيلتــه هــل يحــق للوكيــل املذكــور اســتالم الديــة أو ال‬\n‫‪ -4‬علــى فضيلتــه إعــادة النظــر والتأمــل واإلفــادة هــل ســبق أن أفهــم‬\n‫املتســبب يف الوفــاة بكفــارة القتــل اخلطــأ أو ال )‪ .‬وفيهــا حضــر املدعــي‬\n‫وكالــة وجــرى إعــادة التأمــل يف أوراق القضيــة وقــال املدعــي إننــي ســبق‬\n‫أحضــرت لكــم صكــي الوكالــة وحصــر الورثــة وهمــا مصدقــان‬\n‫مــن وزارة اخلارجيــة الســعودية ومــن فــرع وزارة العــدل يف املدينــة املنــورة‬\n‫كمــا طلبتــم منــي ســابقا فهــذا جــواب املالحظــة األولــى وأمــا عــن جــواب‬\n‫املالحظــة الثانيــة فــإن اســم ممثــل بيــت املــال هــو وأمــا عــن املالحظــة‬\n‫الثالثــة فقــد جــرى بيــان أن للمدعــي حــق اســتالم الديــة احملكــوم بهــا‬\n‫بنــاء علــى الوكالــة الصــادرة لــه وأمــا عــن املالحظــة الرابعــة فإنــه ســبق‬\n‫إفهــام الســائق املتســبب يف الوف ــاة بكفــارة قتــل اخل ـ ــطأ وبــاهلل التوفي ـ ــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محـ ــمد وعلــى آلـ ـ ــه وصحبــه وســلم ‪ .‬ح ـ ــرر يف‬\n                                                                     ‫‪1434/6/24‬ه‪.‬‬\n\n\n                                                                                          ‫‪220‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة باملدينة‬\n      ‫املنــورة والقائــم بعمــل فضيلــة القاضــي اثنــاء فتــرة أجازتــه عليــه ففــي‬\n      ‫هــذا اليــوم الســبت املوافــق‪ 1434/07/29‬ه ـ وحيــث وردة مــن محكمــة‬\n      ‫االســتئناف مشــفوعة بالقــرار رقــم ‪ 34266053‬وتاريــخ ‪1434/7/11‬ه‬\n      ‫املتضمــن وبدراســة القــرار وصــورة ضبطــه تقــررت باملوافقــة علــى‬\n      ‫احلكــم بعــد اإليضــاح األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/29‬ه‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":217,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7373c76e3cf371ed390c6a3b71530b599260451f7a9a7e54d04540fd25141c69","normalized_text_hash":"fdde89f26a889ac26cce6256867af540eded03742af4352b031f388eb8e31825","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p217-3456993"},{"id":"30636b05-ac74-51a4-9b9d-210e6eb05792","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متويف -حادث مروري -سماع الدعوى ضد بيت املال لعدم معرفة القاتل -اإلذن بسماع الدعوى ضد بيت املال -ال يبطل دم امرئ مسلم -احلكم بدفع الدية من بيت املال .","document_number":"345007","case_number":"32145803","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف بالعمل يف املكتب القضائي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/6","year":"1434","subject":"دية متويف -حادث مروري -سماع الدعوى ضد بيت املال لعدم معرفة القاتل -اإلذن بسماع الدعوى ضد بيت املال -ال يبطل دم امرئ مسلم -احلكم بدفع الدية من بيت املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/6 :‬هـ َر ْق ُم‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪345007 :‬‬\n                            ‫الدعوى‪32145803 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3461200‬تاريخه‪1434/3/14 :‬هـ‬\n\n\n‫ديــة متــويف ‪ -‬حــادث مــروري ‪ -‬ســماع الدعــوى ضــد بيــت املــال لعــدم‬\n‫معرفــة القاتــل ‪ -‬اإلذن بســماع الدعــوى ضــد بيــت املــال ‪ -‬ال يبطــل دم‬\n                   ‫امــرئ مســلم ‪ -‬احلكــم بدفــع الديــة مــن بيــت املــال ‪.‬‬\n\n\n\n\n‫‪ .1‬أن النبــي صلــى اهلل عليــه وســلم ودى األنصــاري الــذي قتــل يف خبيــر‬\n                                                               ‫مــن بيــت املــال ‪.‬‬\n‫ا قتــل يف زحــام يف زمــن عمــر فلــم يعــرف قاتلــه فقــال‬\n                                                           ‫‪ .2‬مــا روي أن رجـ ً‬\n‫علــي لعمــر‪ :‬يــا أميــر املؤمنــن ال يبطــل دم امــرئ مســلم فــأدى ديتــه مــن‬\n                                                                     ‫بيــت املــال ‪.‬‬\n‫‪ .3‬اإلذن بســماع الدعــوى الصــادرة مــن نائــب رئيــس مجلــس الــوزراء‬\n                                      ‫برقــم ‪/1451‬م وتاريــخ ‪1432/3/2‬ه ـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي باألصالــة عــن نفســه وبالوكالــة عــن والدتــه وأخيــه‬\n‫الشــقيق وجميــع الــوكاالت والصكــوك مصــادق عليهــا مــن اجلهــات‬\n‫الرســمية وادعــى قائـاً‪ :‬إن مورثــه كان يقطــع أحــد الطــرق يف الريــاض‬\n‫مــن الغــرب إلــى الشــرق وعندمــا وصــل إلــى املســار األيســر قدمــت‬\n‫ســيارة مــن نــوع ( ‪ ) ...‬ال يعــرف لوحتهــا مــن اجتــاه الشــمال إلــى اجلنــوب‬\n\n                                                                                       ‫‪222‬‬\n\f      ‫واصطدمــت مبورثــه ولــم يقــم بإســعافه ويطلــب احلكــم لــه بصــرف الدية‬\n      ‫مــن بيــت املــال ـ بعــرض دعــوى املدعــي وكالــة وأصالــة علــى منــدوب‬\n      ‫وزارة املاليــة طلــب متكينــه مــن االطــاع علــى املعاملــة ‪ -‬تبــن صحــة‬\n      ‫مــا ادعــى بــه املدعــي أصالــة ووكالــة ـ صــدر اإلذن مــن املقــام الســامي‬\n      ‫بســماع الدعــوى ضــد بيــت املــال ‪ -‬مت االطــاع علــى تقريــر املــرور ـ‬\n      ‫احلكــم بإلــزام املدعــى عليــه بدفــع ديــة قتــل اخلطــأ ملــورث املدعــي ـ قــرر‬\n      ‫املدعــي أصالــة ووكالــة قناعتــه باحلكــم وقــرر املدعــي عليــه اعتراضــه‬\n      ‫علــى احلكــم بــدون الئحــة ـ صــدق احلكــم مــن محكمــة االســتئناف‬\n      ‫باألغلبيــة ـ ســلم يف جلســة أخــرى الشــيك للمدعــي أصالــة ووكالــة‬\n                        ‫حيــث إن وكالتــه مخــول لــه فيهــا حــق اســتالم الديــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي باحملكمــة‬\n      ‫العامــة بالريــاض واملكلــف بالعمــل يف املكتــب القضائــي رقــم «‪»35‬‬\n      ‫مــن تاريــخ ‪1433/6/21‬ه ـ ب ــموجب قــرار فضيلــة رئيــس احملكمــة‬\n      ‫رقــم ‪ 331143899‬وتاريــخ ‪1433/06/17‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n      ‫‪1433/80/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 08.15‬وفيهــا حضــر ‪...‬‬\n      ‫باألصالــة عــن نفســه وبالوكالــة عــن والدتــه ‪ ...‬اندونيســية اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة بالريــاض برقــم ‪ 20418‬يف ‪1433/03/14‬ه ـ وبالوكالــة‬\n      ‫عــن ‪ ...‬بخطــاب الوكالــة رقــم ‪ 2012/432508/60‬واملصــادق عليهــا‬\n      ‫مــن عمــدة ناحيــة فســانغان ‪ ...‬ختــم وتوقيــع ومــن رئيــس قريــة فوتــوان‬\n      ‫الوك ‪ ...‬ختــم وتوقيــع وبســؤال املدعــي أصالــة ووكالــة عمــا طلــب منــه‬\n\n‫‪223‬‬\n\f‫يف اجللســة الســابقة مــن تصديــق حصــر الورثــة والوكالــة قــدم حصــر‬\n‫الورثــة والوكالــة مصدقــة مــن قبــل وزارة اخلارجيــة ووزارة العــدل وقــد‬\n‫تضمــن حصــر الورثــة الصــادر مــن احملكمــة الدينيــة ب ـ فاميكاســان‬\n‫املختصــة بالنظــر والفصــل للقضايــا املدنيــة التــي ترفــع أمــام احملكمــة‬\n‫االبتدائيــة بإثبــات األحــكام يف قضيــة طلــب أصــدار صــك حصــر‬\n‫الورثــة واملتضمــن انحصــار ورثــة ‪ ... ...‬بزوجتــه ‪ ...‬و أبنائــه ‪ ...‬و‪... ...‬‬\n‫‪ .‬وحضــر حلضــوره منــدوب بيــت املــال ‪ ...‬مبوجــب خطــاب مديــر عــام‬\n‫اإلدارة القانونيــة بــوزارة املاليــة برقــم ‪ 26719‬وتاريــخ ‪1433/04/28‬ه ـ‬\n‫وادعــى األول بقولــه حصــل علــى مورثنــا حــادث دهــس يف شــارع ‪ ...‬يف‬\n‫حــي ‪ ...‬بالريــاض حيــث كان مورثنــا يقطــع الطريــق مــن الغــرب إلــى‬\n‫الشــرق وعندمــا وصــل إلــى املســار األيســر حيــث قدمــت ســيارة مــن نــوع‬\n‫‪ ...‬أبيــض اللــون ال يعــرف رقــم لوحتهــا مــن اجتــاه الشــمال إلــى اجلنــوب‬\n‫حيــث اصطــدم مبورثنــا ولــم يتوقــف إلســعافه وحيــث لــم يعــرف املتســبب‬\n‫يف احلــادث لــذا نطلــب صــرف الديــة مــن بيــت املــال هــذه دعــواي وبعــرض‬\n‫ذلــك علــى منــدوب بيــت املــال طلــب اإلطــاع علــى املعاملــة وبعــد متكينــه‬\n‫مــن اإلطــاع علــى املعاملــة أجــاب بقولــه نطلــب احلكــم الشــرعي يف‬\n‫القضيــة والنتهــاء وقــت اجللســة رفعــت الســاعة ‪ 08.35‬وحــدد موعــد‬\n‫اجللســة القادمــة يــوم األحــد املوافــق ‪1433/12/19‬ه ـ الســاعة ‪08.30‬‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                          ‫يف ‪1433/08/21‬ه ـ‬\n‫ويف جلســة أخــرى يف يــوم األحــد املوافــق ‪1434/01/04‬ه ـ لــدي أنــا ‪...‬‬\n‫املــازم القضائــي لــدى فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫يف الريــاض افتتحــت اجللســة الســاعة ‪ 10: 15‬وفيهــا حضــر املدعــي‬\n\n\n                                                                                    ‫‪224‬‬\n\f      ‫أصالــة ووكالــة ‪ ...‬إندونيســي اجلنســية املــدون مــا يثبــت هويتــه ووكالتــه‬\n      ‫يف جلســة ســابقة وحضــر حلضــوره منــدوب بيــت املــال ‪ ...‬املــدون مــا‬\n      ‫يثبــت هويتــه يف جلســة ســابقة ومت عــرض الدعــوى علــى املدعــى عليــه‬\n      ‫وكالــة و أجــاب قائــا ‪ :‬اطلــع الوكيــل احلاضــر يف اجللســة الســابقة‬\n      ‫علــى دعــوى املدعــي ومســتنداته وبعــد الرجــوع خلطابــات وزارة الداخليــة‬\n      ‫تبــن لنــا صحــة مــا ذكــره املدعــي أصالــة ووكالــة جملــة وتفصيــا هــذه‬\n      ‫إجابتــي لــذا رفعــت اجللســة الســاعة ‪ 11: 30‬إلــى يــوم الثالثــاء املوافــق‬\n      ‫‪1434/01/06‬ه ـ الســاعة ‪ 11: 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم‬\n         ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬حــرر يف ‪1434/1/4‬ه ـ‬\n      ‫ويف جلســة أخــرى يــوم الثالثــاء املوافق ‪1434/01/06‬هـ افتتحت اجللســة‬\n      ‫‪ 10: 30‬وفيهــا حضــر املدعــي واملدعــى عليــه املفــوض ‪ ...‬املــدون مــا يثبــت‬\n      ‫هويتهمــا يف جلســة ســابقة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومصادقــة املدعــى عليــه املفــوض مــن قبــل بيــت املــال علــى جميــع مــا‬\n      ‫ادعــى بــه املدعــي وبنــاء علــى اإلذن بســماع الدعــوى الصــادرة مــن نائــب‬\n      ‫رئيــس مجلــس الــوزراء برقــم ‪/1451‬م وتاريــخ ‪1432/03/02‬ه ـ وبنــاء‬\n      ‫علــى تقريــر املــرور برقــم ‪ 5414746‬والــذي ينــص علــى هــروب الســائق‬\n      ‫القاتــل وحتملــه مســؤولية احلــادث بنســبة ‪ %100‬وألن النبــي صلــى اهلل‬\n      ‫عليــه وســلم ودى األنصــاري الــذي قتــل يف خيبــر مــن بيــت املــال وملــا روي‬\n      ‫أن رجــا قتــل يف زحــام يف زمــن عمــر فلــم يعــرف قاتلــه فقــال علــي لعمــر‬\n      ‫يــا أميــر املؤمنــن ال يبطــل دم امــرئ مســلم فــأدى ديتــه مــن بيــت املــال‬\n      ‫وعليــه فقــد ألزمــت املدعــى عليــه بدفــع ديــة قتــل اخلطــأ مبلغــا وقــدره‬\n      ‫ثالثمائــة ألــف ريــال لورثــة ‪ ...‬وبــه حكمــت وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــي أصالــة ووكالــة القناعــة بينمــا قــرر املدعــى عليــه‬\n\n\n‫‪225‬‬\n\f‫املفــوض عدمهــا وأقــر قائــا أطلــب رفعهــا لالســتئناف بــدون الئحــة‬\n‫اعتراضيــة هكــذا أقــر وختمــت اجللســة يف متــام الســاعة ‪ 12: 00‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                              ‫‪1434/01/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وقــد صــدق احلكــم مــن الدائــرة اجلزائيــة األولــى لتمييــز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض مبوجــب قرارهــا‬\n‫رقــم ‪ 3461200‬يف ‪ 1434/03/14‬قاضــي اســتئناف ‪ ...‬لــه وجهــة نظــر‬\n‫ختــم وتوقيــع قاضــي اســتئناف د‪ ....‬ختــم وتوقيــع رئيــس الدائــرة ‪ ...‬ختــم‬\n‫وتوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/06‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/7/11‬ه ـ حضــر‬\n‫املدعــي اصالــة ووكالــة بوكالتــه املشــار لهــا ســابق ًا املخولــة لــه حــق‬\n‫اســتالم الديــة واســتلم الشــيك رقــم ‪ 8328770‬يف ‪1434/6/19‬ه ـ‬\n‫املســحوب مــن وزارة املاليــة مببلــغ وقــدره ثالثمائــة ألــف ريــال لصالــح‬\n‫الورثــة املذكوريــن يف الدعــوى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫برقــم ‪ 33552138‬وتاريــخ ‪1434/2/23‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪ .../‬املســجل برقــم‬\n‫‪ 345007‬وتاريــخ ‪1434/1/6‬ه ـ اخلــاص بدعــوى املدعــي ‪ ...‬اصالــة عــن‬\n\n\n                                                                                   ‫‪226‬‬\n\f      ‫نفســه ووكالــة عــن ‪ -1‬والدتــه ‪ ...‬اندونســية اجلنســية ‪ ...-2‬ضــد بيــت‬\n      ‫املــال بشــأن املطالبــة بديــة متوفــى علــى النحــو املوضــح بالصــك املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة وباهلل‬\n                                                                          ‫التوفيــق ‪.‬‬\n\n\n\n\n‫‪227‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":222,"source_page_end":227,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ca3d3d1eecf7f9f812e02676db6b63b83187a9d73cdf6303527bb79a875d72b6","normalized_text_hash":"4d11cdb5b7c8a6c7c7dafa5ac71d5079f41db2429e5d2eaac1b431f4649ea81e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p222-345007"},{"id":"65a3246f-cd49-5a94-a7f3-f86cd30e6a3b","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري -وفاة نتيجة دهس بالسيارة -املطالبة بدية قتل خطأ -إثبات اإلدانة مبوجب تقرير املرور -حتمل املدهوس نسبة من اخلطأ -إلزام املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ","document_number":"3422286","case_number":"32205393","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/26","year":"1434","subject":"دية -حادث مروري -وفاة نتيجة دهس بالسيارة -املطالبة بدية قتل خطأ -إثبات اإلدانة مبوجب تقرير املرور -حتمل املدهوس نسبة من اخلطأ -إلزام املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -إفهام املدعى عليه بأن عليه كفارة قتل اخلطأ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/26 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3422286 :‬‬\n                              ‫الدعوى‪32205393 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34318301‬تاريخه‪1434/9/14 :‬هـ‬\n\n\n   ‫ديــة ‪ -‬حــادث مــروري ‪ -‬وفــاة نتيجــة دهــس بالســيارة ‪ -‬املطالبــة بديــة‬\n   ‫قتــل خطــأ ‪ -‬إثبــات اإلدانــة مبوجــب تقريــر املــرور ‪ -‬حتمــل املدهــوس‬\n   ‫نســبة مــن اخلطــأ ‪ -‬إلــزام املدعــى عليــه بدفــع الديــة مقابــل نســبة‬\n   ‫اخلطــأ التــي عليــه ‪ -‬إفهــام املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ‬\n                                                                                    ‫‪.‬‬\n\n\n\n\n   ‫‪ -1‬قولــه تعالــى ‪ ( :‬ومــا كان ملؤمــن أن يقتــل مؤمنــا إال خطــأ ومــن‬\n   ‫قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه إال أن‬\n                                                                      ‫يصدقــوا) ‪.‬‬\n   ‫‪ -2‬القاعــدة ‪ ( :‬أن كل مــن أتلــف إنســان ًا مبباشــرة أو تســبب فإنــه ملــزم‬\n                                                                         ‫بديتــه ) ‪.‬‬\n\n\n\n\n   ‫ادعــى وكيــل الورثــة علــى املدعــى عليــه بأنــه تســبب يف وفــاة مــورث‬\n   ‫موكلــه عــن طريــق دهســه بالســيارة ‪ -‬طلــب إلــزام املدعــى عليــه بدفــع‬\n   ‫الديــة ‪ -‬صــادق املدعــى عليــه علــى الدعــوى وقــرر املدعــى عليــه بأنــه‬\n   ‫كان يســير يف طريقــه عنــد إحــدى اإلشــارات بســرعة منخفضــة وكان‬\n   ‫يف أقصــى اليمــن وكان املتوفــى متجهــا نحــو الســيارة ولــم يــره حتــى‬\n\n                                                                                        ‫‪228‬‬\n\f      ‫ســمع صــوت االصطــدام ‪ -‬قــرر املدعــى عليــه بــأن املــرور حمــل مــورث‬\n      ‫املدعــن النســبة األكبــر مــن اخلطــأ ‪ -‬قــرر املدعــى عليــه اســتعداده‬\n      ‫بدفــع الديــة مقابــل نســبة اخلطــأ التــي عليــه ‪ -‬جــرى رجــوع القاضــي إلــى‬\n      ‫تقريــر احلــادث الصــادر مــن املــرور املتضمــن إدانــة مــورث املدعــن بنســبة‬\n      ‫‪ %75‬وإدانــة املدعــى عليــه بنســبة ‪ - %25‬صــدر احلكــم بإلــزام املدعــى‬\n      ‫عليــه بدفــع ديــة مــورث املدعــن مقابــل نســبة اخلطــأ التــي عليــه خمســة‬\n      ‫وســبعني ألــف ريــال ‪ -‬إفهــام املدعــى عليــه بــأن عليــه كفــارة قتــل اخلطــأ‬\n                                   ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي يف احملكمة اجلزائية بخميس‬\n      ‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط برقــم ‪ 32205393‬وتاريــخ ‪ 1432/06/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 32639797‬وتاريــخ ‪ 1432/06/01‬ه ـ ففــي‬\n                 ‫يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10 : 00‬وفيهــا حضــر ‪...‬مينــي اجلنســية مبوجــب جــواز الســفر رقــم‬\n      ‫‪...‬حلضــوره ‪...‬ســعودي اجلنســية ســجل مدنــي رقــم ‪...‬وقــد حضــر ‪...‬وكالــة‬\n      ‫عــن ورثــة املتوفــى ‪...‬وهــم كال مــن والــده ‪...‬ووالدته‪...‬كمــا هــو مبــن يف‬\n      ‫انحصــار اإلرث الصــادر مــن محكمــة الزهــرة االبتدائيــة بالرقــم ‪30‬‬\n      ‫واملصــدق مــن اجلهــات الرســمية وأخرهــا وزارة العــدل برقــم ‪ 2048‬يف‬\n      ‫‪ 1433/3/16‬وذلــك بالوكالــة عــن وارثــي املتــويف بالوكالــة رقــم ‪218‬‬\n      ‫واملتضمــن توكيــل املدعــي يف املطالبــة واســتالم كل مــا وجــب لهــم مــن‬\n      ‫حــق خــاص مقابــل وفــاة ولدهــم ‪ ...‬علــى اثــر احلــادث املــروري الذي تعرض‬\n\n‫‪229‬‬\n\f‫لــه يف محافظــة صامطــة وادعــى قائــا‪ :‬إن هــذا احلاضــر ‪...‬قــد تســبب يف‬\n‫وفــاة مــورث موكلــي دهســا يف محافظــة صامطــة وأطلــب إلزامــه بدفــع‬\n‫الديــة الشــرعية للمتوفــى هكــذا ادعــى وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه أجــاب قائــا‪ :‬مــا جــاء يف دعــوى املدعــي وكالــة صحيــح فقــد‬\n‫كنــت أســير يف طريقــي عنــد إحــدى اإلشــارات وســرعتي ثالثــن تقريبــا‬\n‫وكنــت يف أقصــى اليمــن وقــد كان املتوفــى متجهــا نحــو الســيارة ولــم‬\n‫أره حتــى ســمعت صــوت اإلصطــدام وقــد قــرر املــرور إدانتــي بنســبة ‪%25‬‬\n‫وأنــا مقتنــع بهــا هكــذا أجــاب ‪ .‬وإلنتهــاء وقــت اجللســة فقــد رفعتهــا‬\n‫وحــددت لهــا موعــدا يف يــوم األحــد املوافــق ‪1434/5/26‬ه ـ ‪ .‬أقفلــت‬\n‫اجللســة يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/25‬هـ‬\n‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي يف احملكمة اجلزائية بخميس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بخميــس مشــيط برقــم ‪ 32205393‬وتاريــخ ‪1432/06/01‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32639797‬وتاريــخ ‪ 1432/06/01‬ه ـ‬\n‫ففــي يــوم األحــد املوافــق‪ 1434/05/26‬ه ـ افتتحــت اجللســة الســاعة‬\n‫احلاديــة عشــرة والنصــف وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وجــرى اإلطــاع علــى أوراق املعاملــة ومــا جــاء يف طياتهــا ومــا جــاء يف‬\n‫تقريــر احلــادث رقــم ‪ 7/32800027/30‬واملرفــق باملعاملــة لفــه رقــم ‪11‬‬\n‫واملتضمــن توجيــه املســئولية للمدعــى عليــه بنســبة ‪ %25‬وذلــك لعــدم‬\n‫انتباهــه أثنــاء القيــادة وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى إقــرار املدعــى عليــه بنســبة دعــس املتوفــى ‪...‬بالوصــف املذكــور‬\n‫يف التقريــر املــروري واقتناعــه بالنســبة املروريــة وهــي ‪ %25‬وملــا كان‬\n\n\n                                                                                         ‫‪230‬‬\n\f      ‫حــادث الدعــس بســبب خطــأ كل مــن الســائق واملاشــي فــإن الضمــان‬\n      ‫بالنســبة املذكــورة متوجــه علــى املدعــى عليــه ملــا ذكــر مــن أســباب يف‬\n      ‫رأي أهــل اخلبــرة املتقــرر فقهــا اعتبــاره والرجــوع إليــه يف مثــل هــذه احلــال‬\n      ‫ومبــا أن احلــادث نتــاج فعــل املدعــى عليــه مبباشــرته للدعــس فالقاعــدة‬\n      ‫أن كل مــن أتلــف إنســانا مبباشــرة أو تســبب فإنــه ملــزم بديتــه ولقــول‬\n      ‫اهلل تعالــى (ومــا كان ملؤمــن أن يقتــل مؤمنــا إال خطــأ ومــن قتــل مؤمنــا‬\n      ‫خطــأ فتحريــر رقبــة مؤمنــة وديــة مســلمة إلــى أهلــه إال أن يصدقــوا)‬\n      ‫لــذا فقــد قــررت إلــزام املدعــى عليــه بدفــع مبلــغ وقــدره خمســة وســبعون‬\n      ‫ألــف ريــال تســلم لوكيــل ورثــة املتوفــى هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫وأفهمــت املدعــي أن هــذا املبلــغ يكــون نصيــب األم منــه إن لــم يكــن‬\n      ‫لــه جمــع مــن األخــوة الثلــث وإن كان لــه جمــع مــن األخــوة فنصيبهــا‬\n      ‫الســدس ويف احلالتــن مــا تبقــى يكــون لــأب وبعرضــه علــى املدعــي‬\n      ‫قــرر قناعتــه باحلكــم وبعرضــه علــى املدعــى عليــه قــرر عــدم قناعتــه‬\n      ‫باحلكــم وطلــب رفعــه إلــى محكمــة اإلســتئناف بــدون الئحــة أقفلــت‬\n      ‫اجللســة يف متــام الســاعة الثانيــة عشــر ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/26‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫مبنطقة ‪...‬بخطاب فضيلة رئيسها رقم ‪ 341352239‬يف ‪1434/7/11‬هـ‬\n      ‫واملرفــق بــه قــرار املالحظــة رقــم ‪ 34244151‬يف ‪1434/6/18‬ه ـ‬\n      ‫واملتضمــن أنــه لوحــظ مــا يلــي أوال‪ :‬حكــم فضيلتــه بثبــوت إدانــة املدعــى‬\n      ‫عليــه ‪...‬بدهــس املدعــو‪... /‬بنســبة ‪ %25‬ولــم جنــد أن فضيلتــه أفهمــه أن‬\n      ‫عليــه كفــارة قتــل اخلطــأ رغــم استشــهاده بنــص القــرآن وال بــد مــن ذلك ‪.‬‬\n      ‫ثانيــا‪ :‬صــورة الوكالــة وحصــر اإلرث لــم يصــدق فضيلتــه عليهــا بأنــه مت‬\n\n\n‫‪231‬‬\n\f‫اإلطــاع عليهــا ووجــدت مطابقــة لألصــل حســب مــا نــص عليــه النظــام‬\n‫‪ .‬ثالثــا‪ :‬يكتفــى بتدويــن اســم القاضــي يف مســتهل الضبــط وقــراره‬\n‫الشــرعي والصــك دون التكــرار يف كل جلســة عمــا بالتعليمــات ‪.‬‬\n‫وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل علــى املالحظــة األولــى‬\n‫بأنــه جــرى إفهــام املدعــى عليــه بــأن عليــه كفــارة القتــل اخلطــأ أثنــاء‬\n‫اجللســة وقــد تــرك ضبطهــا ســهوا وســيتم تــدارك ذلــك مســتقبال إن شــاء‬\n‫اهلل ‪ .‬وأمــا الثانيــة فقــد جــرى املصادقــة علــى صــور الــوكاالت وحصــر‬\n‫اإلرث والثالثــة متــت إضافتــه أثنــاء التنســيق ســهوا وســيتم مالحظــة ذلــك‬\n‫مســتقبال إن شــاء اهلل وبهــذا متــت إجابــة أصحــاب الفضيلــة وفقهــم اهلل‬\n‫واختتمــت اجللســة الســاعة احلاديــة عشــر والنصــف ‪ .‬واهلل املوفــق وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‪... ...‬علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط‬\n‫املســاعد برقــم ‪ 341766963‬وتاريــخ ‪1434/8/7‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪... /‬برقــم ‪...‬وتاريــخ‬\n‫‪1434/5/26‬ه ـ اخلــاص بدعــوى ‪( ... ... /‬مينــي اجلنســية) وكالــة ضــد‬\n‫‪... /‬يف قضيــة (مطالبــة بديــة متوفــى يف حــادث مــروري) علــى الصفــة‬\n‫املوضحــة يف الصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n‫ـاء علــى قرارنــا‬\n                ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n‫رقــم ‪ 34244151‬وتاريــخ ‪1434/6/18‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                              ‫وصحبــه وســلم ‪.‬‬\n                                                                                    ‫‪232‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":228,"source_page_end":232,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0fd25d61872c0b11e98479f35907daab4278f5f977260796cb18283744fc675","normalized_text_hash":"d714e55cbb63e43dfc7e5b730c87e482545daba3d7c137cef7b1df9c0488d0ec","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p228-3422286"}]$archive_payload$::jsonb) AS x LIMIT 25
